UPDATE public.healthcare_providers SET name_ar = COALESCE(name_ar, 'د. آرزو أيوبوفا'), specialty_ar = COALESCE(specialty_ar, 'اختصاصية الغدد الصماء'), description_ar = COALESCE(description_ar, 'الخبرة: 30 عامًا
اللغات: اللغة الأذربيجانية
التعليم: جامعة أذربيجان الحكومية للطب
مجالات الاهتمام: أمراض جهاز الغدد الصماء، أمراض جهاز الغدد الصماء، أمراض جهاز الغدد الصماء، أمراض جهاز الغدد الصماء، أمراض جهاز الغدد الصماء، أمراض جهاز الغدد الصماء، أمراض جهاز الغدد الصماء، أمراض جهاز الغدد الصماء، أمراض جهاز الغدد الصماء، أمراض جهاز الغدد الصماء
الخدمات: متابعة الغدد الصماء قبل الحمل وخلاله، تقييم توازن فيتامين D والكالسيوم والفوسفور، إعداد خطط علاج ومتابعة فردية، فحوصات وقائية للغدد الصماء، تشخيص أمراض الغدة الكظرية والغدة النخامية، المتابعة طويلة الأمد للمرضى، متابعة أمراض الغدد جارات الدرقية، التقييم الهرموني لاضطرابات الكوليسترول والدهون، تشخيص هشاشة العظام وعلاجها، التقييم الهرموني خلال مرحلة انقطاع الطمث، علاج متلازمة تكيس المبايض والاضطرابات الهرمونية، تشخيص أمراض جهاز الغدد الصماء، الإحالة لإجراء خزعة من الغدة الدرقية، تقييم مخاطر عقيدات الغدة الدرقية، فحص أمراض الغدة الدرقية وعلاجها، تفسير نتائج التصوير بالموجات فوق الصوتية والفحوصات المخبرية، تقييم تحاليل الهرمونات، علاج الوزن الزائد والسمنة، تطبيق علاج GLP-1 ومتابعته، تقييم مقدمات السكري ومقاومة الإنسولين، إدارة داء السكري ووضع خطة للعلاج بالإنسولين

تُعد الطبيبة الاختصاصية آرزو أيوبوفا خبيرة متمرسة في مجال الغدد الصماء، ومتخصصة في تشخيص أمراض الجهاز الهرموني وعلاجها ومتابعتها على المدى الطويل. تعمل حاليًا في مدينة باكو، وتقدم للمرضى رعاية طبية تستند إلى أحدث الأساليب في طب الغدد الصماء. تشمل مجالات عملها الرئيسية تشخيص وعلاج داء السكري من النوعين 1 و2، ومقدمات السكري، ومقاومة الإنسولين، وأمراض الغدة الدرقية، وتضخم الغدة الدرقية، والاضطرابات الهرمونية، والسمنة، ومتلازمة الأيض، وغيرها من أمراض جهاز الغدد الصماء. وتعتمد في العلاج نهجًا فرديًا لكل مريض بهدف تحقيق نتائج صحية مستدامة على المدى الطويل. تركز الطبيبة الاختصاصية آرزو أيوبوفا بصورة خاصة على إدارة داء السكري، وضبط العلاج بالإنسولين، وتقييم مشكلات الغدة الدرقية، واستعادة التوازن الهرموني. ويُعد تحسين جودة حياة مرضاها والكشف المبكر عن الأمراض من أهم محاور ممارستها المهنية. كما تتابع عن كثب المستجدات الطبية الحديثة والتوصيات الدولية في طب الغدد الصماء، وتقدم لمرضاها نهجًا علاجيًا موثوقًا ومخصصًا قائمًا على الأدلة العلمية. تستقبل مرضاها حاليًا في Universal Hospital بمدينة باكو.'), address_ar = COALESCE(address_ar, 'Universal Hospital، شارع جعفر خندان 196، باكو، أذربيجان') WHERE id = '603d7801-444c-4f6c-a59a-6329d9cd6775';
UPDATE public.healthcare_providers SET name_ar = COALESCE(name_ar, 'د. زينب شاغيدولينا'), specialty_ar = COALESCE(specialty_ar, 'اختصاصية أمراض النساء والتوليد'), description_ar = COALESCE(description_ar, 'الخبرة: 21 عامًا
اللغات: اللغة الأذربيجانية
التعليم: جامعة كوبان الحكومية للطب
