-- ── mommy_daily_messages → ar (1459 sətir) ──
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'قد تكون أظافر رضيعكِ رقيقة كالورق، لكنها حادة كشفرة الحلاقة، وقد يخدش وجهه ويؤذي نفسه بحركاته اللاإرادية. قد يبدو قص أظافره أمرًا مرهقًا جدًا، وأسهل طريقة للقيام بذلك هي قصها بحذر باستخدام مقص خاص للأطفال حين يكون رضيعكِ في نوم عميق. تفضّل بعض الأمهات استخدام القفازات، لكن رضيعكِ يتعرّف إلى العالم من خلال تحسّسه بيديه، وقد يؤدي إبقاء يديه مغطاتين إلى إبطاء نموه وإعاقة آليته لتهدئة نفسه. لا تخافي، فحتى إذا تسببتِ له بجرح صغير عن طريق الخطأ، يكفي الضغط عليه بقطعة قطن نظيفة وسيلتئم سريعًا؛ كوني شجاعة!') WHERE id = '3eb8e784-2dc2-4db5-bcf8-7391a821ce01';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'قد تشعرين أحيانًا خلال فترة ما بعد الولادة هذه بأنكِ معزولة عن العالم، وكأنكِ "روبوت" لا يفعل سوى إرضاع طفلكِ وتغيير حفاضاته. لكن تذكّري أنكِ لستِ أمًا فحسب، بل أنتِ أيضًا صديقة وزوجة وإنسانة لها اهتماماتها. اليوم، عندما ينام طفلكِ، اتصلي بإحدى صديقاتكِ، أو اقرئي شيئًا ممتعًا على وسائل التواصل الاجتماعي، أو انظري ببساطة من النافذة وقولي: "أنا هنا وكل شيء على ما يرام". صحتكِ النفسية لا تقل أهمية عن صحتكِ الجسدية؛ وإذا كنتِ تشعرين بالعزلة، فشاركي هذه المشاعر مع المقرّبين منكِ، فالحديث سيخفف عنكِ العبء.') WHERE id = 'e0cd0853-270f-4ca4-a662-76294120406b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لا تقلقي إذا بدا رضيعكِ في هذه الأيام وكأنه لا يشبع من الحليب أبدًا، ويطلب الرضاعة باستمرار ويضطرب نومه؛ فغالبًا ما تكون هذه "طفرة نمو الأسبوع الثالث" (growth spurt). خلال هذه الفترة ينمو جسم رضيعكِ بسرعة، ولذلك يحتاج إلى مزيد من الطاقة، بينما يحاول جسمكِ إنتاج مزيد من الحليب للتكيف مع هذا الطلب. أكبر خطأ ترتكبه الأمهات في هذه المرحلة هو الانتقال إلى الحليب الصناعي ظنًا منهن أن "حليبي قد انقطع"؛ بل هي أزمة مؤقتة، والحل الوحيد هو إرضاع طفلكِ كلما طلب ذلك ومن دون التقيد بمواعيد محددة. تحلّي بالصبر، فعادةً ما تنتهي هذه الفترة المرهقة خلال 24-48 ساعة، ثم تتكيّف كمية حليبكِ مجددًا.') WHERE id = '2fdd98da-1e6c-412b-96b1-b850d42327b4';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'قد تلاحظين فجأة ظهور طفح جلدي أحمر صغير أو بثور على وجه رضيعكِ الناعم كالحرير؛ فلا تبدئي فورًا بلوم نفسكِ قائلة: "ماذا أكلتُ حتى حدث هذا لطفلي؟". يُسمى ذلك "حب شباب حديثي الولادة"، وهو جزء من عملية تخلّص جسم رضيعكِ من الهرمونات التي انتقلت إليه منكِ خلال الحمل. هذا الطفح ليس حساسية، لذلك يُمنع تمامًا عصره أو وضع الكحول أو الكريمات المختلفة عليه، إذ قد يؤدي ذلك إلى تضرر البشرة فحسب. يكفي مسح وجهه يوميًا بماء مغلي فاتر، وسيختفي الطفح من تلقاء نفسه خلال بضعة أسابيع.') WHERE id = 'c3f99f3b-1467-413f-94c0-72c3e11f5099';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'قد تبلغ نوبات البكاء المعروفة (المغص)، التي تبدأ مساءً وتستمر ساعات، ذروتها خلال هذه الفترة؛ وعندها جرّبي استخدام "الضوضاء البيضاء" (white noise) لتهدئة رضيعكِ. كان رضيعكِ يسمع باستمرار داخل الرحم أصوات تدفق الدم والأعضاء، ولذلك تبدو له أصوات مجفف الشعر والمكنسة الكهربائية أو تطبيقات "الضوضاء البيضاء" على الهاتف مألوفة وتمنحه شعورًا بالأمان. قد يساعد احتضان رضيعكِ بإحكام وهزّه بإيقاع منتظم مع إسماعه هذه الأصوات على تهدئة جهازه العصبي. تذكّري أن هذا البكاء ليس خطأكِ، بل هو مجرد استجابة من جهاز رضيعكِ الهضمي الذي لم يكتمل نموه بعد.') WHERE id = '401736ab-8891-41f0-a7a6-17ce6782e7e4';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'بدأت قدرة رضيعكِ على الإبصار تتطور، لكنه لا يزال غير قادر على تمييز الألوان بالكامل، ويرى العالم غالبًا على هيئة ظلال ضبابية. يمكنكِ استخدام بطاقات بالأبيض والأسود أو ألعاب ذات تباين لوني قوي لجذب انتباهه ودعم نمو دماغه؛ ويجب إمساكها على بُعد نحو 20-30 سم من وجهه. ستلاحظين أنه يثبّت نظره على هذه البطاقات ويتابعها باهتمام. لا يدرّب هذا اللعب البسيط عضلات عينيه فحسب، بل يساعد أيضًا على تكوين روابط جديدة بين خلايا الدماغ (الخلايا العصبية).') WHERE id = '6acb903b-f503-4e0a-bf5a-5cedae1d83e4';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'قد يشير بكاء رضيعكِ دون سبب واضح في ساعات المساء، وضمّ ساقيه إلى بطنه واحمرار وجهه، إلى بدء آلام الغازات (المغص)؛ وهذا يعني أن جهازه الهضمي لم يكتمل نموه بعد. لا تقلقي، فهذه الآلام لا تعني وجود مشكلة في صحة رضيعكِ، بل يحتاج فقط إلى بعض المساعدة؛ سيساعد تدليك بطنه بلطف باتجاه عقارب الساعة أو تحريك ساقيه كأنه يقود دراجة على تهدئته. وقد يخفف المغص أيضًا حمله منبطحًا على ذراعكِ والمشي به (وضعية النمر). تحلّي بالصبر، فقد تبدو لكِ هذه الفترة وكأنها «ليالٍ لا تنتهي»، لكن هذه الآلام ستختفي تمامًا بعد 3-4 أشهر.') WHERE id = 'bcbaede0-1b13-4f10-af2e-89c520ee8eac';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تهانينا، لقد بلغ رضيعكِ الآن أسبوعين كاملين! خلال هذه الفترة، يصف الأطباء عادةً قطرات فيتامين D للرضع، فعلى الرغم من أن حليب الأم غذاء مثالي، فإن كمية فيتامين D فيه لا تكون كافية عادةً، كما قد لا يكون التعرض لأشعة الشمس كافيًا دائمًا. لا تنسي إعطاءه الفيتامين بالجرعة التي وصفها طبيبكِ لضمان نمو عظامه نموًا سليمًا والوقاية من الكساح. وهذا أيضًا وقت مناسب لإجراء الفحص الطبي الأول؛ يمكنكِ حجز موعد مع طبيب الأطفال للتحقق من زيادة وزن رضيعكِ وطرح أسئلتكِ حول نموه وتطوره. أنتِ تقومين بعمل رائع، وقد اجتزتِ أول مرحلة صعبة!') WHERE id = '6f0bc18f-ecc7-4ad9-915b-db7cdf9694f7';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لنُعِد اليوم بعض الاهتمام إلى جسدكِ؛ يُفترض أن تبدأ إفرازات ما بعد الولادة (الهلابة) في التحول تدريجيًا إلى لون أفتح أو مائل إلى الصفرة أو الأبيض. إذا ازداد النزيف فجأة أو ظهرت رائحة كريهة، فقد تكون هذه رسالة من جسدكِ بأنكِ «تجهدين نفسكِ كثيرًا» أو أن «هناك عدوى»؛ لذلك تجنبي تمامًا رفع الأشياء الثقيلة. اهتمي بنظافتكِ الشخصية جيدًا، فالاستحمام بانتظام مهم للنظافة الجسدية وتحسين حالتكِ النفسية. تذكّري أن تعافيكِ الكامل سيستغرق بضعة أسابيع أخرى، لذا امنحي جسدكِ الوقت والرفق حتى إن لم تشعري بعد بأنكِ استعدتِ كامل نشاطكِ.') WHERE id = '924b5e58-de0f-4e99-ae9e-3a1b97775596';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'قواعد النوم الآمن بالغة الأهمية لحماية حياة رضيعكِ؛ احرصي دائمًا على وضعه للنوم على ظهره فوق مرتبة صلبة. قد تؤدي الوسائد الناعمة والبطانيات السميكة أو الألعاب داخل السرير، التي قد تنصح بها الجدات، إلى تعريض رضيعكِ لخطر الاختناق، لذلك اجعلي مهده بسيطًا وفارغًا قدر الإمكان. غالبًا لا تكون هناك حاجة إلى الوسائد الطبية الخاصة المستخدمة «للحفاظ على استدارة الرأس»، إذ يجب أن يتمكن رضيعكِ من تحريك رأسه بحرية. حافظي على درجة حرارة الغرفة ضمن نطاق مناسب (20-22 درجة مثالية)، وتجنبي إلباسه ملابس سميكة أكثر من اللازم، لأن فرط الحرارة يشكل أيضًا خطرًا أثناء النوم.') WHERE id = '00815f0c-e81b-4156-a3e1-eda10e9b02f3';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'ربما سمعتِ عن أهمية وضع رضيعكِ على بطنه أثناء استيقاظه (وقت الاستلقاء على البطن)، لكنه قد لا يحب ذلك إطلاقًا ويبدأ بالبكاء فورًا. هذا طبيعي، لكن لا تستسلمي؛ فالمحاولة عدة مرات يوميًا، لمدة 1-2 دقيقة فقط في كل مرة، لا تُقدّر بثمن لتقوية عضلات رقبته وكتفيه وذراعيه. كما أنها الطريقة الطبيعية الأفضل للوقاية من تسطح مؤخرة الرأس (الرأس الوارب). ولجعل هذا الوقت ممتعًا، يمكنكِ وضع مرآة أو بطاقات بالأبيض والأسود أمامه، بل ويمكنكِ الاستلقاء على الأرض بجانبه والتواصل معه بعينيكِ.') WHERE id = '442f3095-2fe9-4071-b81b-22bb923583fd';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'إن مقولة «لا يخرج الطفل من المنزل قبل إتمام الأربعين يومًا» ليست سوى خرافة قديمة؛ فإذا كان الطقس مناسبًا وكان رضيعكِ بصحة جيدة، فسيكون الهواء النقي مفيدًا لكما كالعلاج. قد يكون الهواء الراكد والغبار والبكتيريا داخل المنزل أكثر ضررًا من الهواء النقي في الخارج؛ لكن ابتعدي عن مراكز التسوق المزدحمة والأماكن المغلقة. عند إلباس رضيعكِ، يكفي أن تضيفي طبقة واحدة فقط فوق ما ترتدينه أنتِ؛ فتغطيته بطبقات كثيرة «كالملفوف» قد تسبب تعرّقه ومرضه. ستُحسّن نزهة قصيرة مزاجكِ وتساعد رضيعكِ على النوم بعمق أكبر.') WHERE id = '0f0e26dc-de3c-4b42-ba38-4351bd00e821';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحبًا بكِ أيتها الأم العزيزة! اليوم تُفتح صفحة جديدة، وربما الأكثر إثارة، في حياتكِ. أهم ما عليكِ الآن هو أن تستريحي وتبدئي أول تلامس جسدي مع طفلكِ؛ فالأعمال المنزلية والمكالمات الهاتفية والضيوف يمكنهم الانتظار. اعلمي أن ذلك الحليب الكثيف المائل إلى الصفرة الذي يفرزه ثدياكِ في الأيام الأولى (اللبأ)، رغم قلة كميته، يتمتع بتركيبة مذهلة ويؤدي دور اللقاح الأول لطفلكِ. لا تخافي من أن يكون حليبكِ قليلًا، فمعدة طفلكِ لا تزال بحجم حبة كرز، وتلك القطرات تكفيه تمامًا. لا تحاولي التظاهر بالقوة، فمن الطبيعي تمامًا أن تشعري بالألم والإرهاق. ما عليكِ سوى الاستلقاء واستنشاق رائحة طفلكِ والشعور بدفئه والاستمتاع بهذه اللحظة، لأن أساس الرابطة بينكما يُبنى الآن.') WHERE id = 'ced035b3-8303-4f5d-95fd-7e29e2539509';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لقد أنجز جسمكِ عملًا رائعًا طوال 9 أشهر، وبدأت أعضاؤكِ الداخلية الآن تعود ببطء إلى مواضعها. قد تشعرين بتقلصات أسفل بطنكِ، خاصة أثناء الرضاعة الطبيعية؛ لا تقلقي، فهذه علامة إيجابية على انقباض الرحم وعودته إلى حجمه السابق. لا تنجرفي وراء الأفكار الخاطئة الشائعة مثل: "حليبي قليل، وطفلي لا يشبع، ولهذا يبكي". قد يطلب طفلكِ الرضاعة كثيرًا، ليس لأنه جائع فحسب، بل أيضًا ليشم رائحتكِ ويسمع دقات قلبكِ ويشعر بالأمان. امنحيه هذا الشعور بالطمأنينة، واحمليه بين ذراعيكِ وأرضعيه كثيرًا؛ وتذكّري أن كمية حليبكِ ستزداد كلما رضع طفلكِ.') WHERE id = 'f5dc2c0a-cfb4-4205-ad61-5a643545c576';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'قد يبدأ ثدياكِ في هذه الأيام بالامتلاء بالحليب، ما قد يسبب شعورًا بالثقل والسخونة فيهما. وفي الوقت نفسه، قد تشعرين بالحزن أو الرغبة في البكاء أو العصبية من دون سبب واضح نتيجة التغير الحاد في مستويات الهرمونات في جسمكِ؛ وتُعرف هذه الحالة طبيًا باسم "كآبة النفاس العابرة". لا تعني هذه المشاعر أنكِ "أم سيئة" أو غير قادرة، بل هي مجرد عملية فسيولوجية مؤقتة. لا تحبسي دموعكِ؛ فإذا رغبتِ في البكاء، فأطلقي العنان لمشاعركِ ولا تترددي في التحدث عنها مع المقرّبين منكِ. أنتِ لستِ وحدكِ، فآلاف الأمهات يعشن هذه المرحلة الانتقالية مثلكِ؛ خذي نفسًا عميقًا ودعي الوقت يمضي بهدوء.') WHERE id = '04d25f7c-e375-4514-ac39-dc2728da56e3';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لاستعادة طاقتكِ، عليكِ الاهتمام بتغذيتكِ جيدًا، لكن ضعي جانبًا المحظورات القديمة مثل "ستصابين بالبرد" و"لا تأكلي الفاكهة" و"لا تشربي الماء". إن تناول غذاء متنوع غني بالفيتامينات وشرب الكثير من السوائل مهمان لاستعادة قوتكِ الجسدية وحيويتكِ النفسية أكثر من أهميتهما لجودة حليبكِ. أما الحبل السري لطفلكِ، فلا حاجة إلى تطهيره بالكحول أو تغطيته. احرصي فقط على إبقائه جافًا ونظيفًا، وعند إلباس طفلكِ الحفاض اتركي منطقة السرة مكشوفة لتتعرض للهواء؛ فالتهوية من أفضل الوسائل لتسريع الالتئام.') WHERE id = '5cdec801-b16c-449e-bf65-9a37a9e133f1';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحبًا بكِ أيتها الأم القوية في الأيام التي يختلط فيها الليل بالنهار ويظهر فيها أثر الحرمان من النوم! قد يقول لكِ المحيطون: "لا تعوّدي طفلكِ على الحمل بين ذراعيكِ"، لكن اعلمي أنه لا يمكن "تدليل" الرضيع أكثر من اللازم خلال الأشهر الأولى. إنه يحتاج إليكِ، وحمله والتلامس المباشر بين بشرتكِ وبشرته من أكثر الطرق فاعلية في دعم نمو دماغه وزيادة إدرار حليبكِ. الأعمال المنزلية لن تهرب، ولا بأس إن بقيت الأطباق من دون غسل، لكن نومكِ وراحتكِ أهم من كل شيء. حاولي إغماض عينيكِ والاستراحة بمجرد أن ينام طفلكِ؛ فحتى قيلولة مدتها 15 دقيقة ستمنحكِ بعض الطاقة.') WHERE id = '726dd7ee-a857-41fc-aad0-622f7b5ddf29';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لستِ مضطرة إلى فعل كل شيء بمفردكِ أو الظهور بصورة "الأم الخارقة"؛ فطلب المساعدة ليس ضعفًا، بل دليل على القوة. اطلبي من زوجكِ أو والدتكِ أو المقرّبين منكِ المساعدة في مهام محددة، مثل إحضار الطعام أو الاعتناء بطفلكِ بينما تستحمين. إن الاعتناء بنفسكِ والاغتسال واحتساء كوب من الشاي الساخن ليس أنانية، بل ضرورة تساعدكِ على أداء دوركِ كأم بصورة أفضل. تذكّري أن الأم السعيدة والمستريحة تعني طفلًا سعيدًا، لذلك لا تترددي في تقاسم أعبائكِ مع الآخرين.') WHERE id = '1ddced84-3654-418b-9996-21c50802a72f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'إذا أتعبتكِ المحظورات الغذائية الشائعة في مجتمعنا، مثل «لا تأكلي الطماطم حتى لا يتأذى طفلكِ» أو «لا تأكلي العدس حتى لا يُصاب طفلكِ بالغازات»، فاعلمي أن الطب الحديث لا يؤيد هذه المعتقدات. فالغازات الموجودة في الطعام الذي تتناولينه لا تنتقل مباشرةً إلى الحليب؛ إذ يتكوّن الحليب من الدم، وليس من غازات المعدة. وما لم تلاحظي انزعاجًا حقيقيًا لدى رضيعكِ بعد تناول طعام محدد (وهذا نادر جدًا، وقد يحدث في حال حساسية بروتين حليب البقر)، فلا تفرضي على نفسكِ حمية غذائية بلا داعٍ. فتناولكِ طعامًا متنوعًا وغنيًا بالفيتامينات والبروتينات أكثر فائدة بكثير من تجويع نفسكِ، سواء لجودة حليبكِ أو لصحتكِ النفسية.') WHERE id = '0f643a6c-2b94-498e-845b-b4547838a7e6';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'قد يسبب حمل رضيعكِ بين ذراعيكِ باستمرار ألمًا في ظهركِ، لذلك يمكن أن تكون حمّالة قماشية أو حقيبة حمل مريحة مصممة وفق مبادئ الهندسة البشرية (وليست حمّالة الكنغر!) أفضل مساعد لكِ. لا تكترثي لعبارات مثل «سيعتاد الطفل على الحمل» أو «سينحني عموده الفقري»؛ بل على العكس، فالحمّالات المريحة التي تكون فيها ساقا الرضيع على شكل حرف "M" (كوضعية الضفدع) مفيدة جدًا لنمو مفصلَي وركه. تذكّر هذه الوضعية رضيعكِ بالاحتواء الذي كان يشعر به داخل الرحم فتهدّئه، كما تترك يديكِ حرتين لتنجزي أعمال المنزل أو تستمتعي بكوب من الشاي بهدوء. وسيمنح شعور القرب كليكما السيروتونين (هرمون السعادة).') WHERE id = 'a2fbf383-d8f0-4347-a3ef-d35f626ab799';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'إذا كان يزعجكِ أن يرغب زوار المنزل في تقبيل رضيعكِ أو أن يتناقلوه من شخص إلى آخر، فلا تترددي أبدًا في قول «لا» ووضع حدود واضحة. فجهازه المناعي لا يزال ضعيفًا جدًا، وقد يشكل فيروس قرحة البرد (الهربس)، الذي يكون عاديًا لدى البالغين، خطرًا على حياته. ومن حقكِ الطبيعي تمامًا أن تطلبي من الزوار بلطف غسل أيديهم، وألا يأتوا إذا كانوا مرضى، وألا يقبّلوا وجه رضيعكِ أو يديه. وإذا انزعج أحدهم بسبب ذلك، فهذه مشكلته؛ فمهمتكِ الأساسية هي حماية رضيعكِ، لا الحرص على عدم إزعاج الآخرين.') WHERE id = '7b5d5e0e-5e56-4eb3-b899-1d95dce7cd83';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تهانينا أيتها الأم الرائعة! أتمّ رضيعكِ اليوم شهره الأول! تذكّري مقدار ما واجهتِه خلال هذا الشهر من صعوبات وليالٍ بلا نوم، وكيف ظللتِ قوية، وافتخري بنفسكِ. وقد حان أيضًا موعد فحص رضيعكِ الطبي الشهري لقياس وزنه وطوله؛ فكل غرام اكتسبه هو ثمرة جهودكِ. التقطي اليوم صورة تذكارية له بمناسبة إتمامه شهرًا، وسجّلي التواريخ، واحرصي على الاحتفال بهذه الذكرى الصغيرة، حتى لو كان ذلك بقطعة كعك واحدة فقط. فالوقت يمضي بسرعة كبيرة، وسيصبح توثيق هذه اللحظات من أجمل ذكرياتكِ في المستقبل.') WHERE id = '520fba19-0b3a-4361-9ce1-dac3a718ebb0';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'إذا كنتِ تخشين دخول الماء إلى أذن رضيعكِ أثناء الاستحمام، فلا تقلقي؛ فطبلة الأذن تحمي الأذن الداخلية من الماء، وعادةً لا يسبب دخول الماء مشكلة خطيرة (ما لم تكن طبلة الأذن متضررة). فالاستحمام ليس مجرد وسيلة لتنظيف رضيعكِ، بل هو أيضًا وقت للمرح والاسترخاء؛ وإذا كان يحب الماء، فقد يكون تحميمه كل مساء في الموعد نفسه قبل النوم روتينًا رائعًا للنوم. يساعد الماء الدافئ على إرخاء العضلات والتهدئة، ويرسل إلى رضيعكِ إشارة مفادها: «لقد حلّ الليل، وحان وقت النوم». وبعد الاستحمام، لفّيه بمنشفة دافئة ودلّكيه برفق لتسهيل انتقاله إلى النوم.') WHERE id = 'd1cd229a-65ce-4753-a5dc-ce53e13d2100';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'بعد انقضاء الشهر الأول من الولادة، يُفترض عادةً أن تنتهي تلك المرحلة الحزينة والحساسة المعروفة باسم "Baby blues"؛ فإذا كنتِ لا تزالين تشعرين باستمرار بالحزن أو اليأس أو الإرهاق أو اللامبالاة تجاه رضيعكِ، فانتبهي. فقد يكون ذلك اكتئاب ما بعد الولادة، وهو ليس ذنبكِ إطلاقًا، ولا دلالًا أو ضعفًا منكِ، بل اختلال هرموني وكيميائي. لا تلومي نفسكِ قائلةً: «أنا أم ويجب أن أتحمّل»؛ فإذا لم يزُل شعور الفراغ داخلكِ، فتحدثي بالتأكيد إلى طبيبكِ أو اختصاصي نفسي. فصحتكِ النفسية لا تقل أهمية عن صحة رضيعكِ الجسدية، بل قد تكون أهم منها.') WHERE id = '792d4a29-1f99-4846-89d2-54738a980f78';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تهانينا، لقد مرّ أسبوع كامل على أمومتكِ، وقد اجتزتِ هذه الأيام بنجاح رغم كل الصعوبات! عندما تنظرين في المرآة، قد تلاحظين أن بطنكِ لم يستعد شكله بعد وأن شعركِ غير مرتب، لكنكِ ترعين معجزة صغيرة، وأنتِ جميلة جدًا كما أنتِ. بدءًا من اليوم، يمكنكِ وضع طفلكِ على بطنه لفترات قصيرة (1-2 دقيقة) وهو مستيقظ وتحت إشرافكِ (وقت الاستلقاء على البطن). سيساعد هذا التمرين البسيط على تقوية عضلات رقبته وظهره، وتخفيف آلام الغازات، وتهيئة أساس نموه الحركي مستقبلًا.') WHERE id = '33d098f8-b80c-478c-bb61-a7d57cd72e57';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'قد تلاحظين اصفرارًا خفيفًا في جلد طفلكِ أو بياض عينيه؛ وهذا هو اليرقان الفسيولوجي، ويزول من الجسم في معظم الحالات مع الرضاعة المتكررة. لكن إذا امتد الاصفرار نحو الساقين وأصبح طفلكِ خاملًا جدًا، فاستشيري طبيبكِ حتمًا. كذلك، لا تخافي من تجديد هواء الغرفة؛ فالاعتقاد بأنه «لا يجوز تعريض الطفل للهواء قبل مرور أربعين يومًا» مجرد خرافة، والهواء النقي ضروري لدماغكِ ودماغ طفلكِ. افتحي النافذة وهوّي الغرفة، أو ألبسي طفلكِ ملابس مناسبة للطقس واصطحبيه لفترة قصيرة إلى الهواء الطلق إن أمكن (إذا سمح الطبيب بذلك).') WHERE id = '55de4073-ef7d-4cff-84f4-bf2b8f830118';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'قد تحب جداتنا لفّ الرضيع بإحكام «كي يستقيم جسمه»، لكن الطب الحديث أثبت أن ساقي الطفل يجب أن تتحركا بحرية لينمو مفصل الورك نموًا سليمًا. إذا كان طفلكِ يفزع من حركة ذراعيه ويستيقظ، فيمكنكِ لف ذراعيه برفق فقط (لفّ جزئي)، لكن احرصي حتمًا على أن تظل ساقاه حرتين في وضعية تشبه «الضفدع». قد يؤثر لف الطفل بإحكام ومنعه من الحركة سلبًا في دورته الدموية ونمو عضلاته. اتركيه يتحرك بحرية ويستكشف العالم بيديه وقدميه.') WHERE id = '94a133da-1fcc-4ffe-a24b-b9755a414c0b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'منذ 10 أيام، ينصبّ كل اهتمامكِ وتفكيركِ على طفلكِ، لكن حاولي اليوم أن تخصصي لنفسكِ وحدكِ ما لا يقل عن 15-20 دقيقة. خذي حمامًا دافئًا، أو استمعي إلى موسيقاكِ المفضلة، أو اعتني ببشرتكِ، أو اكتفي بالنظر من النافذة والاستغراق في أحلامكِ. حاولي تدريجيًا استشعار عضلات قاع الحوض وتحريكها (أبسط أشكال تمارين كيجل) للمساعدة على تسريع تعافيكِ، لكن لا يزال الوقت مبكرًا جدًا لممارسة التمارين الشاقة. أصغي إلى جسدكِ واحترمي احتياجاته، وتذكري أنكِ أكبر سند لطفلكِ، وأن تمتّعكِ بالصحة والقوة النفسية هو أعظم هدية تقدمينها له.') WHERE id = '4ba69869-3aaa-471c-bba8-3e9678c5f231';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'ربما جفّ جذع الحبل السري لدى طفلكِ وسقط بالفعل، أو أوشك على السقوط؛ وهذه عملية طبيعية تمامًا، فلا تقلقي إذا رأيتِ بقعة دم صغيرة عند موضع السرة. بعد سقوطه، من المهم الاستمرار في إبقاء المنطقة جافة ونظيفة، لأن الرطوبة توفر بيئة ملائمة لتكاثر البكتيريا. أحيانًا تقلق الأمهات من بقاء السرة «بارزة إلى الخارج»، لكنها غالبًا ما تعود إلى موضعها مع اشتداد عضلات البطن؛ لذلك تجنبي الأساليب القديمة، مثل ربط قطعة نقدية فوق السرة أو الضغط عليها بإحكام. إذا لاحظتِ احمرارًا حول السرة أو رائحة كريهة أو صديدًا، فأخبري طبيبكِ فورًا؛ وإلا فاتركي الطبيعة تأخذ مجراها.') WHERE id = '4412d0c9-03dd-43c8-bb46-87b4fecadda2';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'قد تلاحظين في هذه الأيام أن طفلكِ يرغب في الرضاعة باستمرار، وأحيانًا كل ساعة، وكأنه لا يشبع أبدًا؛ ويُسمّى ذلك طبيًا «طفرة النمو» (growth spurt). غالبًا ما تفسر الأمهات هذا الوضع بقولهن: «قلّ حليبي وبقي طفلي جائعًا»، فيشعرن بالقلق ويسارعن إلى استخدام الحليب الصناعي، لكن هذه في الواقع طريقة طفلكِ لإرسال إشارة إلى جسمكِ مفادها «أنتجي مزيدًا من الحليب» لتلبية احتياجاته المتزايدة. تحلّي بالصبر، فهذه حالة مؤقتة تستمر عادةً يومًا أو يومين؛ ما عليكِ سوى الاستجابة لطلب طفلكِ وتقريبه إلى ثديكِ كثيرًا. سيساعدكِ شرب كميات وفيرة من الماء والحصول على الراحة خلال هذه الفترة على استعادة قوتكِ، وتذكري أن كمية حليبكِ ستزداد طبيعيًا بما يتناسب مع احتياجات طفلكِ.') WHERE id = '8aab5133-1153-4e9f-bfa1-1ddc76290148';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحبًا بكِ في الشهر الثاني! لقد بدأتِ أنتِ وطفلكِ تتعرّفان إلى بعضكما بصورة أفضل، وبدأ «إيقاع» معيّن يتشكّل في حياتكما. لاحظي أننا لا نقول «نظامًا»، بل «إيقاعًا»؛ لأن طفلكِ ليس مستعدًا بعد للعيش وفق مواعيد محددة، لكن تسلسل النوم والرضاعة واليقظة بدأ يتكوّن. لا تحاولي في هذه الفترة وضع جداول صارمة، بل راقبي إشارات النعاس لدى طفلكِ، مثل التثاؤب وفرك العينين، وحاولي تنويمه قبل أن يصاب بالإرهاق الشديد. وإذا كان كل شيء لا يزال يبدو فوضويًا، فلا تقلقي؛ فحتى داخل هذه الفوضى يوجد نظام رائع، وأنتِ تديرين الأمور ببراعة.') WHERE id = '014f9c15-8f59-4b13-b689-2c5db7a165c4';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'عندما تضعين طفلكِ على بطنه (tummy time)، قد تلاحظين أنه بدأ يحاول رفع رأسه، ولو لبضع ثوانٍ فقط؛ وهذه أول علامة على أن عضلات رقبته تزداد قوة. ولجعل هذه التمارين أكثر تشويقًا، ضعي أمامه لعبة ملوّنة، أو استلقي في مواجهته وتحدّثي إليه. إذا لم يتمكن من رفع رأسه بعد، فلا تقلقي؛ فكل طفل ينمو بوتيرة مختلفة. واصلي التمرين بصبر، فهذه المحاولات الصغيرة هي اللبنات الأساسية التي ستمهّد لحبوه ومشيه مستقبلًا.') WHERE id = 'edef290e-ee82-45c6-adef-de36a35e9688';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'ربما رأيتِ طفلكِ حتى الآن يبتسم في أثناء نومه، ويقال شعبيًا إنه «يلعب مع الملائكة» (لكنها في الواقع ابتسامة انعكاسية)، إلا أن مرحلة «الابتسامة الاجتماعية» قد اقتربت. قد ينظر طفلكِ إليكِ ويبتسم لكِ بوعي استجابةً لصوتكِ أو لتعابير وجهكِ؛ فهذه ليست مجرد حركة في الوجه، بل طريقته الأولى ليقول لكِ: «أنا أعرفكِ وأحبكِ». انظري في عينيه وابتسمي له وأنتِ تتحدثين إليه، وسيحاول بدوره الاستجابة لكِ. هذا التفاعل المتبادل من أقوى المحفزات لنمو ذكائه العاطفي.') WHERE id = '33d46eab-d81b-465a-acf9-3431f678ba0a';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل تدخلين الغرفة أحيانًا وتتساءلين: «لماذا جئتُ إلى هنا؟»، أو تعجزين عن تذكّر أبسط الكلمات؟ يُطلَق على ذلك مازحًا «دماغ الأم» (Mom brain)، وهي حالة فسيولوجية حقيقية تمامًا. تؤدي قلة النوم والتغيرات الهرمونية إلى تغيير بؤرة اهتمام الدماغ، وكأنه يوجّه جميع موارده نحو طفلكِ ويحذف الأمور الأخرى «غير المهمة». لا تظني أنكِ أصبحتِ أقل ذكاءً؛ فهذا مجرد ضباب مؤقت. يمكنكِ تجاوز هذه الفترة بسهولة أكبر عبر تدوين المهام المهمة في دفتر ملاحظات أو على هاتفكِ، وسيستعيد ذهنكِ حدّته السابقة قريبًا.') WHERE id = 'd8c08c2a-72db-44c1-9834-75d63110369c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تتطور قدرة طفلكِ على الرؤية، وقد يبدأ الآن بتتبّع الأشياء المتحركة بعينيه (tracking). أمسكي إصبعكِ أو لعبة ملوّنة على مسافة 20-30 سم من وجهه، وحرّكيها ببطء يمينًا ويسارًا؛ وسيحاول تتبّعها بنظراته. تساعد هذه اللعبة البسيطة على تقوية عضلات عينيه وتطوير التناسق بين الدماغ والعينين. إذا لم يستجب فورًا، فقد يكون متعبًا؛ فلا تجبريه، وحاولي مرة أخرى في وقت لاحق.') WHERE id = '8bc192a0-eebe-4dd4-8ce3-ca56d11958b8';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'رغم أن طفلكِ لا يستطيع الكلام بعد، فإنه مستمع رائع؛ لذا فإن وصف كل ما تفعلينه معه خلال اليوم، مثل: «سنغيّر حفاضك الآن» و«انظر، هذه نافذة»، أمر بالغ الأهمية لتطور كلامه مستقبلًا. تُظهر الأبحاث أن الأطفال الذين يتحدث إليهم والداهم كثيرًا يتمتعون مستقبلًا بحصيلة لغوية أغنى. اطرحي عليه أسئلة، ثم اصمتي قليلًا وانتظري كما لو أنه سيجيبكِ، مثل: «هل شربتَ حليبك؟ أحسنت!». يعلّمه هذا «الحوار» قواعد التواصل ويقوّي الرابطة بينكما.') WHERE id = '99451123-a037-4f29-a96e-5e981ce03fe5';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'قد تكون الأسابيع 6-8 (أي الفترة الحالية) ذروة بكاء الرضّع. أحيانًا قد يبكي طفلكِ من دون سبب واضح، حتى لو كان شبعانًا وحفاضه نظيفًا. يحدث ذلك لأن جهازه العصبي يتعرض لإرهاق مفرط بسبب الأصوات والأضواء والمحفزات المحيطة. لا تلومي نفسكِ؛ فهذا لا يعني أنكِ «أم سيئة»، بل هو جزء طبيعي من نموه. ابقي بجانبه واحتضنيه وقولي لنفسكِ: «هذا أيضًا سيمر». وبالفعل، سيقل هذا البكاء بشكل ملحوظ خلال بضعة أسابيع.') WHERE id = 'c94543e8-f599-4ccd-918b-88ff573157bb';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل بدأ طفلكِ بالفعل بالمناغاة وقول «آغو» أو إصدار أصوات من حلقه؟ هذه أولى مراحل تطور الكلام! عندما يصدر صوتًا، أجيبيه بالصوت نفسه، وكأنكما «تتحادثان». تُظهر الدراسات أن تقليد الوالدين لأصوات الرضيع يوصّل إليه رسالة مفادها: «أنا أسمعك وأفهمك». تعزز هذه اللعبة البسيطة ثقته بنفسه وتمهّد له الطريق لبدء الكلام في وقت أبكر مستقبلًا.') WHERE id = '045f5830-2fde-4a82-b369-03b2e1dcea23';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'قد تشعرين بالإحباط عندما تنظرين إلى المرآة وترين الوزن الزائد المتبقي من الحمل أو ترهل البطن. تذكّري أن بطنكِ تمدد على مدى 9 أشهر، ويحتاج إلى مدة لا تقل عن ذلك كي يستعيد شكله بالكامل. قد تؤدي الحميات القاسية (خصوصًا لدى الأمهات المرضعات) إلى انخفاض إدرار الحليب وتساقط الشعر. لا تفكري الآن في إنقاص وزنكِ، بل في اتباع نظام غذائي صحي. الإكثار من الماء والخضراوات والبروتين هو أفضل ما يدعمكِ. لا تكرهي جسدكِ؛ فقد منحكِ أجمل هدية في العالم.') WHERE id = '772a8327-4bbe-46b7-9c90-09e5deaa584b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'جرّبي لعبة «الطائرة» لجعل «وقت الاستلقاء على البطن» (tummy time) أكثر متعة. استلقي على ظهركِ واثني ركبتيكِ، ثم ضعي طفلكِ على بطنه فوق ساقيكِ وهزّيه برفق (مع إمساكه بيديكِ بالطبع). يمنحه ذلك زاوية رؤية مختلفة، ويساعده على التواصل البصري معكِ، كما ينمّي جهازه الدهليزي (الإحساس بالتوازن). يحب الرضّع التمرّن فوق جسم الأم أكثر من بقائهم وحدهم على الأرض.') WHERE id = 'f63c5890-33d1-4cec-a07d-853961a0ca97';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'على الرغم من أن نومه ليلًا قد لا يكون قد انتظم تمامًا بعد، فقد تبدأ قيلولاته النهارية (nap) بالقِصر. إذا كان طفلكِ ينام نهارًا لمدة 20-30 دقيقة فقط ثم يستيقظ، فلا تفترضي أن «قيلولته انتهت». أحيانًا يستيقظ الرضّع بين دورات النوم (كل 40-45 دقيقة)، رغم أنهم لم يحصلوا بعد على كفايتهم من النوم. لا تشعلي الضوء فور استيقاظه ولا تبدئي باللعب معه؛ استلقي بجانبه، وهدّئيه بأصوات لطيفة، أو حاولي إطالة نومه بإرضاعه.') WHERE id = '2c5835b8-b6ba-41d1-b215-505864265cfb';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'حان الوقت لتتحدثي مع طبيبكِ عن لقاحات الشهرين المرتقبة. وفقًا للجدول الوطني للتطعيم في أذربيجان، تُعطى في هذه المرحلة لقاحات السعال الديكي والدفتيريا والكزاز والتهاب الكبد B وغيرها (Hexaxim أو ما يشابهه)، إلى جانب لقاحي فيروس الروتا والمكورات الرئوية. لا تصدقي الشائعات المخيفة التي لا أساس علميًا لها، مثل «اللقاحات ضارة» أو «ستمنع الطفل من الكلام». اللقاح هو أقوى درع يحمي طفلكِ من أمراض قاتلة قد تصيبه مستقبلًا. اطرحي أسئلتكِ على طبيب الأطفال، لا على «الجارة».') WHERE id = '28360eb0-4c71-4798-a428-29239685c45f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تدليك الرضيع وسيلة رائعة لتخفيف مغص الغازات وتهدئته في الوقت نفسه. ضعي قليلًا من زيت الأطفال الطبيعي على يديكِ، وتأكدي من أن الغرفة دافئة، ثم دلّكي رضيعكِ بحركات لطيفة بدءًا من قدميه صعودًا إلى أعلى جسمه. وسيساعد هرمون الأوكسيتوسين، الذي يُفرَز عند اللمس، على تهدئتكِ وتهدئة رضيعكِ معًا. وقد يساعد تكرار هذا الطقس كل مساء بعد الاستحمام على أن يخلد إلى النوم ليلًا بسهولة أكبر.') WHERE id = '030269db-0cd6-4191-b990-5149723f7ac1';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'قد تشعرين بأن علاقتكِ بزوجكِ قد تراجعت إلى المرتبة الثانية لأن كل الاهتمام منصبّ على رضيعكِ، وهذا طبيعي جدًا. لكن حاولا ألا تنسيا أنكما «زوجان» إلى جانب كونكما «والدين»؛ فقد يساعد احتساء الشاي معًا عندما ينام رضيعكِ، أو تبادل العناق، أو حتى التحدث لمدة 10 دقائق فقط عن أحداث يومكما، على إذابة الفتور بينكما. وأتيحي للأب أيضًا فرصة تكوين رابطة مع رضيعكما، فمثلًا يمكن أن يتولى مساعدته على التجشؤ أو تحميمه. إن شعوركما بأنكما فريق واحد سيمنحكما القوة خلال هذه الأيام الصعبة.') WHERE id = '7b078d0d-8755-48b3-a240-4b2c014cdd7f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'حتى إن كان رضيعكِ لا يحبو بعد، فقد يحاول التقلب بحركات لا إرادية، وهنا تبرز أهمية السلامة. القاعدة الذهبية: لا تتركي رضيعكِ وحده أبدًا، ولو لثانية واحدة، على سطح مرتفع مثل الأريكة أو السرير أو طاولة تغيير الحفاضات. لا تطمئني قائلةً: «إنه لا يتحرك بعد»، فأول تقلب يحدث عادةً في أكثر اللحظات غير المتوقعة. لا تتركيه بمفرده إلا على سجادة مفروشة على الأرض أو بساط لعب مخصص، مع إبقائه تحت المراقبة بالطبع. إن اكتساب عادات السلامة منذ الآن سيساعد على الوقاية من الحوادث مستقبلًا.') WHERE id = '0720bc24-8ac8-43a4-b347-e7e20231713d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'وها قد حلّ ذلك اليوم الذي يحظى بأهمية كبيرة في الموروث الشعبي: «أتمّ الطفل أربعينه»! تهانينا! وفقًا للعادات القديمة، يُقام في هذا اليوم طقس استحمام خاص يُعرف بـ«ماء الأربعين»، ويصبح بإمكان الأم وطفلها الخروج والاختلاط بالمجتمع بحرية. أما من الناحية الطبية، فهذا يعني اكتمال فترة التعافي التي تستمر 6 أسابيع، بما يشمل انتهاء إفرازات النفاس وانقباض الرحم وعودته إلى حجمه الطبيعي. احتفلي بهذا اليوم كأنه عيد، وتأنقي واهتمي بجمالكِ، وربما تخرجين مع طفلكِ في أول نزهة «رسمية» طويلة. «الأربعون» ليس مجرد رقم، بل رمز لانتقالكِ من مرحلة «الأم الجديدة» إلى مرحلة «الأم الخبيرة». لقد نجحتِ!') WHERE id = '1ce90c4b-f9a4-402a-a99b-4457322248d1';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'يُنظر في مجتمعنا إلى «إتمام الأربعين» كأنه خط النهاية، لكنه في الحقيقة ليس سوى بداية الماراثون. لا تستسلمي لضغوط مثل: «يجب أن أكون قادرة على فعل كل شيء الآن» أو «يجب أن يكون منزلي نظيفًا تمامًا». فما زالت عملية التعافي مستمرة، وخصوصًا إذا كنتِ ترضعين طبيعيًا؛ إذ قد تشعرين بليونة في مفاصلكِ أو آلام في أسفل ظهركِ بسبب تأثير الهرمونات، ومنها البرولاكتين. لا تحمّلي نفسكِ فوق طاقتها فجأة خلال مرحلة «الحرية الجديدة» هذه، بل عودي إلى وتيرتكِ السابقة ببطء وتدرّج، خطوةً بخطوة.') WHERE id = '0928cbd6-fa37-455a-a682-9515f253a752';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'بدأ طفلكِ الآن يميّز الألوان بصورة أفضل؛ وقد يكون الأحمر والبرتقالي من أول الألوان الزاهية التي تجذب انتباهه. ولم تعد موسيقى الألعاب الدوّارة المعلقة فوق سريره وحدها ما يثير اهتمامه، بل حركتها أيضًا. إذا لم تشتري واحدة بعد، فإن لعبة معلقة دوّارة بسيطة تتكون من أشكال هندسية وتتحرك ببطء ستساعده على تطوير قدرته على تركيز الانتباه. لكن انتبهي: أبعدي هذه الألعاب عند وضعه للنوم حتى لا تبدد نعاسه.') WHERE id = 'c21766cd-a78b-4676-9247-d0b2e0b3de2f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'غالبًا ما يُعد موضوع الحياة الجنسية بعد الولادة من المحظورات، لكن من المهم أن تكوني على دراية به. يمكنكِ استئناف العلاقة الجنسية بعد موافقة طبيبكِ (عادةً بعد 6 أسابيع)، ومن الطبيعي تمامًا أن تشعري بقلة الرغبة الجنسية أو الجفاف. يرجع ذلك إلى تأثير هرمونات الرضاعة الطبيعية والإرهاق. تحدثي مع شريككِ بصراحة حول هذا الأمر، وامنحا نفسيكما الوقت ولا تتعجلا. فالعلاقة الحميمة لا تقتصر على الجماع؛ إذ إن مجرد العناق واللمسات مهمان جدًا أيضًا خلال هذه الفترة.') WHERE id = 'a59bf56c-999f-4547-b139-eaa70223118e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لقد بلغ طفلكِ الآن المرحلة التي يكتشف فيها يديه؛ فقد يضعهما في فمه أو يمص أصابعه. لا يعني ذلك بالضرورة أنه "جائع" (مع أنه قد يكون أيضًا علامة على الجوع)، بل إنها آلية تساعده على تهدئة نفسه وطريقة يستكشف بها العالم. لا تحاولي إخراج يديه من فمه أو إلباسه القفازات. دعيه يكتشف جسده، وتأكدي فقط من نظافة يديه وتقليم أظافره.') WHERE id = '15366f98-572a-4b0c-8fda-af7cf85e56b4';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لقد حان موعد لقاحات عمر شهرين (إذا لم تكوني قد أعطيتِها لطفلكِ بعد). وفقًا لجدول التطعيمات المُطبَّق في أذربيجان، يُعطى الطفل خلال هذه الفترة عادةً اللقاح المركب 5 في 1 أو 6 في 1 (ضد السعال الديكي والدفتيريا والكزاز وغيرها)، بالإضافة إلى لقاح المكورات الرئوية. قد ترتفع حرارة طفلكِ قليلًا أو يصبح منزعجًا بعد التطعيم؛ وهذا ليس مدعاة للخوف، بل يدل على أن جهازه المناعي قد بدأ "بالعمل" وأن جسمه يكوّن الحماية. احتفظي في المنزل، بعد استشارة الطبيب، بتحاميل أو شراب للأطفال يحتوي على الباراسيتامول، لكن لا تتعجلي في إعطائه الدواء ما لم تتجاوز حرارته 38 درجة.') WHERE id = '947283f7-9c09-4c76-a0bb-7ff92f24aad4';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل بدأ لعاب طفلكِ يسيل وأصبح يقضم يديه؟ قد تقول الجدات فورًا إن "أسنانه بدأت بالظهور"، لكن عمر شهرين يكون عادةً مبكرًا للتسنين، رغم وجود حالات استثنائية. تبدأ الغدد اللعابية بالعمل بنشاط خلال هذه الفترة، لكن طفلكِ لم يتعلم بعد ابتلاع اللعاب جيدًا، ولذلك يسيل من فمه. وفي الوقت نفسه، تساهم الإنزيمات الموجودة فيه في تهيئة جهازه الهضمي للأطعمة الصلبة مستقبلًا. ما عليكِ سوى تغيير مريلته باستمرار حتى لا تبقى رقبته رطبة ويظهر عليها طفح جلدي أو تسلخات.') WHERE id = '99be53c6-0b63-4846-ac0b-fd476ca9e54e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'إذا وجدتِ خصلًا من شعركِ تتساقط في يدكِ أثناء الاستحمام، فلا تقلقي، لن تصابي بالصلع! يُسمى ذلك "تساقط الشعر بعد الولادة"، وهو عملية هرمونية طبيعية تمامًا. كان ارتفاع هرمون الإستروجين خلال الحمل يمنع تساقط شعركِ، أما الآن فقد انخفضت مستويات هذه الهرمونات، لذلك يتساقط دفعة واحدة الشعر الذي لم يتساقط في موعده. هذا مؤقت، وسينمو شعركِ مجددًا خلال نحو 6-12 شهرًا. وبدلًا من إنفاق المال على أنواع الشامبو باهظة الثمن، اهتمي بتغذيتكِ ومستوى الحديد لديكِ؛ فمع مرور الوقت سيعود كل شيء إلى طبيعته.') WHERE id = 'f657e712-ddb7-463c-a1f6-51d68e963ec9';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'بدأ طفلكِ الآن يميز إلى حد ما بين الليل والنهار، لذا فهذا هو الوقت المثالي لإنشاء "روتين للنوم". لا يعني ذلك اتباع نظام صارم، بل مجرد الالتزام بتسلسل ثابت: حمام دافئ -> ارتداء ملابس النوم -> إضاءة خافتة -> تهويدة أو ضوضاء بيضاء -> النوم. إن تكرار التسلسل نفسه يوميًا يرسل إلى دماغ طفلكِ إشارة مفادها أن "وقت النوم قد حان". وحتى إن لم تظهر نتيجة هذه العادة اليوم، فستصبح عونًا كبيرًا لكِ بعد بضعة أسابيع.') WHERE id = '2614d60b-6450-43ee-a569-f20e3ea56045';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'يزداد عالم طفلكِ البصري تنوعًا في الألوان؛ فلم يعد يميّز الأحمر والبرتقالي فحسب، بل بدأ أيضًا في تمييز الأخضر والأصفر. ولدعم نموه، تجوّلي به في غرف المنزل المختلفة، وأريه انعكاسه في المرآة (يحب الأطفال انعكاسهم كثيرًا، رغم أنهم لا يدركون بعد أن الصورة هي صورتهم). تحدّثي إليه قائلة: "تعالَ لنرَ، من هنا؟" فهذه الألعاب الاجتماعية تساهم في النمو السريع للخلايا العصبية في دماغه.') WHERE id = '34645ca6-b752-434e-a340-59af7488ff61';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'ترضع بعض الأمهات طبيعيًا، لكن وزنهن لا ينخفض، بل قد يزداد. قد يرتبط ذلك بارتفاع هرمون الكورتيزول بسبب قلة النوم والتوتر؛ إذ يشعر الجسم بأنه في حالة "خطر" فيبدأ بتخزين الدهون. والاعتقاد بضرورة تناول الشاي المحلّى أو الحلاوة أو المعجنات "لإدرار الحليب" مجرد خرافة؛ فأهم ما يدعم إدرار الحليب هو شرب كمية كافية من الماء وإرضاع طفلكِ بصورة متكررة. سيساعدكِ تقليل السكر وتناول الكثير من الخضراوات على زيادة طاقتكِ وعودة وزنكِ تدريجيًا إلى نطاقه الطبيعي.') WHERE id = '70fa5f2d-ef18-4d50-b156-41acde57d635';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'عندما تضعينه على بطنه (وقت الاستلقاء على البطن)، هل يحاول الآن رفع صدره عن الأرض، وليس رأسه فقط؟ إنه تمرين "رياضي مصغّر"! فعضلات ذراعيه وظهره تزداد قوة. إذا لم يتمكن من ذلك بعد، فساعديه: لفّي منشفة صغيرة على شكل أسطوانة وضعيها تحت إبطيه لتوفر له الدعم. ضعي لعبته المفضلة أمامه ليحاول الوصول إليها. هذه الحركات مهمة لتمكّنه من الحبو والجلوس مستقبلًا.') WHERE id = '8cfe7b98-ab62-49f4-b9ea-ef363b224769';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تكون لدى الأطفال في هذه المرحلة رغبة قوية في "المص غير الغذائي"؛ أي إنه لا يكون جائعًا، بل يريد فقط مص شيء ليهدأ. إذا كان يمص أصابعه وأردتِ إعطاءه لهاية، فحاولي اختيار النوع ذي الشكل "التقويمي". اللهاية ليست عادة سيئة، وقد تساعد في تقليل خطر متلازمة موت الرضع المفاجئ (SIDS). لكن لا تستخدميها "لإسكاته" كلما بكى؛ حاولي أولًا فهم سبب انزعاجه.') WHERE id = '4ec5ed37-79da-4c46-9571-b8e74147be8d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل تلاحظين أن أحد جانبي رأس طفلكِ أصبح مسطحًا؟ يُسمى ذلك "تسطّح الرأس الوضعي"، وينتج عن استلقاء الطفل دائمًا على الجانب نفسه. لا تزال عظام جمجمته طرية، ويمكن تصحيح هذا التسطّح بسهولة. إليكِ حلًا بسيطًا: عند وضعه في سريره، بدّلي اتجاه رأسه كل ليلة (يومًا إلى اليمين ويومًا إلى اليسار). وأثناء استيقاظه، اجعليه يقضي أكبر وقت ممكن مستلقيًا على بطنه لتخفيف الضغط عن مؤخرة رأسه.') WHERE id = '248e6415-444f-4d09-8609-b540277d00d1';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تهانينا! أتمّ طفلكِ اليوم شهره الثاني! لقد تجاوزتما رسميًا مرحلة "حديث الولادة" (newborn)، وأصبح الآن يُعدّ "رضيعًا" (infant). قارني ذلك الكائن الصغير العاجز في أيامه الأولى بطفلكِ الآن، وهو يبتسم لكِ ويصدر الأصوات. ستأتي أيام صعبة أخرى، مثل التسنين وتراجع النوم وغيرهما، لكنكِ أصبحتِ الآن أمًا خبيرة وستتمكنين من تجاوز أي صعوبة. احتضني نفسكِ، فأنتِ تقومين بعمل رائع!') WHERE id = 'd3b345c6-e91a-402d-9918-ceed5b8d37b4';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحبًا بكِ في الشهر الـ3! تقتربان أنتِ وطفلكِ من نهاية فترة التكيف خلال الأشهر الـ3 الأولى، المعروفة في نمو الرضيع باسم "الثلث الرابع من الحمل". لم يعد طفلكِ مجرد كائن يأكل وينام، بل أصبح فردًا اجتماعيًا يدرك ما حوله ويستجيب للأصوات. بدءًا من هذا الشهر، ستزداد مدة بقائه مستيقظًا، وسيصبح نومه أكثر انتظامًا قليلًا (كما نأمل!). في هذه المرحلة الجديدة، سيرغب في "التحدث" معكِ أكثر، لذا استعدي للإكثار من الحديث والغناء له.') WHERE id = '8828f855-f7c6-48a8-aae1-636ec24ccff1';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل يضع طفلكِ يديه أمام وجهه ويتأملهما بدهشة؟ إنه يكتشف أول "لعبة" له! يُسمى ذلك "التناسق بين اليد والعين". فهو يدرك أن يديه جزء منه وأنه يستطيع التحكم فيهما. لا تعيقي هذه العملية ولا تخفي يديه. بل يمكنكِ جعل هذا الاكتشاف أكثر تشويقًا بوضع أساور ملونة أو مُصدرة للأصوات (ذات أجراس) حول معصميه. فهذا تمرين رائع لنمو دماغه.') WHERE id = 'c44f54e6-bd35-4121-9f0f-f6748ef02647';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'رغم أن موضوع النوم لا يزال مرهقًا، فهناك خبر سار: بدأ دماغ طفلكِ بالفعل بإفراز "الميلاتونين" (هرمون النوم)، وبدأ إيقاعه اليومي (ساعته البيولوجية) بالتشكل. وأصبح احتمال خلطه بين الليل والنهار أقل. لمساعدته، املئي الغرفة بضوء الشمس صباحًا، وأطفئي الأنوار مبكرًا في المساء ووفّري أجواء هادئة. سيرسل هذا النمط الطبيعي للضوء إلى دماغه إشارات مفادها "حان وقت الاستيقاظ الآن" و"حان وقت النوم الآن".') WHERE id = 'f3bdc990-29cc-452b-b018-a1508cec7d80';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبحت عضلات رقبته أقوى بكثير، وبات قادرًا عند الاستلقاء على بطنه على رفع رأسه بزاوية 45-90 درجة والنظر حوله. وقد يرفع أحيانًا ذراعيه وساقيه في الهواء ويتأرجح مثل "الطائرة". يساعد ذلك على تهيئة عضلات ظهره لمرحلتي الحبو والجلوس مستقبلًا. إذا كان لا يزال غير قادر على تثبيت رأسه تمامًا، فلا تقلقي؛ فلكل طفل وتيرته الخاصة. احرصي فقط على عدم إهمال وقت الاستلقاء على البطن (tummy time) ضمن روتينه اليومي.') WHERE id = '72ecbac3-10ef-45d2-898d-f50326e4aca5';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل لاحظتِ قشورًا صفراء دهنية على رأس طفلكِ، خصوصًا في منطقة اليافوخ؟ تُعرف شعبيًا باسم "قلنسوة المهد"، وتُسمى طبيًا "التهاب الجلد الدهني". لا تخافي، فهي لا تنتج عن قلة النظافة وليست معدية. وتحدث بسبب فرط نشاط الغدد الدهنية بتأثير الهرمونات المنتقلة من الأم. لا تحاولي نزعها، بل ضعي عليها قليلًا من زيت الزيتون أو زيت اللوز قبل الاستحمام لتليينها، ثم مشّطيها بفرشاة ناعمة واغسليها. وستزول من تلقاء نفسها مع مرور الوقت.') WHERE id = 'ebf4f9a7-c423-4f9b-a35f-e6aea203cbf5';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لم تعد ابتسامات طفلكِ مجرد رد فعل انعكاسي، بل أصبحت واعية تمامًا! عندما تبتسمين له أو تدغدغينه أو تلعبين معه لعبة "الغميضة"، قد يبدأ بالضحك بصوت مسموع. أليس هذا الصوت أجمل موسيقى في العالم؟ لقد بدأ حسه الفكاهي بالتشكل. وسيستمتع كثيرًا عندما تُصدرين أصواتًا غريبة أو تغيرين تعابير وجهكِ بأشكال مختلفة. كما أن الضحك يساعد على نمو رئتيه ويقلل هرمونات التوتر.') WHERE id = '1fddfb5f-0320-4827-b223-17100c2c0495';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل تبتل وسادة طفلكِ أو ملابسه كثيرًا؟ من الطبيعي جدًا أن يزداد إفراز اللعاب في الشهر 3. ولا يعني ذلك بالضرورة أن أسنانه ستبدأ بالظهور، رغم أن لثته قد تسبب له الحكة. فهذا يدل على تطور جهازه الهضمي وتكوّن حماية طبيعية ضد البكتيريا الموجودة في الفم. ما عليكِ سوى استخدام مريلة للعاب حول عنقه والحفاظ على جفاف المنطقة المحيطة بفمه لمنع ظهور الطفح الجلدي.') WHERE id = '65b4b1d4-9f03-4890-8a26-60e163757dc4';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'يشغل سؤال "هل يجب إعطاؤه الماء؟" بال الكثير من الأمهات خلال هذه الأشهر. وقد تقول الجدات خصوصًا: "مسكين، إنه عطشان". لكن منظمة الصحة العالمية توصي بعدم إعطاء الرضيع خلال أول 6 أشهر أي شيء على الإطلاق، حتى الماء، سوى حليب الأم أو الحليب الاصطناعي. يتكوّن حليب الأم من الماء بنسبة 88%، وهذا يلبّي احتياجات الرضيع من السوائل بالكامل. ولا تزال معدته صغيرة جدًا، لذا فإن ملأها بالماء قد يقلل كمية الحليب التي يتناولها ويؤثر سلبًا في نموه.') WHERE id = 'daa57941-307c-46d4-ad44-8c2b7828cf2e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أضيفي زر "استراحة" إلى حياتكِ اليومية. لا تسارعي إلى تنظيف المنزل فور نوم طفلكِ؛ فـ"بطاريتكِ" تحتاج أيضًا إلى إعادة الشحن. من حقكِ أن تأخذي قيلولة لمدة 20 دقيقة، أو تقرئي كتابًا، أو حتى تكتفي بالنظر إلى السقف بلا تفكير. لستِ مضطرة إلى أن تكوني "ربة منزل مثالية"، لكن من الضروري أن تحافظي على صحتكِ كأم. يمكن للغبار أن ينتظر، أما صحتكِ النفسية فلا تنتظر.') WHERE id = '8ae3c3ee-3ed1-4cce-8f50-41530ca784cb';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'يمكنكِ بدءًا من هذا الشهر إنشاء دورة "الرضاعة - النشاط - النوم". أي: يستيقظ طفلكِ -> يرضع -> يلعب -> ينام. غالبًا ما تُرضع الأمهات أطفالهن حتى يناموا، وهذا ليس خطأ، لكنه قد يتحول إلى عادة. إذا اتبعتِ تسلسل "الرضاعة ثم اللعب ثم النوم"، فسيقل ربط طفلكِ بين الرضاعة والنوم، وقد يسهل عليه مستقبلًا أن يخلد إلى النوم بمفرده. وبالطبع، هذه ليست قاعدة صارمة، بل مجرد طريقة تستحق التجربة.') WHERE id = '2c9372ab-3791-4b09-9ac2-4545b2a50eba';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لم تعد يدا طفلكِ تتحركان بشكل عشوائي؛ فقد بدأ يمدهما نحو الأشياء ويحاول الإمساك بها عن قصد. في السابق، كان يقبض على إصبعكِ تلقائيًا عندما تضعينه في راحة يده، أما الآن فهو يرى اللعبة ويمد يده نحوها. هذا تطور رائع، لكن انتبهي: عندما تحملينه، سيحاول شد شعركِ أو قلادتكِ أو نظارتكِ. وأبعدي عنه أيضًا أكواب الشاي الساخن، فقد يسكبها على نفسه بحركة مفاجئة. أصبح الحفاظ على مسافة آمنة أمرًا ضروريًا الآن.') WHERE id = '851b7601-c8f0-43b8-a2e5-3708104c42ba';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'إذا كنتِ لا تزالين تعانين من قلة النوم ليلًا، فيمكنكِ تجربة طريقة "الرضعة أثناء النوم" (Dream Feed). وتعني إرضاع طفلكِ وهو شبه نائم، من دون إيقاظه تمامًا، ثم إعادته إلى مكان نومه؛ مثلًا في الساعة 23:00 قبل أن تخلدي أنتِ إلى النوم. قد تمنع هذه الطريقة أحيانًا استيقاظ طفلكِ في منتصف الليل، وتمنحكِ فترة نوم أطول قليلًا من دون انقطاع. وإذا لم تنجح وأيقظت طفلكِ وجعلته يبكي، فلا تُجبريه عليها؛ فلكل طفل إيقاعه الحيوي الخاص.') WHERE id = '1a681284-0141-4b15-bc3b-3b5a269a1b94';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'عندما تضعين رضيعكِ على بطنه (وقت الاستلقاء على البطن)، قد تلاحظين أنه يحاول التدحرج إلى جانبه. وقد يتمكن بعض الرضع النشيطين في هذه المرحلة من الانقلاب من البطن إلى الظهر (مصادفةً بسبب ثقل الرأس). هذا مصدر فرح كبير، لكنه أيضًا إشارة تحذير: لم يعد من الآمن تركه دون مراقبة ولو لثانية واحدة على طاولة تغيير الحفاضات أو الأريكة أو أي مكان مرتفع. يزداد خطر السقوط بشكل حاد ابتداءً من هذا الشهر، والمكان الأكثر أمانًا هو الأرض (على سجادة أو بساط لعب).') WHERE id = '51999bec-e90a-4151-af89-e280275c886e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لم تعد الأصوات التي يصدرها رضيعكِ تقتصر على البكاء؛ فقد أصبح قادرًا على مدّ أصوات حروف العلة ("a", "o", "u") أو إصدار أصوات حادة. هذا تدريب لأحباله الصوتية. إذا كنتِ تعملين في المطبخ وكان يصدر أصواتًا في الغرفة، فاحرصي على الرد عليه بصوتكِ ("نعم، أسمعك، أنا قادمة"). يمنحه هذا "التواصل عن بُعد" شعورًا بالأمان: "حتى إن لم أرَ أمي، فأنا أسمع صوتها، وهذا يعني أنني لست وحدي". ويساعد ذلك على تخفيف قلق الانفصال (separation anxiety).') WHERE id = '4b396ede-815b-4edd-bee5-1ab95bd630c3';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مع ازدياد وزن رضيعكِ، قد تشعرين بآلام في ظهركِ وذراعيكِ (وخاصة متلازمة "رسغ الأم"). انتبهي إلى وضعية جسمكِ عند حمله أو إرضاعه؛ لا ترفعي كتفيكِ نحو أذنيكِ، واجلسي باستقامة، واحرصي على استخدام وسائد تدعم ظهركِ. وعندما ترفعين رضيعكِ عن الأرض، اثني ركبتيكِ بدلًا من الانحناء بظهركِ. سيظل عمودكِ الفقري ضروريًا لكِ لسنوات طويلة، فابدئي بحمايته من الآن.') WHERE id = 'dc8afbc6-14c7-4301-94dd-c5e5a4b2292b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'قد تسمعين ممن حولكِ ضغوطًا مثل: "بلغ طفلكِ 3 أشهر، دعيه يتذوق مرق الطعام" أو "أعطيه قليلًا من لبّ الخبز كي يعتاد عليه". كوني حازمة وقولي "لا". تؤكد منظمة الصحة العالمية بوضوح: خلال الأشهر الـ6 الأولى، يجب الاكتفاء بحليب الأم فقط (أو الحليب الصناعي). فجهاز طفلكِ الهضمي ليس مستعدًا بعد لهضم النشويات أو الأطعمة الأخرى؛ وقد يؤدي إدخالها مبكرًا إلى الحساسية والغازات والسمنة مستقبلًا. لا تتعجلي، فسيكون أمامه العمر كله لتناول الطعام.') WHERE id = '0739a3ba-203e-453e-b9ac-6bd4bfdbcdf4';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'اللعبة الأكثر إثارة للاهتمام في هذه المرحلة هي المرآة! ضعي مرآة آمنة (غير قابلة للكسر) أمام رضيعكِ. سيبتسم إلى "الرضيع الآخر" فيها، ويحاول لمسه، وينظر إليه بدهشة. لا يدرك بعد أن الصورة تعود إليه (يحدث ذلك في الشهر 18 تقريبًا)، لكن متابعة تعابير الوجه والحركات رائعة لنموه الاجتماعي. كما تُعد هذه اللعبة حيلة ممتازة لإطالة مدة بقائه على بطنه.') WHERE id = 'd5f46289-84de-4aa8-8cc6-e208423016ca';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مع ازدياد اهتمام رضيعكِ بالعالم من حوله، قد تصبح الرضاعة الطبيعية أكثر صعوبة. فهو يريد أن يدير رأسه لينظر إلى كل صوت وكل حركة، فيترك الثدي. يُسمى هذا "متلازمة الرضيع الفضولي". لا تنزعجي، بل اختاري للرضاعة غرفة أكثر هدوءًا وإظلامًا وخالية من المشتتات. وانزعي عن عنقكِ القلائد اللامعة أو الأشياء اللافتة للانتباه. ستلاحظين أنه يرضع بصورة أفضل ليلًا أو عندما يكون ناعسًا، وهذا طبيعي.') WHERE id = '9cc144a8-c429-4c7c-b711-108cf929ab92';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'قد يؤدي اكتشاف طفلكِ ليديه أحيانًا إلى خدش وجهه بأظافره. إذا كنتِ تخشين قص أظافره، فافعلي ذلك أثناء نومه أو بعد الاستحمام حين تكون أظافره أكثر ليونة. لم يعد يُنصح بإلباسه القفازات، لأن طفلكِ يتعرّف إلى العالم من خلال لمس الأشياء بيديه ووضعهما في فمه. فالخدش الصغير يلتئم سريعًا، لكن حرمان يديه من الإحساس باللمس قد يبطئ نموه وتطوره.') WHERE id = '4516cd0b-d8f9-4d0b-92cb-3f43fabc6642';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تهانينا، أوشكت فترة التكيف خلال الأشهر الـ3 الأولى، المعروفة باسم "الثلث الرابع"، على الانتهاء! لقد اعتاد طفلكِ تمامًا على "العالم الخارجي". لا تتركيه مستلقيًا في سريره طوال فترات يقظته؛ تجوّلي به في المنزل، وانظرا من النافذة، وخذيه إلى غرف مختلفة. فقد أصبح الآن مراقبًا لما حوله. وكلما زاد تواصلكِ البصري والصوتي معه خلال هذه المرحلة، ازدادت قوة الروابط العصبية في دماغه. أنتِ معلمته الأولى والأفضل.') WHERE id = 'ef4c7b42-edd4-4ffb-87e6-5505b04254f6';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل لاحظتِ أن طفلكِ بدأ ينام ليلًا فترات أطول (مثلًا، 4-5 ساعات متواصلة)؟ يشير ذلك إلى أن معدته قد كبرت وأصبح قادرًا على البقاء شبعانًا طوال الليل. لكن لا تتعجلي الفرح، فقد تكون هذه فترة "شهر عسل" مؤقتة. يبدأ لدى بعض الأطفال في عمر 3-4 أشهر تقريبًا ما يُعرف بـ"انتكاسة النوم" (sleep regression). إذا اضطرب نومه، فلا تقلقي؛ فهذا يدل على انتقال نمو دماغه إلى مرحلة جديدة. ما عليكِ سوى الالتزام بروتين النوم الذي وضعتِه، فالثبات هو أكثر ما يحتاج إليه.') WHERE id = '7478fbcd-b780-4677-b9cd-7d27602a29cc';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لم تعد يدا طفلكِ مقبوضتين، بل أصبحتا مفتوحتين معظم الوقت. وهذا يدل على تراجع فرط التوتر العضلي وعودة توتر عضلاته إلى طبيعته. يمكنه الآن ضم يديه واللعب بأصابعه. ويمكنكِ تنمية حاسة اللمس لديه بإعطائه أقمشة أو ألعابًا ذات ملمس متنوع (ناعم، خشن، محدث للحفيف). يبدأ نمو الدماغ من أطراف الأصابع؛ فكلما لمس أسطحًا مختلفة أكثر، عالج دماغه معلومات أكثر.') WHERE id = 'd9c1219d-f2eb-4189-a9f5-e0d58b033ef7';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'المقارنات من قبيل "طفل جارتي بدأ يتقلب بالفعل، فلماذا لا يتحرك طفلي؟" هي من أكبر أعداء الأمهات. تذكّري أن كل طفل حالة فريدة، وأن جدول النمو ليس معادلة رياضية، بل مجرد نطاق زمني تقريبي. قد يتقلب طفل في عمر 3 أشهر، وآخر في عمر 5 أشهر؛ ولا يعني ذلك أن الثاني "متأخر". المقارنة تسبب لكِ التوتر، وطفلكِ يشعر بتوتركِ. احترمي وتيرته الخاصة واحتفي بانتصاراته الصغيرة فحسب (مثل قدرته على إبقاء رأسه مرفوعًا باستقامة أكبر).') WHERE id = '3aa7065c-48aa-4e3c-a0fe-877781389808';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'افحصي جسمكِ: هل تشعرين بوجود فراغ أو انخفاض في منتصف بطنكِ على امتداد خط السرة؟ قد يكون ذلك "الانفراق العضلي" (انفصال عضلات البطن). إذا لم تلتئم العضلات التي تمددت أثناء الحمل بعد، فيُمنع تمامًا أداء تمارين البطن التقليدية، لأنها قد تزيد الحالة سوءًا. عليكِ أولًا تقوية العضلات العميقة بتمارين تنفس بسيطة أو تمرين شفط البطن (بعد موافقة الطبيب). من المهم التحقق من وجود الانفراق العضلي قبل البدء بممارسة الرياضة.') WHERE id = '2926fb2b-5ad3-4daf-b451-2b21927c114c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'ليس من المبكر أبدًا أن تبدئي «قراءة الكتب» لطفلكِ! حتى إن لم يفهم الكلمات، فإنه يحب الاستماع إلى نبرة صوتكِ وتنغيمكِ وإيقاعه. اختاري كتبًا ذات صفحات سميكة وصور كثيرة ونصوص قليلة. أريه الصور وقولي: «انظر، هذه قطة، إنها تموء». تساعد هذه العادة على تسريع تطوره اللغوي وإثارة اهتمامه بالكتب مستقبلًا. كما يمكن أن تصبح قراءة كتاب له بين ذراعيكِ طقسًا مهدئًا قبل النوم.') WHERE id = '7f0b6be9-2911-4a47-a448-53c0a1e9d9fe';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'عندما تضعين طفلكِ على بطنه (وقت الاستلقاء على البطن)، يُفترض أن يكون قادرًا الآن على مد ذراعيه إلى الأمام ورفع صدره عن الأرض بدرجة ملحوظة. تشير «وضعية الكوبرا» هذه إلى أن عضلات ظهره ورقبته تزداد قوة. إذا كان لا يزال لا يحب البقاء على بطنه ويبكي، فلا تستسلمي. واصلي بجلسات قصيرة مدتها 5-10 دقائق يوميًا. وكخيار بديل، استلقي وضعيه فوق صدركِ؛ فعندما يرى وجهكِ، سيشعر بحماس أكبر لرفع رأسه.') WHERE id = 'd283274d-2a11-4684-91a8-ce7b016b2812';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تنتشر بين الأمهات المرضعات أفكار مثل «البوتوكس ممنوع» و«صبغ الشعر ممنوع». لكن الأبحاث الحديثة تشير إلى أن معظم صبغات الشعر أو الإجراءات التجميلية الموضعية لا تنتقل إلى حليب الأم وتُعد آمنة للرضيع (مع اختيار صبغات خالية من الأمونيا والاستعانة بمتخصصين موثوقين بالطبع). إن رغبتكِ في الاعتناء بنفسكِ والظهور بمظهر جميل لا تتعارض مع مسؤوليات الأمومة. فالأم السعيدة والواثقة بنفسها تستطيع أن تمنح طفلها مزيدًا من الحب.') WHERE id = '989b1bed-bb91-418f-ba9c-66f04eee3377';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'قد تتحول ابتسامة طفلكِ الآن إلى قهقهة استجابةً للدغدغة. اختبري رد فعله بدغدغة إبطيه أو رقبته أو باطن قدميه برفق. تساعده هذه اللعبة البسيطة على التعرف إلى جسده وتعزيز قدرته على الإحساس. يساهم الضحك في زيادة سعة رئتيه وتحسين الدورة الدموية. فضحكات طفلكِ هي أفضل دواء لتخفيف التوتر في المنزل.') WHERE id = '9800dfd4-1a12-46cd-be37-2d51f66e1ad7';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل أصبحت قيلولات طفلكِ النهارية أقصر، لكن عددها ازداد؟ عادةً ما يأخذ الرضيع في عمر 3 أشهر 3-4 قيلولات نهارية يوميًا (بإجمالي 4-5 ساعات). إذا كان يرفض النوم ويبكي بسبب فرط التعب، فلا تترددي في تنويمه بين ذراعيكِ أو بهدهدته أو أخذه في جولة بعربة الأطفال. فحرمانه من النوم خوفًا من أن «يعتاد على ذلك» أكثر ضررًا. يفرز الرضيع المحروم من النوم هرمون التوتر (الكورتيزول)، ما يؤثر سلبًا في نموه. الهدف الأساسي هو أن ينام؛ أما طريقة نومه فهي مسألة ثانوية في الوقت الحالي.') WHERE id = '1a9dccd0-8134-416f-bb91-5bdf13fc777c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تهانينا! أتمّ طفلكِ اليوم شهره الثالث! إنها محطة مهمة. لقد انتهى الآن «الثلث الرابع من الحمل» تمامًا. أصبح طفلكِ يثبت رأسه، ويضم يديه معًا، ويبتسم لكِ، وربما يحاول الانقلاب على جانبه. لقد أصبح الآن شخصية صغيرة مميزة. يمكنكِ اليوم تحديد موعد لفحصه لدى طبيب الأطفال لتقييم نموه وتطوره. لكن الأهم هو أن تهنئي نفسكِ. فأنتِ بطلة تعمل بلا توقف ليلًا ونهارًا منذ 90 يومًا. لا تنسي أن تقدمي لنفسكِ هدية صغيرة اليوم!') WHERE id = 'c4888a4d-c53f-4c06-9f8b-73bef82c950b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل يضع طفلكِ في فمه كل ما تقع عليه يداه؟ هذا يعني بدء مرحلة "الاستكشاف الفموي". فهو يتعرّف إلى العالم من خلال "تذوّقه" بفمه. ولا يعني ذلك بالضرورة أن أسنانه ستبدأ بالظهور، رغم احتمال وجود حكة في اللثة. أعطيه عضّاضات ذات قوامات مختلفة. لكن الأهم هو السلامة: لا تتركي أشياء صغيرة على الأرض أو الطاولة، مثل الأزرار والعملات المعدنية والخرز. يزداد خطر الاختناق في هذه الأشهر لأن مهارة اليدين تتحسن. تفقّدي المنزل "بعيني طفلكِ".') WHERE id = '3d44726d-b011-4c60-a3ce-d4d40cf54d8f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل تلاحظين في المساء أن طفلكِ يرفض الحليب، أو يقاوم الثدي، أو يرضع وهو يبكي؟ يُسمى هذا "الرفض الكاذب للرضاعة". ولا يكون سببه قلة الحليب، بل تعب الطفل أو فرط التحفيز. لتهدئته، شغّلي "الضوضاء البيضاء" (white noise)، وأظلمي الغرفة، أو أرضعيه وأنتِ تمشين. إذا استمر في الرفض، فلا تجبريه؛ خذي استراحة لمدة 15-20 دقيقة، ثم هدّئيه وحاولي مجددًا.') WHERE id = '01937078-adcb-4cc4-9337-fd91b288734f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'إذا أصبحت قيلولات طفلكِ النهارية أقصر (30-45 دقيقة)، فهذا طبيعي. في الشهر الرابع تتغير دورات النوم، وقد لا يستطيع الطفل العودة إلى النوم عند الانتقال من دورة إلى أخرى، أي خلال الاستيقاظ الخفيف. لمساعدته، لا تشغّلي الضوء فور استيقاظه؛ استلقي بجانبه، وربّتي عليه برفق، أو ضعي يدكِ على صدره مع ضغط لطيف. ستساعده تقنية "إطالة النوم" (resettling) بمرور الوقت على تعلّم ربط دورات النوم ببعضها.') WHERE id = '42ae96e6-578f-4958-b69b-9e931b862da2';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تهانينا! لقد اجتزتِ مع طفلكِ أول 100 يوم! يُحتفل بهذا اليوم احتفالًا خاصًا في بعض الثقافات الآسيوية، إذ يُعتقد أن الطفل يكون قد تجاوز أكثر مراحله حساسية. انظري إلى الوراء: لقد أصبح ذلك الرضيع الصغير العاجز طفلًا يبتسم لكِ، ويتعرّف إليكِ، ويلعب بيديه. وأنتِ أيضًا تغيّرتِ ونضجتِ وازددتِ قوة. اسكبي لنفسكِ اليوم كوبًا من القهوة، وشاهدي في معرض الصور لقطات الأيام الأولى، وقولي: "لقد نجحتُ!" أنتِ رائعة!') WHERE id = '000749db-379b-4eae-a0cc-18c3f43ee041';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل بدأ طفلكِ يستيقظ كثيرًا ليلًا؟ أهلًا بكِ في "تراجع النوم في الشهر الرابع"! في الحقيقة، هذا ليس تراجعًا، بل قفزة هائلة في نمو دماغ طفلكِ. تتغير دورات نومه وتنقسم، كما لدى البالغين، إلى مرحلتي النوم "الخفيف" و"العميق". يستيقظ الطفل قليلًا عند الانتقال من مرحلة إلى أخرى (كل 45-60 دقيقة)، ويبكي لأنه لا يعرف بعد كيف يعود إلى النوم. هذه مرحلة مؤقتة (قد تستمر من 2-6 أسابيع). تحلّي بالصبر، ولا تغيّري عاداته السابقة فجأة، مثل الهز أو الرضاعة، بل أشعريه فقط بأنكِ بجانبه.') WHERE id = '70ef5cd6-e529-4523-a7e3-dac3c50ee881';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'عندما تضعين طفلكِ على بطنه (tummy time)، هل تلاحظين أنه لم يعد يرفع رأسه فقط، بل يرفع صدره أيضًا عن الأرض ويمد ذراعيه إلى الأمام محاولًا "السباحة"؟ يشير ذلك إلى أن عضلات ظهره تزداد قوة. قد يتمكن بعض الأطفال في هذه المرحلة من التدحرج من البطن إلى الظهر، أحيانًا بالصدفة بسبب ثقل الرأس. إنه إنجاز مفرح، لكنه أيضًا إشارة تحذيرية: أصبح تركه وحده على الأريكة أو السرير ممنوعًا تمامًا! فمنذ هذا الشهر يزداد خطر السقوط بشكل كبير.') WHERE id = '71d4a5bb-ec66-43a8-8e47-cf600b05a37e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'يزداد اهتمام رضيعكِ بالألعاب الملونة والمضيئة والتي تصدر أصواتًا. لكن انتبهي: هناك حد يُسمى «فرط التحفيز» (overstimulation). إذا بدأ رضيعكِ فجأة بالبكاء، أو أدار رأسه، أو أغمض عينيه، فهذه طريقته في القول: «كفى! لقد تعب دماغي!». في هذه الحالة، أبعدي جميع الألعاب، وأوقفي الضوضاء، واحتضنيه بهدوء. أحيانًا تكون أفضل لعبة هي الهدوء وحضن الأم فحسب.') WHERE id = 'b4ee2099-bc1d-4919-b3ee-ba22dc951100';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل ما زلتِ تشعرين بالحزن عندما تنظرين في المرآة وترين علامات التمدد التي خلّفها الحمل؟ تذكّري أن هذه العلامات هي وسام أمومتكِ. مع مرور الوقت، سيتغير لونها من الذهبي إلى الفضي وستبهت. ورغم صعوبة إزالتها تمامًا، فإن ترطيب البشرة وتدليكها قد يحسّنان مظهرها. لكن الأهم أن هذا الجسد صنع إنسانًا ونمّاه. لا تقسي على نفسكِ، فأنتِ جميلة جدًا كما أنتِ.') WHERE id = 'c1675203-e86f-4f0e-b277-4834368fee01';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'عندما تضعين رضيعكِ على ظهره، هل يرفع ساقيه في الهواء ويحاول الإمساك بهما، بل وحتى وضعهما في فمه؟ هذه ليست مجرد لعبة ممتعة، بل تمرين مهم يقوّي عضلات بطنه ويساعده على التعرّف إلى جسمه. لا تمنعيه، بل انزعي جوربيه ودعيه يلعب بأصابع قدميه. تساعد هذه الحركة أيضًا على تمديد الجزء السفلي من عموده الفقري وإراحته، وقد تخفف من مغص الغازات.') WHERE id = '5348f17b-ff81-4e2c-b426-336c5630b994';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تتراوح فترة الاستيقاظ (wake window) لدى الرضّع بعمر 4 أشهر عادةً بين 1.5 و2 ساعة. إذا ظل رضيعكِ مستيقظًا مدة أطول، فقد يدخل في حالة «الإرهاق المفرط» (overtiredness)، ما يزيد صعوبة خلوده إلى النوم. راقبي الوقت: إذا مرّت 1.5 ساعة منذ قيلولته الأخيرة وبدأ يفرك عينيه، فابدئي فورًا روتين التهدئة. قد يؤدي تفويت موعد النوم إلى زيادة عدد مرات الاستيقاظ ليلًا.') WHERE id = '314c334b-e7f8-4072-b418-2d43d8366274';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل يبكي رضيعكِ أحيانًا فجأة أثناء الرضاعة الطبيعية أو تناول الحليب الصناعي، ويرفض الرضاعة ويقوّس ظهره إلى الخلف؟ قد تكون هذه علامة على «الارتجاع الصامت». إذ يرتفع حمض المعدة إلى المريء مسببًا له حرقة. إذا تكرر ذلك كثيرًا وأعاق زيادة وزنه، فتحدثي إلى طبيبكِ. وفي المنزل، لا تمدديه فورًا بعد إرضاعه، بل أبقيه في وضع مستقيم (على كتفكِ) مدة 15-20 دقيقة حتى يستقر الطعام في معدته بسهولة.') WHERE id = '1f5459ab-1bd2-4191-b9fa-6cb6903bc60f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لا تقلقي قائلةً: «لماذا لم يبدأ طفلي بالضحك/التقلب بعد؟». فمراحل النمو ليست سباقًا. بعض الأطفال «مراقبون»؛ يتابعون ما حولهم بهدوء، ثم يفعلون كل شيء فجأة. وبعضهم الآخر «كثيرو الحركة»؛ فلا يتوقفون عن المحاولة والحركة. كلتا الحالتين طبيعيتان. إن مقارنة طفلكِ بأطفال آخرين، حتى بإخوته، لن تجلب لكِ سوى التوتر، وله سوى الضغط. تقبّلي شخصيته الفريدة كما هي وأحبّيها.') WHERE id = '6c7ebcbb-cb8d-440f-985f-f7721a4549c7';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل يثير تشتّت انتباه رضيعكِ أثناء الرضاعة قلقكِ؟ يرضع رشفة أو رشفتين، ثم يدير رأسه لينظر إلى صوت أو ضوء في الغرفة. يُسمّى ذلك "متلازمة الرضيع الفضولي". فهو يريد استكشاف ما حوله، ويبدو له تناول الطعام "مملًا". الحل: اجعلي الغرفة أثناء الرضاعة هادئة وخافتة الإضاءة قدر الإمكان، وأبعدي الأشياء التي تشتّت انتباهه، مثل الهاتف والتلفاز والألعاب ذات الألوان الزاهية. ستلاحظين أنه يرضع بشكل أفضل خلال الرضعات الليلية أو عندما يكون ناعسًا.') WHERE id = 'bce582cc-6b95-467c-98a1-35d2509fd4d5';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل ما زال لعاب رضيعكِ يسيل، وهل يعضّ بقوة كل ما يقع في يده، مثل اللعبة أو البطانية أو إصبعكِ؟ يرجع ذلك إلى الحكة في لثته. فرغم أن السن لم يظهر بعد، فإنه يتحرك تحت اللثة، ما يسبب له الانزعاج. يمكنكِ مساعدته على تدليك لثته بإعطائه عضّاضات مبردة (وليست مثلجة!) أو قطعة قماش نظيفة ورطبة. فهذا يخفف الألم ويساعده على الهدوء.') WHERE id = 'c2f4aabf-8bc7-487e-b896-7f21d18143b1';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل يبكي طفلكِ عندما تغادرين الغرفة، لكنه يهدأ فور عودتكِ؟ تهانينا، فهذا يدل على تطور ذاكرته وقدرته على تمييزكِ عن الآخرين! لقد بدأ يفهم مفهوم "ديمومة الأشياء" (أي أن الشيء لا يختفي عندما يغيب عن الأنظار، بل يتغير مكانه فحسب)، لكنه لم يكتسب اليقين الكامل بعد. يمكنكِ مساعدته على التغلب على هذا الخوف بلعب "الغميضة" معه. غطّي وجهكِ بيديكِ ثم اكشفيه؛ فهذه اللعبة البسيطة تنقل إليه رسالة مفادها: "حتى إن ذهبت أمي، فإنها تعود".') WHERE id = '807256c5-09ac-42f8-a6ba-9c88ea7f39a0';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لا تستسلمي لأفكار مثل "لم يعد حليبي غنيًا بالدهون" أو "حليبي كالماء". يتغير تركيب حليب الأم باستمرار بما يتوافق مع احتياجات رضيعكِ. قد يبدو ذلك الحليب الكثيف المائل إلى الصفرة في الأشهر الأولى أكثر سيولة الآن، لكن هذا لا يعني أن جودته منخفضة. في هذا الشهر، تزداد نسبة الماء في الحليب لتلبية احتياجات رضيعكِ من السوائل (ولذلك لا يحتاج إلى شرب ماء إضافي). لقد نظّمت الطبيعة كل شيء بإتقان، فثقي بجسمكِ.') WHERE id = 'd807fc3e-ee9d-408b-880a-d8041fef08ed';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'إن إصدار رضيعكِ أصواتًا مثل ("آ-غو"، "با-با"، "غي-غي") ليس مجرد ضوضاء، بل هو تدريب على تطور النطق. عندما يصدر صوتًا، أجيبيه بالصوت نفسه أو بكلمات بسيطة مثل: ("حقًا؟ أهذا صحيح؟"). تشير الأبحاث إلى أن الأطفال الذين يشاركون والديهم في "محادثات متبادلة الأدوار" (turn-taking) يتمتعون مستقبلًا بمعدل ذكاء وقدرات لغوية أعلى. تحدّثي إليه كما لو كان شخصًا بالغًا؛ فحتى إن لم يفهمكِ، فإنه يتعلم نبرة الكلام وقواعد التواصل.') WHERE id = '8c9eeb48-f7d1-4cb1-abda-c8b5acd82625';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل يؤلمكِ ظهركِ وذراعاكِ من حمل رضيعكِ؟ قد يؤدي ذلك إلى "رسغ الأم" (التهاب غمد الوتر لدي كيرفان) أو مشكلات في العمود الفقري. عند رفع رضيعكِ، اثني ركبتيكِ بدلًا من ظهركِ، كما في وضعية القرفصاء. وعند إرضاعه، احرصي على وضع وسادة تحت مرفقكِ حتى لا يقع وزن رضيعكِ على ذراعكِ. كما أن استخدام حمالة ظهر مريحة أو حمالة قماشية قد يمنحكِ الراحة من خلال توزيع الوزن بالتساوي. حافظي على صحتكِ، فطفلكِ يحتاج إليكِ بصحة جيدة.') WHERE id = '43116043-105f-43ce-b935-0d355f71fac9';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحبًا بكِ في الشهر 4! لقد أصبحت «مرحلة الثلث الرابع» خلفكِ تمامًا. لم يعد طفلكِ مجرد «لفافة صغيرة» لا تفعل سوى الأكل والنوم، بل أصبح إنسانًا صغيرًا يدرك ما حوله. ابتداءً من هذا الشهر، تبدأ دورات نومه بالتشابه مع دورات نوم البالغين (فتظهر مرحلتا النوم الخفيف والعميق). قد يسبب هذا التغيير أحيانًا اضطرابات في النوم، لكن لا تقلقي؛ فهذه ليست انتكاسة، بل علامة على التطور. دماغه ينمو، وهو يحاول فقط التأقلم مع النظام الجديد.') WHERE id = 'eb18b9d2-6fac-4a33-989e-ff8e3c156809';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل تلاحظين عندما تحملين طفلكِ أنه يبقي جسمه أكثر استقامة ويتحكم في رأسه بحرية؟ يشير ذلك إلى أن عموده الفقري يزداد قوة. يمكنكِ الآن تجربة وضعيات حاملة الأطفال المريحة التي تسمح له بالجلوس «ووجهه نحو العالم» (face out)، بشرط بالطبع أن تكون ساقاه على شكل حرف "M". إنه يحب تأمل العالم، لكن انتبهي: قد ترهقه كثرة المحفزات البصرية بسرعة. إذا بدأ يشعر بالانزعاج، فأديري وجهه نحوكِ فورًا وهدّئيه.') WHERE id = '0ffeb288-283a-4150-a4f7-cffdb0482b4c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«طفلي لا يتقلب بعد، فهل نموه متأخر؟» – إذا كان هذا السؤال يشغل بالكِ، فخذي نفسًا عميقًا. يبدأ الأطفال عادةً بالتقلب بين عمر 4-6 أشهر. يتقلب بعض الأطفال أولًا من البطن إلى الظهر، بينما يبدأ آخرون بالعكس. إذا كان طفلكِ يحاول الالتفاف على جانبه، فهذه بداية ممتازة. لمساعدته، ضعي لعبته المفضلة إلى جانبه على مسافة لا تستطيع يده بلوغها. سيضطر إلى تدوير جسمه للوصول إليها. وهذا أفضل تمرين له.') WHERE id = '7165cb2d-519b-4d93-9e14-3abc5973a1c2';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل ما زال شعركِ يتساقط؟ عادةً ما يبلغ «تساقط الشعر بعد الولادة» ذروته في الشهر 4. قد تجعلكِ كتل الشعر في الحمّام تبكين، لكن اطمئني، فأنتِ لا تصابين بالصلع. ما يحدث هو ببساطة تساقط الشعر الذي كان «متوقفًا» خلال الحمل. لا تستطيع الفيتامينات أو أنواع الشامبو باهظة الثمن إيقاف هذه العملية؛ فهي تحتاج فقط إلى الوقت. حاولي ألا تربطي شعركِ بإحكام شديد، وتجنبي الإفراط في تجفيفه بالحرارة (مجفف الشعر). سيبدأ ظهور الشعر الجديد ("baby hair") تقريبًا بعد الشهر 6.') WHERE id = 'd0ba1bd8-2d07-4566-8111-997ecbf838c6';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في هذه المرحلة، تتحول ابتسامة طفلكِ إلى ضحكات مسموعة! ولإضحاكه، أصدري أصواتًا «غريبة»، أو حرّكي شفتيكِ لإصدار صوت طريف، أو قبّلي بطنه وانفخي عليه برفق. يقوّي الضحك الحجاب الحاجز (عضلة التنفس)، ويساعد على إدخال كمية وفيرة من الأكسجين إلى الجسم. إذا خاف وبكى بدلًا من الضحك (بسبب الصوت المرتفع)، فهذا يعني أن جهازه العصبي لا يزال شديد الحساسية. انتقلي إلى ألعاب أكثر هدوءًا. فلكل طفل حس فكاهي مختلف.') WHERE id = '7f993160-1b52-4958-82c0-d5f0cf373852';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل تفكرين في شراء «مشّاية الأطفال»، تلك التي تحب الجدات التوصية بها؟ لا تتعجلي! لا ينصح أطباء العظام وأطباء الأطفال المعاصرون باستخدام المشّاية إطلاقًا. فقد تجعل طفلكِ يعتاد المشي على أطراف أصابعه، وتحمّل عموده الفقري عبئًا مبكرًا، وتحد من نشاطه (لأنه لا يتعلم الحفاظ على توازنه). أفضل مكان للنمو والتطور هو الأرض (على سجادة أو بساط لعب). دعيه يحاول الزحف والتحرك بجهده؛ فهذه العملية الطبيعية تساعد عضلاته على النمو بصورة أكثر سلامة.') WHERE id = '58105ea4-3801-47f9-97cc-2478fe93cb03';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'يمكنكِ الآن البدء بتمارين تساعد طفلكِ على التعرّف إلى اسمه. إلى جانب مناداته بعبارات مثل "حبيبي" و"يا جميل"، خاطبيه باسمه كثيرًا. نادي اسمه من زاوية أخرى في الغرفة، ولاحظي ما إذا كان سيلتفت نحوكِ. إذا التفت ونظر إليكِ، فأظهري فرحتكِ بحماس كبير وقولي: "أحسنت!". هذه هي الخطوة الأولى في تشكّل هويته الاجتماعية، فقد بدأ يدرك أنه فرد مستقل في هذا العالم.') WHERE id = 'e2e55b95-3a42-4c60-9aac-15653d87bc0a';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في هذه المرحلة، يكون أكبر تحدٍّ تواجهه الأمهات هو ضغط "الأقارب الذين يعرفون كل شيء" بقولهم: "الطفل نحيف ولا يشبع، أعطيه العصيدة". تذكّري: امتلاء جسم طفلكِ لا يعني بالضرورة أنه بصحة جيدة. المؤشرات الأساسية هي نمو طوله ومحيط رأسه ومستوى نشاطه. إن بدء الأطعمة التكميلية في الشهر الرابع، ما لم توجد ضرورة طبية، يرهق أمعاءه ويزيد خطر الحساسية ويقلل تناوله لحليب الأم. قولي لهم "حسنًا" وتجاوزي الأمر، لكن افعلي ما تعرفين أنه صحيح واتّبعي توصيات منظمة الصحة العالمية.') WHERE id = '79a1bd17-ef80-4f02-a1a6-cec0947ec9fb';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'إذا كان طفلكِ يستطيع، أثناء الاستلقاء على بطنه (tummy time)، الارتكاز على يديه ورفع صدره بالكامل، فضعي أمامه لعبة ممتعة، ولكن على مسافة لا يستطيع الوصول إليها. سيحاول تغيير مركز ثقله للوصول إلى اللعبة، وربما يرفع إحدى يديه عن الأرض. يُعدّ "تمرين التوازن" هذا مهمًا جدًا لتعلّم الحبو مستقبلًا. وإذا لم يستطع وشعر بالانزعاج، فقرّبي اللعبة قليلًا حتى لا يفقد حماسه.') WHERE id = '9069addc-9d36-4d58-8ceb-48b115881ebe';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل بدأت الأصوات التي يصدرها طفلكِ تنتقل من حروف العلة مثل "آ-أو" إلى الحروف الساكنة مثل "م-ب-پ"؟ قد يصدر مصادفةً أصواتًا مثل "ما-ما" و"با-با". هذا لا يعني أنه يناديكِ بوعي، على الأقل حتى الآن، بل إنه يمرّن عضلات شفتيه فحسب. لكن استجيبي له بحماس كبير وقولي: "نعم، أنا ماما!". سيشجعه تفاعلكِ على تكرار هذه الأصوات وتطوير مهاراته اللغوية.') WHERE id = '124a08e0-8297-466a-ad92-5da9e2b40124';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في الشهر الرابع، يمكنكِ إنشاء "ارتباطات النوم" (Sleep Associations) للمساعدة على تنظيم نوم طفلكِ. إذا اعتاد ألا ينام إلا أثناء الرضاعة أو الهز، فابدئي بتغيير ذلك تدريجيًا. على سبيل المثال، ضعيه في سريره عندما يبدأ بالنعاس، قبل أن ينام تمامًا، وضعي يدكِ عليه بهدوء وقولي: "ششش". قد يعترض في الأيام الأولى، لكن إذا تحلّيتِ بالصبر، فسيبدأ بتعلّم تهدئة نفسه (self-soothing). إنها رحلة طويلة، فلا تتعجّلي.') WHERE id = '440c73d7-8d87-4380-afc8-4a3037eff65e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تهانينا! لقد أتمّ طفلكِ شهره الرابع! إنها المرحلة الذهبية من فترة الرضاعة؛ فلم يعد صغيرًا جدًا وعاجزًا، ولم يصبح بعد كثير الحركة ومتعبًا. خلال الفحص الطبي هذا الشهر، قد تجدين أن وزنه أصبح نحو ضعف وزنه عند الولادة، وهذا معدل تقريبي. أصبح الآن يرى الألوان ويتعرّف إلى الأصوات، وهو مغرم بكِ. استمتعي بهذه المرحلة، فسرعان ما ستبدأ مغامرات التسنين والحبو! أنتِ تقومين بعمل رائع يا ماما!') WHERE id = 'c7fd582a-aa6d-4d77-b362-3fa53514647a';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'إذا بدأتِ تسمعين أسئلة مثل: "هل يستطيع طفلكِ الجلوس؟"، فلا تتعجلي. إن إجبار رضيعكِ على الجلوس بين الوسائد وهو لم يصبح مستعدًا بعد قد يضر بعموده الفقري. في الشهر 5، قد يحاول الأطفال اتخاذ "وضعية الجلوس الثلاثي" (الاستناد إلى اليدين الممدودتين إلى الأمام)، لكنهم لا يستطيعون بعد الحفاظ على توازنهم بشكل كامل. أفضل تمرين له هو اللعب على الأرض وهو مستلقٍ على بطنه. ومع تقوّي عضلات ظهره، سينهض ويجلس من تلقاء نفسه.') WHERE id = 'e21494e3-d1b4-470c-8b69-91bdff0641cb';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل عادت نصيحة الجدات: "أعطيه قليلًا من مرق الحساء ليتذوقه" إلى الواجهة؟ يجب أن تعلمي أن أمعاء رضيعكِ لا تزال أشبه بـ"المصفاة" (أي إن نفاذية الأمعاء مرتفعة). وأي طعام يُقدَّم له غير حليب الأم أو الحليب الصناعي (حتى الماء أو العصير) قد يعبر هذا الحاجز ويسبب الحساسية ومشكلات الهضم. سيكون أمامه متسع من الوقت "لاكتشاف المذاقات"، أما الآن فالهدف الأساسي هو حماية البكتيريا النافعة في أمعائه. أنتِ لستِ "كنّة سيئة"، بل "أم واعية".') WHERE id = '2049b273-04ed-4768-bc4b-392861691428';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل يخيفكِ أن يتقلب رضيعكِ من تلقاء نفسه أثناء نومه ليلًا وينام على بطنه؟ إذا كان يستطيع خلال النهار التقلب بحرية في الاتجاهين (من الظهر إلى البطن ومن البطن إلى الظهر)، فلا داعي لإعادته إلى وضعه السابق في كل مرة ليلًا. تأكدي فقط من خلو سريره من الوسائد والبطانيات والألعاب المحشوة لتجنب خطر الاختناق. سيختار بنفسه الوضعية التي تريحه. ونامي أنتِ أيضًا مطمئنة.') WHERE id = '75eb58f4-2826-4a4a-8b58-b49e3d0b9d70';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'قد يبدأ شعر رضيعكِ بالتساقط هذا الشهر لينمو مكانه شعر جديد (تبدّل "شعر الرضيع"). وقد تظهر أحيانًا "بقعة صلعاء" في مؤخرة رأسه، وهذا يحدث ببساطة بسبب الاحتكاك الناتج عن الاستلقاء لفترات طويلة، وهو أمر طبيعي تمامًا. عندما يبدأ بالجلوس والحركة أكثر، سينمو شعره بالتساوي. هذا ليس ناتجًا عن نقص الفيتامينات، فلا تقلقي.') WHERE id = 'f63f93ff-407c-4880-934c-4db268020afd';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح رضيعكِ الآن يرى الأشياء الصغيرة (مثل ذرة غبار على الأرض أو خيط على ملابسه) ويحاول التقاطها بأصابعه. فقد تطور بصره إلى درجة تمكّنه من تمييز التفاصيل الدقيقة. في هذه المرحلة، السلامة هي القاعدة رقم 1. أبقي الأزرار والعملات المعدنية والأقراط وكل الأشياء الصغيرة بعيدًا عن متناول يده. فهو لا يزال يستكشف العالم بفمه وسيتذوق كل ما يعثر عليه.') WHERE id = '50867048-47ec-4339-857c-cdebcdc6c314';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل تفكرين في شراء مشّاية أطفال؟ أعيدي التفكير. يُحظر بيع هذا الجهاز في كثير من الدول المتقدمة (مثل كندا). والسبب أنه قد يجعل رضيعكِ يمشي على أطراف أصابعه دون أن يضع كعبيه على الأرض، ويحمّل عموده الفقري عبئًا مبكرًا، والأهم أنه يمكّنه من الوصول سريعًا إلى الأماكن الخطرة (مثل إبريق الشاي الساخن أو الدرج). الأرضية هي أفضل وسيلة لدعم نموه. دعيه يزحف ليقوّي عضلاته.') WHERE id = '700936b7-4cd2-492b-9509-98a14c16e71e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحبًا بالشهر الخامس! لم يعد ذلك "الرضيع الصغير الملفوف" موجودًا في المنزل، بل حلّت مكانه شخصية فضولية تضحك وتصرخ وتتحرك. سيتسارع نموه الجسدي أكثر هذا الشهر: التقلّب، ونقل الأشياء من يد إلى أخرى، وربما أولى محاولات الزحف... ما عليكِ سوى تهيئة بيئة آمنة له (بساط مفروش على الأرض) ومراقبته من بعيد. أحيانًا يكون عدم التدخل أفضل مساعدة.') WHERE id = 'ab2e9390-020b-4160-8af0-d640595e2268';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل يضمّ رضيعكِ شفتيه ويُصدر صوتًا نافخًا (فيُكوّن فقاعات من اللعاب)؟ إنه لا يفعل ذلك لمجرد أن يبتلّ ويُضحككِ! فهذه الحركة تدرّب عضلات اللسان والشفتين والفك، وهي مهمة جدًا لتطور النطق لديه. كما أنه يتعلم آلية إصدار الأصوات: "عندما أحرّك شفتيّ هكذا، يصدر هذا الصوت". لا تقولي له "عيب"، بل شاركيه وقلّدي هذا الصوت. هذا "الحوار" هو أكثر ألعاب العالم تشويقًا بالنسبة إليه.') WHERE id = 'ea92481c-f89e-4020-bcda-f62d11c6d1f3';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبحت يدا رضيعكِ الآن أكثر مهارة. هل يستطيع إمساك اللعبة بيد، ثم نقلها إلى اليد الأخرى؟ تُظهر مهارة "عبور خط المنتصف" (crossing the midline) أن التواصل بين نصفي الدماغ يزداد قوة. أعطيه لعبتين مختلفتين لتنمية هذه المهارة: واحدة في يده اليمنى والأخرى في اليسرى. ثم قدّمي له لعبة ثالثة. راقبي هل سيلقي إحدى اللعبتين اللتين في يديه ليمسك بالثالثة؟ هذه أول لحظة "لاتخاذ القرار" في حياته.') WHERE id = 'c16f8e30-0e77-4445-93ae-cd9830a7f241';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في الشهر الخامس، يرى الرضّع الألوان بوضوح شديد، وخصوصًا الأحمر والأزرق والأصفر. وفي الوقت نفسه، يبدأ إدراك العمق (الرؤية ثلاثية الأبعاد) بالتطور. أصبح طفلكِ الآن قادرًا على تقدير مدى بُعد اللعبة ومدّ يده إليها مباشرة. خلال هذه الفترة، يساعد وضعه أمام المرآة أو اللعب معه بالكرات الملوّنة على تحسين التناسق البصري لديه. إذا كنتِ لا تزالين تلاحظين الحَوَل (اتجاه العينين نحو بعضهما من حين إلى آخر)، فيُفترض أن يقل خلال هذا الشهر؛ وإذا استمر، فمن الأفضل عرضه على الطبيب.') WHERE id = '1f034b11-0fbb-48ea-bbf4-278ca6b86b2b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل يضمّ رضيعكِ شفتيه ويبكي عندما يحمله شخص آخر (حتى لو كانت جدته أو خالته)؟ كثيرًا ما تشعر الأمهات بالحرج من ذلك ويحزنّ قائلين: "طفلي لا يألف الغرباء". لكن هذا في الحقيقة دليل على نمو قدراته العقلية! فقد أصبح الآن يدرك الفرق بين "المألوف" (أنتِ ووالده) و"الغريب" (الآخرون). إن "الخوف من الغرباء" (stranger anxiety) مرحلة طبيعية من النمو. لا تجبريه على الانتقال إلى حضن شخص آخر، بل دعيه أولًا يتعرّف إلى ذلك الشخص وهو في حضنكِ حتى يشعر بالأمان والثقة.') WHERE id = 'c6a4085b-3a97-4e0b-b5f5-5b36782649fe';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل تزداد الاقتراحات من قبيل: "الطفل لا يشبع ويستيقظ ليلًا، فلنُطعمه بعض العصيدة"؟ تذكّري أن الاستيقاظ ليلًا لا يكون غالبًا بسبب الجوع، بل نتيجة تغيّر دورات النوم أو تهيّج اللثة بسبب التسنين أو لمجرد رغبته في وجودكِ. لم يكتمل نمو الجهاز الهضمي لرضيع عمره ٥ أشهر بعد (فالإنزيمات ليست كافية). يزيد البدء المبكر بالأطعمة التكميلية خطر الحساسية، وقد يؤدي إلى انخفاض إدرار حليب الأم. وما زالت توصية منظمة الصحة العالمية ثابتة: الحليب فقط خلال الأشهر الستة الأولى. لا تتعجلي، فما زال العمر كله أمامه ليمسك بالملعقة.') WHERE id = 'c26a80c4-409b-4945-b7d2-51c416190946';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'يواصل طفلكِ اكتشاف قدميه. إذا كان يضع أصابع قدميه في فمه ويمصّها، فلا تمنعيه. تساعد هذه الحركة على زيادة مرونة عموده الفقري، وفتح مفصل الورك، وإيجاد توازن جسمه. وفي الوقت نفسه، يتعرّف من خلالها إلى حدود جسمه ("آه، هذا الإصبع يخصني أيضًا"). انزعي جواربه ودعيه "يتذوق" قدميه.') WHERE id = '0696d902-62ea-41fb-ac33-42f63be246d0';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لقد ازداد وزن طفلكِ كثيرًا الآن (وقد يبلغ نحو 6-8 kq)، وحمله باستمرار بين ذراعيكِ يشكّل عبئًا كبيرًا على عمودكِ الفقري. انتبهي إلى قواعد "الحمل المريح للجسم": ادعمي طفلكِ من منطقة الوركين ووزّعي الوزن، وتجنبي حمله على جانب واحد فقط (على خصركِ الأيمن أو الأيسر)، لأن ذلك قد يؤدي إلى انحراف العمود الفقري. اختاري اللعب على الأرض قدر الإمكان. فصحة ظهركِ ضرورية لتتمكني من رعاية طفلكِ.') WHERE id = 'd400ec9f-412b-4ad6-988e-58b62c0416fd';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل يرمي طفلكِ اللعبة على الأرض، فتلتقطينها، ثم يرميها مجددًا ويضحك؟ قد يزعجكِ ذلك، لكنه بالنسبة إليه تجربة فيزيائية! إنه يتعلم علاقة "السبب والنتيجة": "أنا أرميها (السبب)، فتلتقطها أمي (النتيجة)، أو يصدر عنها صوت". تجعله هذه اللعبة يشعر بأنه قادر على التأثير في العالم من حوله. لا تنزعجي، وتذكري أن ذلك مهم لنموه، ثم واصلي اللعب بصبر (أو باستخدام ألعاب مربوطة بخيط).') WHERE id = 'fe5f82f2-00a9-4854-b3e5-0b8ebb578153';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'بدأ نوم طفلكِ نهارًا ينتظم الآن ("مرحلة انتقال القيلولات"). وقد تحلّ 3 قيلولات أطول يوميًا (صباحًا وظهرًا وفي آخر النهار) محل القيلولات السابقة القصيرة والمتفرقة. عادةً ما تكون القيلولة الأخيرة قصيرة (30-40 dəq)، وتسهّل الانتقال إلى النوم ليلًا. إذا كان نومه لا يزال غير منتظم، فراقبي "نافذة النوم" (مدة بقائه مستيقظًا)، وحاولي تنويمه قبل أن يصاب بالإرهاق الشديد. فالنوم يجلب النوم.') WHERE id = '5d110284-d82d-4dbe-8144-2a516161ad7f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل يضع طفلكِ قدميه في فمه وكأنه "يتذوقهما"؟ قد يبدو هذا المشهد مضحكًا جدًا، لكنه في الحقيقة تطور رائع يدل على مرونة عموده الفقري وتناسق حركات جسمه. إنه يكتشف الجزء السفلي من جسمه. فلا تمنعيه من ذلك (وانزعي جواربه ليشعر براحة أكبر). كما تساعد هذه الحركة على تخفيف مغص الغازات طبيعيًا.') WHERE id = '66fe21ca-05fd-4c48-95fa-5f031cadebb2';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في الشهر 5، يحب الأطفال الصراخ وإصدار الأصوات الحادة ورفع أصواتهم. قد تكون هذه الضوضاء مزعجة للأذن أحيانًا، لكن لا تقلقي، فهو ليس غاضبًا منكِ. إنه فقط "يختبر" أحباله الصوتية: "يا ترى، إلى أي حد يمكنني أن أصرخ بصوت مرتفع؟". هكذا يتعلم التحكم في صوته. ردّي عليه بالهمس، وسيحاول تقليدكِ وخفض صوته أيضًا. إنها لعبة رائعة.') WHERE id = 'd03675dd-580b-4a83-a42a-a1376cb7a774';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'قد تضعف مناعة رضيعكِ قليلًا في فترة التسنين، لكن لا تخلطي بين «حمّى التسنين» و«العدوى الفيروسية». عند التسنين، لا تتجاوز الحرارة عادةً 38 درجة، ولا تظهر أعراض مثل سيلان الأنف أو السعال. إذا كانت الحرارة مرتفعة وكان رضيعكِ خاملًا، فلا تفترضي أن السبب هو التسنين وتطمئني، بل احرصي على إبلاغ طبيبه.') WHERE id = 'ec752558-6d74-4751-872c-b47b29cef0cb';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'قد تعود الدورة الشهرية لدى الأمهات خلال هذه الفترة؛ لدى بعضهن أبكر ولدى أخريات لاحقًا. والاعتقاد بأن «الأم المرضعة لا تأتيها الدورة الشهرية» مجرد خرافة. عند عودة الدورة الشهرية، قد تقل كمية الحليب قليلًا أو يتغير مذاقه بسبب الهرمونات، وقد يعترض رضيعكِ على ذلك. لكن جودة الحليب لا تتدهور ولا يصبح «سامًا». واصلي الرضاعة الطبيعية، فهذه حالة مؤقتة.') WHERE id = 'ad62d3cf-28a5-411d-86f8-d16d19e156b2';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل أصبح طفلكِ يحب ضرب اللعبة التي يمسكها بالأرض أو طرقها على الطاولة؟ هذا ليس سلوكًا تخريبيًا، بل هو نوع من «هندسة الأصوات» لديه! فهو يكتشف الصوت الناتج عن اصطدام جسم صلب بسطح صلب. وبدلًا من منعه، أعطيه أشياءً تُصدر أصواتًا مختلفة، مثل ملعقة خشبية ووعاء بلاستيكي ولعبة طرية. اشرحي له الفرق قائلةً: «انظر، هذا يُصدر صوتًا عند الطرق، أما هذا فلا يُصدر صوتًا».') WHERE id = '62ce75ea-f714-4996-ae9c-54a3b27495ac';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'حان الوقت تمامًا لتعزيز إجراءات سلامة الطفل في المنزل («Babyproofing»). حتى إن لم يكن رضيعكِ يحبو بعد، فقد يصل بالتدحرج أو الزحف على بطنه إلى مقابس الكهرباء أو الأسلاك المتدلية أو طرف مفرش الطاولة. انزلي إلى مستواه واستلقي على الأرض، ثم تفحّصي المنزل بعينيه: ما الذي يبدو خطرًا على الأرض؟ أبعدي جميع الأشياء التي قد تشكل خطرًا، فالحوادث لا تنبّه قبل وقوعها.') WHERE id = 'aff088aa-a1cd-4138-acbc-e2c0688efeb6';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'إذا ظهرت على جلد رضيعكِ بقع جافة أو احمرار (التهاب الجلد التأتبي/الإكزيما)، فلا تلومي طعامكِ أو نظامكِ الغذائي فورًا. غالبًا لا يكون السبب هو الطعام، بل عوامل البيئة المحيطة، مثل الهواء الجاف أو الملابس الاصطناعية أو مسحوق الغسيل أو الاستحمام بماء شديد السخونة. ارفعي مستوى الرطوبة في الغرفة، ودلّكي جلد رضيعكِ بكريمات مرطبة (المطرّيات)، وبعد الاستحمام جففي بشرته بالتربيت برفق بدلًا من فركها.') WHERE id = '572d9eb0-1241-494b-9f36-13d0ee848f80';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تهانينا! أتمّ رضيعكِ شهره 5! لم يتبقَّ سوى القليل حتى يبلغ نصف عام (6 أشهر). هذا الشهر مرحلة انتقالية كبيرة بالنسبة إليه؛ فقد أصبح يعبّر عن مشاعره بوضوح أكبر، فيصرخ فرحًا ويدفع ما لا يريده بعيدًا. وأنتِ أيضًا قطعتِ رحلة مذهلة خلال هذه الأشهر الـ5. فرغم الليالي التي قضيتِها بلا نوم والإرهاق، تظلين محور عالمه. قولي لنفسكِ «شكرًا جزيلًا»، واحتفلي بهذا اليوم بابتسامة صغيرة!') WHERE id = '7802c1ee-5da4-41a5-a0b7-633ee14ee9a9';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل تشعرين بأنكِ مهملة ومتعبة عندما تنظرين إلى المرآة؟ قد تبدو إجازة الأمومة أحيانًا مثل "يوم جرذ الأرض"، حيث يتكرر اليوم نفسه. اتركي طفلكِ اليوم مع والده أو جدته واخرجي من المنزل لمدة 1 ساعة. فمجرد الذهاب إلى المتجر أو التنزه بمفردكِ في الحديقة أو قص شعركِ سيمنحكِ شعورًا وكأنكِ وضعتِ "قناع الأكسجين". عندما تكونين سعيدة، سيكون طفلكِ سعيدًا أيضًا.') WHERE id = '3c6e4f71-0ba2-4930-a133-04552c20e1dd';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تهانينا، أنتِ في منتصف الشهر الـ5! قد لا تزداد أوزان طفلكِ الآن بالسرعة نفسها التي كانت عليها في الأشهر الأولى (400-500 qr شهريًا بدلًا من 1 kq). هذا طبيعي، لأنه يتحرك أكثر ويستهلك طاقة أكبر. ما دام "المنحنى" في مخطط الطبيب يتجه إلى الأعلى، فلا توجد مشكلة. لا ترهقي نفسكِ بالقلق والتفكير: "قلّ حليبي وخسر طفلي وزنه"، بل استمتعي بنشاطه فحسب.') WHERE id = '77295e93-c83b-4ff4-8d09-da9b139b8a65';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل يفتح طفلكِ فمه عندما تتناولين الطعام، أو يراقبكِ باهتمام، أو يمد يده نحو طبقكِ؟ هذا ما يُسمى "الاهتمام البيولوجي بالطعام". إنه يريد تقليدكِ، ولا يعني ذلك بالضرورة أنه جائع. ولا يكفي الاهتمام وحده لبدء تقديم الأطعمة التكميلية؛ إذ يجب أن يكون طفلكِ قادرًا على إبقاء رأسه منتصبًا، والجلوس دون دعم (أو بقليل من الدعم)، والأهم من ذلك أن يختفي لديه "منعكس دفع اللسان"، أي دفع الطعام إلى الخارج بلسانه. أعطيه حاليًا ملعقة فارغة ليلعب بها، لكن تحلّي بقليل من الصبر قبل تقديم الطعام.') WHERE id = '7853d6dc-3fa1-4c99-9bee-ffadc85c9246';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'عندما يستلقي طفلكِ على بطنه، هل يرفع ذراعيه وساقيه في الهواء وكأنه يطير مثل "سوبرمان"؟ رغم أن هذه الحركة تبدو لطيفة جدًا، فإنها في الواقع تمرين شاق. فهو يقوّي عضلات ظهره ورقبته ووركيه استعدادًا للحبو والجلوس مستقبلًا. لا تعيقيه أثناء ذلك، بل حفّزيه بوضع لعبة ممتعة أمامه.') WHERE id = 'ee5e432a-11cb-49f0-b780-4af770910a6e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في الشهر الـ5، قد يصدر الأطفال أحيانًا أصواتًا غريبة، مثل الحشرجة أو تقليد السعال أو الصرخات العالية. وبينما تستعدين للذهاب إلى الطبيب خوفًا، قد يبتسم لكِ طفلكِ. إنها "تجربة" يجريها وهو يكتشف أحباله الصوتية. فهو يتعلم أي حركة تُصدر أي صوت. إذا لم تكن لديه حمى أو أي علامات مرضية أخرى، فاستمتعي بهذا "الحفل" فحسب.') WHERE id = 'b8f6e7f4-fa6c-4da7-b344-5fdbda538ecd';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'إذا لاحظتِ أن طفلكِ يدير رأسه دائمًا إلى الجهة نفسها أثناء النوم، أو أن هناك تسطحًا في مؤخرة رأسه، فغيّري اتجاه اللعب معه خلال وقت استيقاظه. إذا كنتِ تقتربين منه عادةً من الجهة اليمنى، فتحدثي إليه الآن من الجهة اليسرى. وغيّري موضع سريره ليضطر إلى إدارة رأسه نحو الجهة الأخرى كي ينظر إلى الضوء أو إليكِ. سيساعد هذا التغيير البسيط على نمو عضلات رقبته بشكل متوازن.') WHERE id = 'b66d2212-4a92-4a46-b745-aeb8c99cd2a4';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحبًا بكِ في اليوم الأول من الشهر 6! لقد أصبح موضوع "التغذية التكميلية" الآن الموضوع الأكثر تداولًا في المنزل. قد تستعجلكِ الجدات، لكن تذكّري القاعدة الذهبية لمنظمة الصحة العالمية: حتى إتمام عمر 6 أشهر، يجب الاكتفاء بحليب الأم (أو الحليب الصناعي). ومع ذلك، يمكنكِ البدء بالاستعداد! تحقّقي مما إذا كان طفلكِ مستعدًا: هل يستطيع الجلوس دون دعم؟ هل يثبّت رأسه منتصبًا؟ هل يُظهر اهتمامًا بالطعام ويحرك فمه عندما تتناولين الطعام؟ إذا كانت الإجابات "نعم"، فالمغامرة باتت قريبة.') WHERE id = 'c07d39a8-4230-4141-b911-a428b18acb0f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل يعضّكِ طفلكِ أثناء الرضاعة؟ قد يعني ذلك أن لثته تؤلمه أو أنه قد شبع ويريد اللعب. لا تصرخي فتُخيفيه، فقد يؤدي ذلك إلى رفضه الرضاعة. قولي له بهدوء "لا" وأخرجي الثدي من فمه (بإدخال إصبعكِ الخنصر في زاوية فمه لفك الشفط). عندما يفهم أن العض ينهي الرضاعة، فلن يكرره. وستكون عضّاضات التسنين الباردة أفضل حليف لكِ لمواجهة العض.') WHERE id = '1c9ac763-40c0-4c2c-9037-aa4d0926c708';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لا تتعجّلي في استخدام "حصون الوسائد" لإجلاس طفلكِ. فإذا لم يحاول الجلوس بنفسه وكان ظهره منحنيًا على شكل حرف "C" (وضعية منحنية)، فهذا يعني أن عضلاته ليست مستعدة بعد. وقد يضر إجلاسه قسرًا بعموده الفقري. دعيه يقضي وقتًا أطول على الأرض، وسيصل بنفسه إلى وضعية "الحامل الثلاثي" (بوضع يديه أمامه). فالتطور الطبيعي هو الأكثر أمانًا دائمًا.') WHERE id = '026af185-68d2-497b-b2e5-6cbcde3b4230';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'كوني شديدة الحذر عند استخدام جل التسنين. فالأنواع التي تحتوي على "Lidokain" أو "Benzokain" قد تشكل خطرًا جسيمًا على الرضّع (بسبب خطر صعوبة البلع واضطرابات نظم القلب). ولا توصي إدارة الغذاء والدواء الأمريكية (FDA) باستخدام هذه المواد للرضّع. وبدلًا منها، تُعد أنواع الجل ذات المكونات الطبيعية، أو الألعاب المطاطية المبردة فحسب، أو تدليك اللثة بشاش رطب خيارات أكثر أمانًا وفعالية.') WHERE id = 'd57483e9-dfea-4122-86d2-ac70acfdcbfd';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'عندما يستلقي طفلكِ على بطنه، هل بدأ يدفع الأرض بيديه ويتحرك إلى الخلف ("مثل السلطعون")؟ هذه هي المرحلة الأولى من الحبو! إنه يريد التقدم إلى الأمام، لكن ذراعيه أقوى من ساقيه، لذلك يتحرك إلى الخلف. وقد يزعجه ذلك. لمساعدته، ضعي يدكِ خلف باطن قدميه لتكون دعامة تمكّنه من دفع نفسه إلى الأمام. تحلّي بالصبر، فسرعان ما سيغزو المنزل كله.') WHERE id = '1cfdff71-da32-4931-b5cb-94e1a37d4db0';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'قد يضطرب نوم طفلكِ مجددًا هذا الشهر، لكن السبب هذه المرة قد يكون "قلق الانفصال" (separation anxiety). فعندما تغادرين الغرفة، قد يشعر وكأنكِ "تركته". ابقي بجانبه مدة أطول قليلًا عند تنويمه ولمسيه، لكن لا تتعجّلي في حمله والتجول به (وإلا فقد يعتاد على ذلك). علّميه من خلال لعبة "Ce-ee" (الغميضة) أن أمه تذهب ثم تعود. هذا الخوف مؤقت، أما شعوره بالأمان فدائم.') WHERE id = 'bda07f09-37eb-4be3-a16a-4bf2694b38b8';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'يصبح سؤال "متى نبدأ بإعطائه الماء؟" مطروحًا الآن. في اليوم الذي تبدئين فيه بإدخال الطعام التكميلي (الطعام الصلب)، عليكِ البدء أيضًا بإعطائه الماء. أما الآن، فإذا لم تكوني قد بدأتِ بتقديم الطعام الصلب بعد، فلا حاجة إلى الماء؛ فحليب الأم/الحليب الصناعي كافٍ. يمكنكِ من الآن شراء "كوب ماء" صغير مانع للانسكاب (sipper cup) وتعريفه إليه من دون ملئه بالماء. دعيه يمسكه بيده ويقرّبه من فمه ويلعب به كلعبة. وهكذا، عندما يحين الوقت، سيكون مألوفًا لديه.') WHERE id = 'ff09c584-fe70-41cf-951d-eb545f630c39';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل أصبح تغيير حفاض طفلكِ أشبه بمباراة مصارعة؟ فهو لا يبقى ساكنًا، بل يتقلب ويحاول الهرب. هذا لأنه يستمتع بحرية الحركة. لا تنزعجي، بل استخدمي بعض الحيل: عند تغيير حفاضه، أعطيه شيئًا مثيرًا للاهتمام لم يره من قبل (مثل علبة كريم نظيفة)، أو شتتي انتباهه بالغناء. وقد تضطرين أحيانًا إلى تغيير حفاضه وهو واقف أو يزحف؛ وهذه مهارة من مهارات الأمومة!') WHERE id = '5c0bcce8-2d98-4e33-ab73-d613b0c76c24';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل يكرر طفلكِ مقاطع مثل "با-با" و"دا-دا" و"ما-ما"؟ عادةً ما يفرح الآباء قائلين: "قال بابا!"، لكن هذا لا يُعدّ نداءً مقصودًا بعد، بل مجرد تمرين على إصدار الأصوات (المناغاة). ومع ذلك، امنحي هذه الأصوات معنى: "نعم، هذا بابا!"، "نعم، أنا ماما!". عندما تربطين هذه الكلمات بالأشياء أو الأشخاص، فإنكِ تساهمين في تكوين حصيلته اللغوية في دماغه. وسرعان ما سيبدأ باستخدام هذه الكلمات عن قصد.') WHERE id = 'ea83f521-c253-469b-809a-6bfb8bc161b2';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لم يتبقَّ سوى 20 يومًا حتى يبلغ طفلكِ 6 أشهر (نصف عام)! هل اخترتِ "كرسي الطعام" لتبدئي بإدخال الطعام التكميلي؟ أهم شرط عند اختيار الكرسي هو أن يبقى ظهر طفلكِ مستقيمًا وأن ترتكز قدماه حتمًا على مسند للقدمين. فالطفل الذي تبقى قدماه معلقتين في الهواء يشعر بعدم الارتياح ولا يستطيع التركيز على تناول الطعام. ليس من الضروري أن يكون الكرسي من علامة تجارية باهظة الثمن؛ يكفي أن يكون مريحًا ومصممًا وفق مبادئ السلامة وسهل التنظيف (لأنه سيتسخ كثيرًا!).') WHERE id = '5376c7fc-e6df-4f63-941d-2e00e5209d33';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل بدأتِ بشراء مستلزمات الاستعداد لإدخال الطعام التكميلي؟ أولًا، من المهم اختيار ملعقة مخصصة لطفلكِ. فقد تؤذي الملاعق المعدنية حنكه الحساس، كما أنها تنقل الحرارة بسرعة وقد تحرق لسانه. الخيار الأفضل هو ملعقة صغيرة ذات طرف ناعم من السيليكون ومقبض طويل. أما فكرة "سأطعمه بملعقة كبيرة ليشبع بسرعة" فهي خاطئة؛ فكلما كانت الملعقة أصغر، كان تكيّف منعكس البلع لديه أسهل. كما ستزيد الملاعق الملونة اهتمامه بالطعام.') WHERE id = '1d96ab29-9c6c-4bb8-ba1f-f5f3f11a1dbb';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل يستيقظ طفلكِ ليلًا فجأة وهو يبكي ويصعب تهدئته؟ مع اقتراب الشهر 6، قد يزداد شعوره بالضغط في اللثة ليلًا، لأن تدفق الدم إلى الرأس يزداد عند الاستلقاء. لا تنزعجي منه، فهو يتألم فحسب. قد يساعد تدليك لثته بلطف قبل النوم بإصبعكِ النظيف أو بفرشاة سيليكون مخصصة على تحسين الدورة الدموية وتخفيف انزعاجه. تحلّي بالصبر؛ فعندما تظهر تلك "اللآلئ" الصغيرة، ستنسين كل الليالي التي قضيتِها بلا نوم.') WHERE id = '4bb38a42-9207-48cc-87a0-6e8506859c1d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لا تحبسي طفلكِ على الأريكة أو في سريره استجابةً لكلام الكبار الذين يقولون: «الأرض باردة، ستمرضين الطفل». سجادة نظيفة أو بساط لعب مخصص (بساط الأحجية) هو أفضل صالة رياضية لطفلكِ. إذا كنتِ تخشين عليه من البرد، فما عليكِ سوى اختيار ملابس مناسبة له (جوارب أو سروال قطني). كلما تقلب على الأرض وزحف وحاول الحركة أكثر، قويت عضلاته بوتيرة أسرع. قلة الحركة هي أكبر عدو يبطئ نموه وتطوره.') WHERE id = '5ed49a9c-59aa-4f08-b836-cd7056d33992';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لا تنتظري حتى يبدأ طفلكِ بالكلام كي تقرئي الكتب معه. فهذا هو الوقت المثالي لشراء كتب «اللمس والاستكشاف» (touch and feel) أو الكتب التي تُصدر أصوات حفيف. سيحاول تقليب الصفحات (وهو تمرين رائع للمهارات الحركية الدقيقة)، وسيربت على الصور، وربما يقضم الكتاب أيضًا. إنها بداية «حب الكتب». أشيري له إلى الحيوانات وقلّدي أصواتها («ماذا تقول البقرة؟ مووو!»). هذه اللعبة البسيطة تثري مفرداته الاستقبالية.') WHERE id = 'a556f86c-ce31-4428-944f-44af737aa8ba';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'عندما يحاول طفلكِ الجلوس، هل يضع يديه أمامه محاولًا الحفاظ على توازنه (بوضعية المثلث/الحامل الثلاثي)؟ هذه علامة رائعة! لكن لا تتركيه من دون دعم تمامًا بعد، فقد يسقط فجأة إلى الخلف أو على أحد جانبيه. ضعي وسائد حوله (خلفه وعلى جانبيه) لتشكيل «دائرة أمان». لكن لا تحشريه بين الوسائد وتمنعيه من الحركة؛ بل دعيه يتعلم التحكم في جسمه ليجد توازنه بنفسه.') WHERE id = '75dd1faa-e49b-4521-a298-8ff13485c3cb';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لماذا نبدأ بإدخال الأغذية التكميلية عند عمر 6 أشهر تحديدًا؟ السبب لا يتعلق بالمعدة وحدها، بل بالدم أيضًا. فمخزون الحديد (الفيريتين) الذي كوّنه الطفل في رحم أمه يبدأ بالنفاد عند الشهر السادس تقريبًا، ولا يعود الحديد الموجود في حليب الأم كافيًا لتلبية احتياجاته المتزايدة بالكامل. لذلك تُختار الأطعمة الأولى عادةً من الأغذية الغنية بالحديد (مثل اللحوم والحبوب المدعّمة بالحديد). هذه ضرورة فسيولوجية وليست مجرد مسألة «شعور بالشبع».') WHERE id = 'd0ee725f-9b61-4b89-bc59-14a2829f8036';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لا تهملي «حزام الأمان» في كرسي الطعام المرتفع. ومن أكبر الأخطاء أن تفكري: «طفلي لا يتحرك بعد، فإلى أين سيذهب؟». يمكن للرضع أن ينزلقوا إلى الأسفل أو يحاولوا الوقوف خلال ثانية واحدة. كذلك، يجب أن يحتوي الكرسي على «مسند للقدمين» (footrest). فقد يواجه الطفل الذي تتدلى قدماه في الهواء صعوبة أثناء البلع (ويزداد خطر الاختناق). عندما تستقر قدماه على المسند، يصبح جسمه أكثر ثباتًا وتكون عملية البلع أكثر أمانًا.') WHERE id = '625e4f6a-1f8a-44b3-838c-95a927b0b1a5';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'قد يزداد في هذه الفترة خوف «ذهبت أمي!» أو قلق الانفصال (Separation Anxiety). إذا بكى طفلكِ عندما تغادرين الغرفة، فواصلي التحدث إليه من خلف الباب: «أنا هنا، أسمعك، وسآتي الآن». سيمنحه صوتكِ الطمأنينة. كذلك، أكثري من لعب «الغميضة» (Pee-ka-boo) معه. تعلّمه هذه اللعبة أن الأشخاص حتى إن اختفوا (أو غطوا وجوههم)، فإنهم سيعودون حتمًا. إنها تمرين نفسي.') WHERE id = '422035de-73c2-492a-bbec-313984910971';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'عند البدء بالأطعمة التكميلية، سيكون تقديم الماء مهمًا أيضًا. عرّفي رضيعكِ من الآن إلى «كوب الماء» (كوب التدريب أو كوب صغير عادي). ضعي فيه كمية قليلة جدًا من الماء (رشفة واحدة)، أو قدّميه فارغًا. دعيه يتعلم إمساك الكوب ورفعه إلى فمه وإمالته بالزاوية المناسبة (مع إرجاع رأسه إلى الخلف). وعلى عكس الشرب من زجاجة الرضاعة، يتطلب الشرب من الكوب تنسيقًا مختلفًا تمامًا بين الفم واللسان.') WHERE id = '276120aa-1546-4b32-a95c-f7c80f3724d7';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل تصدقين؟ لم يتبقَّ سوى 10 أيام حتى يبلغ طفلكِ نصف عام (6 أشهر)! إنها مرحلة مهمة جدًا. لقد أصبح طفلكِ شبه مستعد ليكون «طفلًا كبيرًا». التقطي له الصور وسجّلي مقاطع الفيديو خلال هذه الأيام. قارني بين ذلك الرضيع الهادئ المنكمش في أشهره الأولى وبين المستكشف النشيط الذي ترينه الآن. لم تمنحيه الحليب فحسب، بل منحتِه أيضًا الأمان والحب والشجاعة. استمتعي بالأيام الـ10 الأخيرة، لأن مرحلة «المرايل الملطخة» و«معارك الملاعق» على وشك أن تبدأ!') WHERE id = 'eeef4f12-67b6-4638-9c3f-cfa2a5c6b644';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحبًا بكِ في الأيام العشرة الأخيرة من الشهر 6! بلغت الآن تحضيرات المطبخ للأطعمة التكميلية ذروتها. عادةً ما تكون مهروسات الخضراوات (مثل الكوسا والقرنبيط) أو عصيدة الأرز أو الحنطة السوداء من أكثر الخيارات أمانًا للبداية. قاعدة مهمة: قدّمي كل طعام جديد بمفرده، وانتظري 3 أيام قبل إدخال طعام جديد آخر. فهذا يساعدكِ على معرفة ما إذا كان طفلكِ يعاني حساسية تجاه ذلك الطعام. لا تتعجلي؛ فالهدف في الأيام الأولى ليس إشباعه، بل تعريفه بالنكهات فحسب.') WHERE id = 'f895f071-f97f-4fb0-9772-e32eeffab324';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ أقرب الآن إلى الجلوس من دون دعم. عندما تُجلسينه على الأرض، قد تلاحظين أنه يحافظ على توازنه بالاستناد إلى يديه على جانبيه. من المهم في هذه المرحلة وضع فرش طري أو وسائد حوله، فقد يسقط إلى الخلف فجأة في لحظة غفلة. لكن لا «تدفنيه» بين الوسائد؛ دعيه يتدرب على حفظ توازنه باستخدام عضلاته. فكلما استخدم عضلات الظهر والبطن أكثر، تمكن من الجلوس منتصبًا بصورة أسرع.') WHERE id = '5a9ac2d0-eaf0-4588-afbc-9d21af03e70a';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الخوف من «الاختناق» عند الانتقال إلى الأطعمة التكميلية هو كابوس كل أم. من المهم أن تعرفي أن «منعكس التهوع» (Gag reflex) لدى الرضع يحدث في جزء أكثر تقدمًا من اللسان؛ لذا فإن تهوّع الطفل لا يعني أنه يختنق، بل إنه يدفع الطعام إلى الخارج فحسب. أما عند الاختناق الحقيقي، فلا يستطيع الطفل إصدار صوت وقد يتغير لون بشرته. وفي حالة التهوع، يسعل الطفل عادةً ويُخرج الطعام. سيساعدكِ فهم هذا المنعكس على الشعور بالهدوء، وسيمنح طفلكِ الثقة لتعلّم تناول الطعام.') WHERE id = '70a66a9a-563a-4960-829c-3c543e77de0b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ الآن ينقل الأشياء بحرية تامة من يد إلى أخرى. وهذا يدل على أن نصفي الدماغ يعملان بتناسق. العبي معه ألعابًا تنمّي هذه المهارة: أعطيه لعبة، وبعد أن يمسكها قدّمي له لعبة ثانية في يده الأخرى. لنرَ، هل سيلقي اللعبة الأولى أم سينقلها إلى يده الأخرى؟ تعزز هذه اللعبة البسيطة مهاراته الحركية الدقيقة وقدرته على حل المشكلات.') WHERE id = 'ae843217-76c1-4871-8e0d-ffc6c753bdec';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'في الشهر 6، تصبح ذاكرة طفلكِ أقوى بكثير. فقد أصبح يتعرّف على الطقوس اليومية؛ فمثلًا، يفهم أنه سيتناول الطعام عندما تضعين له المريلة، وأنه سيستحم عندما يرى المنشفة. يمنحه هذا الثبات شعورًا بالأمان، لذا حاولي الحفاظ على هذه الطقوس. تحدّثي إليه واشرحي له كل خطوة بسؤاله: «ماذا سنفعل الآن؟». صوتكِ وهذا التسلسل يجعلان عالمه أكثر أمانًا ووضوحًا.') WHERE id = '024b161c-2539-4cac-976f-5bf08fd88827';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'إذا لم تظهر الأسنان الأولى بعد، فلا تقلقي؛ فقد يتأخر التسنين لدى بعض الأطفال حتى عمر 1 سنة. لكن اللثة قد تكون متورمة ومؤلمة بالفعل. سيساعد تدليك لثة طفلكِ بقطعة شاش نظيفة ورطبة وباردة على تهدئته كثيرًا. كذلك، حافظي على جفاف المنطقة المحيطة بفمه واستخدمي الكريمات الواقية حتى لا تؤدي كثرة سيلان اللعاب خلال هذه الأشهر إلى تهيّج الجلد.') WHERE id = '5905275f-db82-478c-ba85-c28c03e494ac';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'عند بدء تقديم الأطعمة التكميلية، سيتغير لون براز طفلكِ (محتوى الحفاض) ورائحته وقوامه بشكل ملحوظ. لا تدعي ذلك يخيفكِ! فأمعاؤه تحاول للمرة الأولى هضم مادة غير الحليب. وقد تخرج الخضراوات أحيانًا كما هي دون أن تُهضم، وهذا طبيعي أيضًا. المهم ألا يعاني طفلكِ من ألم حاد في البطن أو الإمساك. وإذا حدث ذلك، فتوقفي عن تقديم الطعام الذي أعطيته له لبضعة أيام واجعلي الحليب خياره الأساسي.') WHERE id = '2175d91f-594f-42b1-b5ca-5375fe51dcff';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'راقبي «المهارات الحركية الدقيقة» لدى طفلكِ: فقد أصبح يحاول الإمساك بالأشياء بأصابعه بدلًا من راحة يده، وإن لم يتقن بعد قبضة «الملقط» تمامًا. قدّمي له ألعابًا آمنة ومختلفة الأشكال ليمسك بها. في هذه المرحلة، يُعد إدراكه للفروق بين خامات المطاط والقماش والخشب مهمًا جدًا لنموه الحسي. تذكّري أنه لا يزال «يستكشف كل شيء بفمه»، لذا احرصي على نظافة ألعابه وتأكدي من خلوها من الأجزاء الصغيرة.') WHERE id = 'ad5ab394-baf9-4d75-b342-9b228c2343bc';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'غدًا سيُكمل طفلكِ نصف عام بالضبط (6 أشهر)! راجعي اليوم للمرة الأخيرة كل ما تحتاجين إليه لبدء الأطعمة التكميلية، مثل جهاز الطهي بالبخار والخلاط أو مجرد مصفاة والأوعية البلاستيكية. لكن الأهم هو الاستعداد النفسي. فقد يبصق طفلكِ الملعقة الأولى، أو يلطخ وجهه، أو يرفض الطعام تمامًا. لا تنزعجي ولا تجبريه. فالهدف في الشهر الأول ليس إشباعه، بل تعريفه إلى النكهات. صبركِ هو أهم مكوّن في هذه التجربة.') WHERE id = '99a11b8e-07bd-49f3-b3dd-d51a0720e2b5';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تهانينا أيتها الأم الرائعة! أتمّ طفلكِ اليوم 6 أشهر! لقد اجتزتِ بنجاح نصف الطريق، أي نصف عامه الأول. وقد أصبح وزن طفلكِ الآن ضعف وزنه عند الولادة تقريبًا، وتكيّف تمامًا مع العالم. احتفلي معه اليوم بأول «مهرجان طعام» رسمي له. هذه المغامرة، التي تبدأ ببضع ملاعق من الطعام المهروس، تمثل مرحلة جديدة في نموه. افتخري بنفسكِ؛ ففي ابتسامته العذبة وهو ينظر إليكِ اليوم، يمكنكِ أن تري ثمرة الليالي التي قضيتِها بلا نوم وجهودكِ التي لا تنتهي!') WHERE id = '6314b77b-4ba8-4969-86b0-43b2ae2976dd';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحبًا بكِ في الشهر 7! لقد بدأت رسميًا مغامرة إدخال الأطعمة التكميلية. إذا لاحظتِ في الأيام الأولى أن طفلكِ يدفع الطعام إلى الخارج بلسانه، فلا تقلقي؛ فهذا رد فعل طبيعي ناتج عن منعكس المص الذي اعتاد عليه منذ أشهر. قدّمي له فقط 1-2 ملعقة صغيرة من الطعام المهروس ولا تجبريه على تناوله. هدفنا في هذه المرحلة ليس إشباع طفلكِ، بل تعريفه إلى نكهات وقوامات مختلفة. ولا يزال حليب الأم أو الحليب الصناعي مصدر طاقته الأساسي.') WHERE id = '359c78b7-5eb4-4ddd-8230-6dac6d1fbced';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'من الطبيعي تمامًا أن يتغير لون براز طفلكِ ورائحته بعد تقديم الخضراوات الأولى. وإذا رأيتِ في الحفاض قطعًا من الطعام المهروس كما هي من دون هضم، فلا تخافي؛ إذ يحاول جهاز طفلكِ الهضمي التكيف مع الأطعمة الجديدة. أهم ما يجب أن تنتبهي إليه هو ظهور احمرار مفاجئ في الجلد، أو طفح جلدي، أو انتفاخ شديد في البطن. إذا لم تظهر هذه العلامات، فكل شيء على ما يرام!') WHERE id = 'e2b1e9c6-06ca-442f-a823-59969208dc77';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'ابدئي بتقديم الماء لطفلكِ منذ اليوم الذي تبدئين فيه بإدخال الأطعمة التكميلية. لا تزال حاجته اليومية إلى الماء قليلة، لكن شرب بضع رشفات بعد الطعام يساعد على تنظيف الفم ويؤسس لعادات صحية مستقبلًا. حاولي تقديم الماء في كوب صغير أو كوب مخصص للشرب (sipper cup)، وليس في زجاجة رضاعة. سيساعد ذلك على نمو عضلات فكه السفلي بطريقة مختلفة.') WHERE id = '0368b56f-7108-4cef-9b22-96d46e080b4f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل تلتزمين بقاعدة الانتظار لمدة 3 أيام؟ قدّمي كل نوع جديد من الخضراوات أو الفواكه على حدة حتى تتمكني من مراقبة استجابة جسم طفلكِ. فعلى سبيل المثال، إذا قدّمتِ له اليوم هريس اليقطين، فلا تضيفي أي طعام جديد آخر خلال اليومين التاليين. سيساعدكِ ذلك على تحديد الطعام "المسبب" فورًا إذا ظهرت أي حساسية. تحلّي بالصبر، فبراعم التذوق لدى طفلكِ تعمل الآن وكأنها مختبر!') WHERE id = '6a73b0da-2d2c-48e8-a871-941a5e9014db';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل يحاول طفلكِ أخذ الملعقة من يدكِ أو وضع يديه في الطعام المهروس أثناء الأكل؟ لا تمنعيه! فالأطفال يتعرفون إلى الطعام ليس بالتذوق فقط، بل باللمس أيضًا. من الطبيعي أن تتسخ المنطقة المحيطة قليلًا؛ فهذا "الاتساخ" مهم لنموه الحسي واكتسابه مهارات تناول الطعام باستقلالية. دعيه يستكشف قوام الطعام، فهذه من أفضل الطرق للوقاية من مشكلة "الانتقائية في الطعام" مستقبلًا.') WHERE id = '81644d16-8ba2-4b27-83e5-5d3f50deae69';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'قد تحدث حالات إمساك خلال فترة إدخال الأطعمة التكميلية، إذ تعتاد أمعاء طفلكِ على معالجة أطعمة غير الحليب. إذا كان طفلكِ يحزق وكان برازه شديد الصلابة، فقد يفيد إضافة قليل من زيت الزيتون إلى طعامه المهروس أو تقديم هريس البرقوق له. ولا تنسي إعطاءه كمية كافية من الماء. إذا استمرت المشكلة طويلًا، فاستشيري طبيب الأطفال بالتأكيد، لكن من المتوقع أن يحتاج طفلكِ إلى مثل هذه التعديلات في الأيام الأولى.') WHERE id = '467b7c20-7f80-4ea7-b9c0-93bd0e277a7e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'بعد عمر ٦ أشهر، تقوى ذاكرة طفلكِ وقدرته على التركيز بشكل ملحوظ. ويبدأ في ربط الأشياء بأسمائها. فعلى سبيل المثال، عندما تقولين: "أين الكرة؟" سيبحث عنها بعينيه. العبي معه ألعاب الأسئلة والأجوبة من هذا النوع. فأنتِ أيضًا "مكتبته الصوتية"؛ وكلما سمع كلمات أكثر، ازدادت حصيلته اللغوية في دماغه بسرعة أكبر. أنصتي إليه كما لو كان شخصًا بالغًا، واستجيبي لكل صوت يصدره بطريقة ذات معنى.') WHERE id = '5b5665e4-15b0-42d4-8279-20912bd71937';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل أصبح طفلكِ يحاول الجلوس من دون دعم بثقة أكبر؟ إن "قضاء الوقت على الأرض" هو أفضل تمرين لتقوية عضلات الوركين والظهر. عندما تضعينه على بطنه، ضعي أمامه لعبة ممتعة على مسافة بعيدة نسبيًا. سيحاول تدوير جذعه، وربما الزحف للوصول إليها. هذه الحركات أساسية لتناسق جسمه. تذكّري أن كل سقوط هو تجربة تعلّم، لكن احرصي فقط على أن تكون البيئة المحيطة آمنة.') WHERE id = '85f7b4d5-b074-40cb-b8e7-126bfcb368b7';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'إذا زاد استيقاظ طفلكِ مجددًا أثناء الليل، فقد يكون ذلك مرتبطًا بالتسنين أو بزيادة نشاطه البدني. فالطفل "يكرّر" حتى أثناء نومه الحركات التي تعلّمها نهارًا، مثل التدحرج أو الزحف. إذا لم يكن يبكي، فلا تتعجّلي حمله؛ دعيه يحاول تهدئة نفسه والعودة إلى النوم. وقد يكفي أن تُشعريه بوجودكِ إلى جانبه، كأن تضعي يدكِ على ظهره.') WHERE id = 'aa9eef25-9e2b-4d46-bc09-aebaa1272eaa';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لقد دخلتما الآن رسميًا الشهر السابع! يُفترض أن يبلغ وزن طفلكِ نحو ضعف وزنه عند الولادة، مع العلم أن هذا مجرد متوسط. إذا لم تظهر أسنانه بعد، فلا تقلقي؛ فما دام نمو عظامه طبيعيًا، فقد تطلّ الأسنان في أي لحظة لتقول "مرحبًا". جرّبي اليوم إضافة كمية صغيرة جدًا، بضع قطرات، من زيت الزيتون البكر عالي الجودة والمعصور على البارد إلى هريس الخضراوات الذي أعددتِه له. سيساعد ذلك على الهضم، كما سيمدّ دماغه بالأحماض الدهنية المفيدة.') WHERE id = 'd3b9ca7e-7233-4280-976e-e11828d20cca';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'إذا أصبح طفلكِ معتادًا على الخضراوات، فيمكننا الانتقال تدريجيًا إلى عالم البروتينات. يُعد لحم العجل قليل الدهن أو الديك الرومي أو الأرنب من أفضل الخيارات عند تقديم اللحوم لأول مرة. اطهي اللحم جيدًا جدًا، واهرسيه حتى يصبح ناعمًا تمامًا، ثم أضيفيه إلى هريس الخضراوات. يُعد اللحم من أهم الأطعمة لتعويض مخزون الحديد لدى طفلكِ، الذي يتناقص بسرعة. في الأيام الأولى، تكفي ملعقة صغيرة واحدة فقط من هريس اللحم.') WHERE id = 'd543dbe5-6df1-4d22-a7ce-cbb22da34fc3';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل أصبح طفلكِ قادرًا على نقل اللعبة من يد إلى أخرى واستخدام كلتا يديه في الوقت نفسه؟ هذه علامة على التطور المتناسق لنصفي الدماغ. العبي معه ألعاب "أمسك واترك". على سبيل المثال، أعطيه لعبة في إحدى يديه، ثم قدّمي له لعبة ثانية إلى اليد نفسها؛ ولنرَ هل سينقل اللعبة الأولى إلى يده الأخرى ليأخذ الجديدة. يساعد هذا التمرين البسيط على صقل مهاراته الحركية الدقيقة وقدرته على حل المشكلات.') WHERE id = 'a8158232-7247-4508-af89-b5e8c2455782';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'حان وقت تقديم صفار البيض! اسلقي البيضة جيدًا، ثم امزجي جزءًا من صفارها بحجم حبة البازلاء فقط مع حليب الأم أو الطعام المهروس وقدّميه لطفلكِ. صفار البيض غني بالكولين والأحماض الدهنية الضرورية لنمو الدماغ. انتبهي: لا يُنصح بتقديم بياض البيض (البروتين) حتى عمر 1 سنة لأنه من مسببات الحساسية القوية. زيدي كمية الصفار قليلًا في كل مرة وراقبي رد فعل طفلكِ.') WHERE id = '348776a6-90b7-44de-bed5-439f8ce3ea57';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل يتخذ رضيعكِ وضعية "الانطلاق" استعدادًا للحبو؟ قد يرتكز على يديه وركبتيه ويتأرجح إلى الأمام والخلف. بهذا "التأرجح" يختبر إحساسه بالتوازن وقوة عضلاته. عندما ترين ذلك، امدحيه وشجعيه. واحرصي على ألا تكون الأرضية زلقة لمساعدته على بدء الحبو (السجاد أو بساط اللعب مثاليان). لن يمر وقت طويل قبل أن يصل إلى كل ركن من أركان المنزل!') WHERE id = '075eebcf-bf5d-40ba-b7ae-a5f38e71818b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مع بدء مرحلة الأغذية التكميلية، لم يعد شرب الماء خيارًا بل ضرورة. تحتاج كليتا رضيعكِ إلى مزيد من الماء أثناء معالجة الأطعمة الجديدة. إذا رفض رضيعكِ الماء، فأثيري اهتمامه باستخدام أكواب الشرب ذات الفوهة أو أكواب صغيرة ملوّنة. قدّمي له الماء بعد الطعام مباشرة وبشكل متكرر خلال اليوم. تذكّري أن العصائر ومشروبات الفاكهة المطهية لا تحل محل الماء؛ فالماء النقي هو الخيار الأكثر صحة.') WHERE id = '5ed536ec-a0b5-4447-9d9a-377e3e5da4a3';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'قد يصبح "قلق الانفصال" (Separation anxiety) أكثر وضوحًا في هذه الفترة. عندما يبدأ رضيعكِ بالصراخ بمجرد مغادرتكِ الغرفة، فهذا لا يعني أنه "سيئ الطباع"، بل إنه يخشى فقدانكِ. عند مغادرة الغرفة، احرصي على مناداته وقولي: "ماما في المطبخ وستعود حالًا". سماع صوتكِ من بعيد يمنحه الشعور بالأمان. العبي معه لعبة "الغميضة" بطرق أكثر تنوعًا؛ فالاختباء ثم الظهور من مكان آخر سيساعده على التغلب على هذا الخوف.') WHERE id = '9d97a34c-0a55-4e17-9a40-0912d5c81137';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'إذا لاحظتِ احمرارًا مفاجئًا على جلد رضيعكِ، خصوصًا حول الفم أو على الجسم، فتذكّري الأطعمة الجديدة التي قدّمتِها له خلال آخر 3 أيام. إذا اشتبهتِ في حدوث أي رد فعل تحسّسي، فأوقفي ذلك الطعام فورًا وجرّبيه مجددًا بعد 1-2 أسبوع بكمية صغيرة. أحيانًا يتفاعل الجسم مع قوام الطعام فحسب، وأحيانًا تكون حساسية فعلية. عند الشك، من الأفضل استشارة طبيب الأطفال.') WHERE id = 'c73b10f1-26e8-49f8-a842-9fc9eb05c61a';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'راجعي مستوى الأمان في المنزل مرة أخرى. أصبح رضيعكِ الآن يمد يده نحو الأشياء ويشدّها ويتذوقها. ركّبي أغطية واقية للمقابس الكهربائية، وغطّي الزوايا الحادة بوسائد حماية. والأهم من ذلك: يجب ألا تتركي أي قطعة صغيرة على الأرض أو السجاد، مثل الأزرار أو الخرز أو البطاريات. حاسة البصر لدى رضيعكِ حادة لدرجة أنه قد يعثر حتى على خيط صغير لم تلحظيه ويضعه في فمه.') WHERE id = 'cb68fae9-cc1f-40fd-8358-d8d8262537c7';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'قد يضطرب نومه ليلًا من جديد. وغالبًا ما يكون السبب هو "التطور الحركي". إذ يرغب رضيعكِ في تكرار الحركات التي تعلّمها نهارًا (مثل الارتكاز على ركبتيه) حتى أثناء نومه. إذا ارتكز على ركبتيه وبدأ يتمايل ليلًا، فلا تحمليه فورًا. أعيديه برفق إلى وضعية الاستلقاء وربّتي على ظهره. امنحيه فرصة ليتعلّم كيف يهدأ من تلقاء نفسه.') WHERE id = 'e9e1b950-57d8-4d65-82e5-7c7681ec6159';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تهانينا! أتمّ طفلكِ 200 يوم! إنه رقم كبير. لم تعودي الآن "أمًا جديدة"، بل أصبحتِ أمًا تتمتع بقدر لا بأس به من الخبرة. عندما ينظر إليكِ طفلكِ ويبتسم، أو يحاول احتضانكِ، تشعرين بقيمة كل الجهد الذي بذلتِه. نظّمي له اليوم "مهرجان نكهات" مميزًا، وحضّري له هريسًا شهيًا من مزيج الخضراوات واللحم الذي يحبه. أنتِ رائعة يا ماما!') WHERE id = '8ef38899-1def-4d57-bd7d-f28245d50ca5';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لقد اجتزنا المحطة الكبيرة المتمثلة في إتمام 200 يوم، وحان الآن وقت تنويع قائمة الطعام قليلًا! إذا كان طفلكِ قد اعتاد على هريس الخضراوات واللحم، فهذا هو الوقت المناسب تمامًا لإدخال الفواكه إلى نظامه الغذائي. ابدئي بالتفاح أو الكمثرى أو الموز. يُسهّل الهضمَ طهوُ الفواكه على البخار ثم هرسها (أو بشرها بمبشرة زجاجية). انتبهي: قد يجد طفلكِ مذاق الفواكه الحلو جذابًا جدًا، لذا يُفضّل عادةً تقديمها في النصف الثاني من اليوم كتحلية، حتى لا يعزف عن الخضراوات.') WHERE id = '52048f39-dc3c-4433-994b-496425ac059d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'من المفترض أن تكون مهارة الجلوس لدى طفلكِ قد تجاوزت وضعية "الحامل الثلاثي" (الاستناد باليدين إلى الأرض)، ليصبح جلوسه أكثر استقامة واستقلالية. وقد أصبح بإمكانه الآن رفع يديه عن الأرض واللعب بلعبة. إذا كان لا يزال يسقط كثيرًا على أحد جانبيه، فلا تقلقي؛ أتيحي له قضاء وقت أطول على الأرض لتقوية عضلات ظهره. ضعي خلفه وسائد ناعمة، لكن امنحيه فرصة ليجد توازنه بنفسه. فالجلوس باستقلالية يعني له رؤية العالم من زاوية مختلفة تمامًا.') WHERE id = '9d5fc99c-ca1a-4324-a7ea-7d36c4768a6e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'حان وقت التعرّف إلى منتجات الألبان! إذا لم يرَ طبيبكِ مانعًا، فيمكنكِ تقديم الزبادي الطبيعي المحضّر منزليًا أو الجبن القريش. فالزبادي غني بالكالسيوم، كما يحتوي على البروبيوتيك المفيد للنبيت المعوي. عند تقديمه للمرة الأولى، ابدئي بملعقة صغيرة واحدة فقط وراقبي أي تفاعل جلدي. تذكّري: ابتعدي عن "زبادي الأطفال" المحلّى أو المنكّه بالفواكه والمتوافر في المتاجر؛ فالخيار الصحي الأفضل هو الزبادي الطبيعي الذي تحضّرينه في المنزل.') WHERE id = '8027ff1e-e9f7-4f2e-9aa6-3293659f2fb7';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل أصبح طفلكِ يستمتع بضرب الأشياء بعضها ببعض لإصدار الأصوات؟ إنه بذلك يتعمّق في فهم علاقة "السبب والنتيجة": "إذا ضربتُ هاتين اللعبتين معًا (السبب)، فسيصدر صوت (النتيجة)". أعطيه ألعابًا مصنوعة من مواد مختلفة (الخشب والبلاستيك والقماش) ليدرك الاختلاف بين الأصوات والملامس. تُنمّي هذه اللعبة البسيطة حاسة السمع والمهارات الحركية لديه. وقد تكون الأوعية البلاستيكية والملاعق الخشبية في المطبخ أحيانًا أكثر إثارة للاهتمام من أغلى الألعاب!') WHERE id = '580f2e78-b4ac-4e71-a08f-98de51b2b255';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح جمع المقاطع مثل "ما-ما" و"با-با" و"دا-دا" أكثر إيقاعًا واستمرارية (المناغاة التكرارية). كما بدأ طفلكِ يحاول تقليد نبرة صوتكِ. عندما تتحدثين إليه، فإنه "يجيبكِ" بدوره. أطيلي هذه الحوارات! عندما يصدر صوتًا، أنصتي إليه باهتمام، ثم أجيبي: "حقًا؟ وماذا حدث بعد ذلك؟" فهذا يزيد حماسه للتواصل وينشّط مركز النطق لديه. أنتِ أفضل شريكة تواصل له.') WHERE id = 'cfd5a392-f80a-4d2d-a1a6-3083e4ec4e6d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أدخلي الحبوب (العصائد) بصورة أكبر ضمن نظام طفلكِ الغذائي التكميلي. إذا لم تكوني قد بدأتِ بعد، فعصيدة الأرز والحنطة السوداء ودقيق الذرة هي أفضل الخيارات للبدء، لأنها خالية من الغلوتين. لا تجعلي العصيدة كثيفة جدًا؛ قدّميها في البداية بعد تخفيفها بحليب الأم أو الحليب الصناعي. تمنح الحبوب رضيعكِ طاقة تدوم طويلًا، وقد تساعده على النوم ليلًا دون انقطاع لفترة أطول (بالطبع، إذا كان الجوع هو سبب استيقاظه).') WHERE id = 'a9b193a4-5558-4e20-a84e-1718f45d9ce1';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل بدأ رضيعكِ يمسك الأشياء بأصابعه بدلًا من راحة يده (استعدادًا لتطوير "قبضة الكماشة")؟ إنها قفزة كبيرة في مهاراته الحركية الدقيقة. أعطيه ألعابًا آمنة ليست صغيرة، لكن يمكنه الإمساك بها بأصابعه. انتبهي: تعني هذه المهارة أيضًا أنه يستطيع التقاط أصغر خيط أو ذرة غبار يراها على الأرض ووضعها في فمه. لذا أصبح الحفاظ على نظافة المنزل والتأكد من خلو الأرض من القطع الصغيرة أكثر أهمية من أي وقت مضى.') WHERE id = 'f62f3f3e-4b0d-4001-8523-9219c3da8c5d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'بدأت مرحلة "الاستقلالية"! اسمحي له بإمساك ملعقته بنفسه وقت الطعام. نعم، ستتسخ الأشياء من حولكما، وقد يصل الطعام المهروس إلى شعر رضيعكِ ووجهكِ، لكن هذه التجربة لا تُقدّر بثمن لتنمية مهارات الاعتماد على النفس. دعيه يمسك ملعقة، وأطعميه أنتِ بملعقة أخرى. وهكذا سيشعر بأنه مشارك فعّال في تناول الطعام. إنها من أفضل الطرق للوقاية من نوبات "لا أريد أن آكل" مستقبلًا.') WHERE id = '60871d42-5c1c-446f-a627-a65d4f2f7fcb';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'إذا كانت مرحلة التسنين لا تزال مستمرة، فقد تقل شهية رضيعكِ. وقد لا يكون تناول الطعام الصلب أو الساخن مريحًا له بسبب ألم اللثة. في مثل هذه الأيام، لا تجبريه على الأكل، وأكثري من إرضاعه طبيعيًا، أو قدّمي له الطعام أبرد قليلًا من درجة حرارة الغرفة. قد تساعد مهروسات الفاكهة الباردة على تهدئة لثته. تحلّي بالصبر، فهذا الانزعاج مؤقت، والأهم ألا تتكوّن لديه مشاعر سلبية تجاه الطعام.') WHERE id = 'd3067cbe-ce54-41b6-9dd3-9072dfcf2c69';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تهانينا، لقد وصلتما إلى نهاية الشهر السابع! أصبح طفلكِ يعرف اسمه تمامًا ويلتفت نحوكِ عندما تنادينه. كما بات يعبّر عن مشاعره بوضوح أكبر: يصرخ فرحًا، ويُظهر انزعاجه عندما تؤخذ لعبته منه. هذه هي بداية تشكّل شخصيته. استلقي اليوم معه على الأرض والعبا معًا فحسب، فهو يقدّر اهتمامكِ أكثر من أي شيء آخر. لقد قطعتِ شوطًا رائعًا يا ماما!') WHERE id = 'bd6cd20e-2a94-483e-b4a1-ed0a0a344bf5';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل لاحظتِ أن طفلكِ صار ينظر إلى المكان الذي تسقط فيه اللعبة عندما يرميها؟ يشير ذلك إلى اكتمال تطور مفهوم «دوام الشيء» (object permanence) لديه. فهو يعرف أن اللعبة لم تختفِ عندما خرجت من مجال رؤيته، بل سقطت على الأرض فحسب. لذلك قد تكون ردة فعله أقوى عندما تغادرين الغرفة. ابتكري طقوس «وداع» قصيرة تجعله يشعر بأنكِ تغادرين وأنكِ ستعودين حتمًا.') WHERE id = '2f260480-889e-4da7-8269-7ccb344f483a';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'قد يطرأ تغيير على نمط نوم طفلكِ. في الشهر الثامن، يبدأ بعض الأطفال في الاستغناء عن القيلولة النهارية الثالثة (قيلولة آخر النهار). وهذا طبيعي تمامًا. إذا كان ينام قيلولتين أطول خلال النهار ويخلد إلى النوم في موعده مساءً، فهذا يعني أنكما تنتقلان إلى نمط جديد. وقد تمتد فترة بقائه مستيقظًا الآن إلى 2.5 - 3 ساعات. واصلي مراقبة علامات التعب لديه (مثل حكّ أذنه وفرك عينيه).') WHERE id = '0800d9fe-eb08-4a4c-84c3-d676b21556f0';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحلة جديدة في تطور اللغة: هل لاحظتِ أن طفلكِ صار يؤلف جملًا طويلة «بلغته الخاصة»؟ هذه هي مرحلة «الرطانة». فهو يقلّد نبرة حديث البالغين، ويرفع صوته كما لو كان يطرح سؤالًا، أو يحرّك يديه وذراعيه كما لو كان يشرح شيئًا. أنصتي إليه باهتمام وأجيبيه بعبارات مثل: «حقًا؟ هذا ممتع جدًا!». سيزيد ذلك رغبته في التواصل بدرجة مذهلة.') WHERE id = '71cabae0-25d9-4b76-b251-aaf1f4412278';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تهانينا، اكتملت الأيام العشرة الأولى من الشهر الثامن! أصبح طفلكِ يعبّر عن مشاعره بطرق أكثر تعقيدًا: فقد يتدلل أو يعترض أو يصفق بيديه فرحًا عند رؤيتكِ. العبي معه اليوم على الأرض بالكرة؛ دحرجيها نحوه ودعيه يحاول الإمساك بها أو دفعها إليكِ مجددًا. ستعزز هذه اللعبة البسيطة رابطتكما الجسدية والاجتماعية. أنتِ مرشدة رائعة يا أمي!') WHERE id = '9fdaa957-189e-4f2e-b893-b9625e6dd277';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'نواصل مغامرتنا مع منتجات الألبان! إذا لم تكوني قد بدأتِ بعد، فقد حان الوقت تمامًا لإضافة الجبن القريش المحضّر منزليًا إلى النظام الغذائي. فالجبن القريش غني بالكالسيوم والبروتين، ولا غنى عنه لنمو عظام طفلكِ وأسنانه. يمكنكِ مزجه مع هريس الفواكه ليصبح ألذ. تذكّري: إذا كنتِ تشترينه من المتجر، فاختاري بالتأكيد نوعًا مخصصًا للأطفال وخاليًا من السكر والمواد المضافة.') WHERE id = 'ae94f7bd-20c4-400d-a0b5-4fc94f6e2927';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'بدأ طفلكِ الآن في التعرّف إلى أجزاء جسمه. اطرحي عليه أسئلة مثل: «أين أنفك؟» و«أين عيناك؟»، وأشيري إلى هذه الأجزاء في وجهكِ. تساعد هذه اللعبة البسيطة على توسيع حصيلته اللغوية وإدراك ذاته بوصفه فردًا مستقلًا. وسيجعل الوقوف أمام المرآة والإشارة إلى يديه وقدميه هذه العملية أكثر متعة. لقد اقترب من فهم أن للصورة المنعكسة في المرآة معنى.') WHERE id = 'c515c840-71f3-41f7-b139-398b94946105';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'المحاولات الأولى للمشي مستندًا إلى الأثاث! قد يبدأ طفلكِ بأخذ خطوات جانبية ممسكًا بالأريكة أو الكرسي. يُسمّى ذلك "المشي الجانبي مع الاستناد". في هذه المرحلة، لا تتعجلي في إلباسه الحذاء؛ فالحركة حافي القدمين في المنزل (أو بجوارب مانعة للانزلاق) هي الأفضل لنمو عضلات القدم نموًا سليمًا ولتنمية إحساسه بالتوازن. فملامسة الأرض بأصابع قدميه تنقل مزيدًا من المعلومات إلى دماغه.') WHERE id = '0028192c-1744-4eba-bb7a-f5c3b5d11c54';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'اختبري "المهارات الحركية الدقيقة" لدى طفلكِ: أصبح الآن قادرًا على نقل اللعبة من يد إلى أخرى بسهولة تامة، وتقريب إبهامه من بقية أصابعه. في هذه المرحلة، قدّمي له ألعاب "الهرم" بأشكال وألوان مختلفة، أو أوعية متداخلة. ورغم أنه قد لا يتمكن بعد من ترتيب الحلقات بالتسلسل الصحيح، فإن تفكيكها وتركيبها ينمّيان إدراكه المكاني وتناسق حركاته بدرجة مذهلة.') WHERE id = 'b139a999-0910-43e1-b5bf-dc2f0d783db4';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تنويع ألوان قائمة الطعام: إذا لم تكوني قد جرّبتِ البقوليات بعد، فيمكنكِ البدء بها (مثل العدس الأحمر). فالعدس مصدر للبروتين النباتي والحديد. لكن انتبهي، إذ قد تسبب البقوليات الغازات. لذلك، انقعي العدس مسبقًا وأضيفي كمية صغيرة جدًا منه إلى حساء الخضراوات. راقبي استجابة جهاز طفلكِ الهضمي؛ وإذا كان كل شيء على ما يرام، فستكون هذه وجبة غداء مشبعة جدًا له.') WHERE id = '071fb8f4-fce6-4526-aae9-c60d8797b1ea';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'المهارات الاجتماعية: قد أصبح طفلكِ قادرًا على تقليد حركات مثل التلويح باليد للتوديع أو التصفيق تعبيرًا عن الاستحسان. فإذا كرّر التصفيق عندما تصفقين، فهذا يدل على تمتعه بقدرة عالية على التقليد. حوّلي هذه الحركات إلى لعبة. فالتقليد من أسرع طرق التعلّم. امدحيه بحماس بعد كل حركة ناجحة، فهذا سيعزز ثقته بنفسه.') WHERE id = '5cd6ae76-cf22-4b82-a5b7-ee78e7b002f5';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تنبيه للسلامة: أصبح طفلكِ يميل إلى التسلق إلى الأماكن المرتفعة. وقد يستخدم أدراج الخزائن كدرجات سلّم. لقد حان الوقت تمامًا لتركيب أقفال خاصة للأدراج. وتأكدي أيضًا من تثبيت قطع الأثاث الثقيلة (مثل خزانة الكتب وخزانة الأدراج) بالحائط. فقد يسحبها طفلكِ فتسقط فوقه. المنزل الآمن يعني استكشافًا حرًا.') WHERE id = 'a8f4ab5e-3832-4512-afc4-44fcec1c8a18';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تعويد الطفل على شرب الماء: مع معالجة كليتي طفلكِ للأطعمة التكميلية، تزداد حاجته إلى الماء. إذا كان طفلكِ يرفض الماء، فقدّميه له بطرق متنوعة وممتعة. على سبيل المثال، قدّمي له الماء عندما تشربين، لأنه يتعلم من خلال مراقبتكِ. وأبقي الماء دائمًا في متناول يده. فالماء النظيف ينظّم عملية الهضم ويقلل خطر الإصابة بالإمساك.') WHERE id = '73e0efe7-8cf6-4415-b315-772133307918';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحبًا بكِ في الشهر الثامن! في هذا الشهر يكتسب طفلكِ صفة "المستكشف المستقل". فقد أصبح قادرًا على الزحف (الحبو) بسرعة من أحد أركان الغرفة إلى الآخر. إذا لم يبدأ طفلكِ بالزحف بعد، فلا تقلقي؛ فبعض الأطفال ينتقلون مباشرةً إلى الوقوف والمشي من دون المرور بمرحلة الزحف. ولتشجيعه، ضعي لعبته المفضلة على مسافة أبعد قليلًا واتركي له المجال ليحاول الوصول إليها. كل تقدم صغير يحرزه هو انتصار كبير!') WHERE id = 'ecb494cd-7c29-44d1-ad94-78d5bacf0eb8';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'حان الوقت الآن لتغيير قوام الأطعمة المهروسة تدريجيًا. بدلًا من خلط الطعام في الخلاط، ابدئي بهرسه بالشوكة. حتى إن لم تظهر أسنان طفلكِ بعد، فعليه أن يتعلم هرس القطع اللينة بلثتيه. يساعد ذلك على تطوير عضلات المضغ، وينعكس إيجابيًا على قدرته على الكلام مستقبلًا. قد يظهر في البداية منعكس التهوع (gag reflex)، وهذا طبيعي؛ ابقي فقط بجانبه وشجعيه.') WHERE id = '2727a145-103d-40b1-93bd-853efdc6e639';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل يحاول طفلكِ الوقوف مستندًا إلى الأشياء؟ حواف الأريكة والكراسي وحتى ساقاكِ تشكل له نقاط ارتكاز. انتبهي خلال هذه المرحلة إلى ثبات أثاث المنزل، فقد تنقلب الكراسي الخفيفة أو قطع الأثاث غير الثابتة. لقد حان الوقت فعلًا لتركيب واقيات لينة خاصة على زوايا الأثاث الحادة، لأن محاولات الوقوف كثيرًا ما تنتهي بسقطات بسيطة.') WHERE id = '2b052f0a-26d0-4470-a503-c5a76302b58f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل تفكرين في إضافة السمك إلى قائمة طعام طفلكِ؟ إذا لم تكن هناك حساسية شديدة تجاه السمك في العائلة، فإن الأسماك ذات اللحم الأبيض (مثل القاروص أو الأسماك البيضاء منزوعة العظام) تعد مصدرًا ممتازًا لأوميغا-3. اطهي السمك على البخار وتفحصيه جيدًا بيدكِ للتأكد من عدم بقاء أي عظمة فيه، مهما كانت صغيرة. فالسمك مفيد جدًا لنمو الدماغ والقدرة على الإبصار. يمكنكِ البدء بحصة صغيرة مرة واحدة أسبوعيًا.') WHERE id = '1d9818aa-0e5b-4ba9-aefe-a8e9678137db';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'حان وقت التعرف إلى كلمة "لا"! أصبح طفلكِ الآن يفهم التغير في نبرة صوتكِ. فعندما يمد يده نحو شيء خطر وتقولين له بنبرة حازمة "لا" أو "ممنوع"، قد يتوقف وينظر إليكِ. لكن لا تستخدمي هذه الكلمة كثيرًا كي لا تفقد تأثيرها. استخدميها فقط عند وجود خطر حقيقي (مثل محاولته لمس مقبس الكهرباء). أما في الحالات الأخرى، فمن الأكثر فاعلية تحويل انتباهه إلى لعبة أخرى مثيرة للاهتمام.') WHERE id = 'f3741479-5e2c-4a17-a78f-8627ec0b11aa';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تزداد مهارة طفلكِ في استخدام "قبضة الكماشة" (pincer grasp). فقد أصبح قادرًا على التقاط الفتات الصغير بإبهامه وسبابته. قدّمي له "أطعمة تؤكل بالأصابع" (finger foods) تساعد على تطوير هذه المهارة، مثل شرائح الجزر اللينة والمطهوة جيدًا، أو قطع الموز، أو اليقطين المطهو. فهذا يطور مهاراته الحركية ويمهد لاكتسابه القدرة على إطعام نفسه. راقبيه دائمًا أثناء الأكل!') WHERE id = '832beb7b-28cb-4a32-9588-55e7154e59b5';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'إذا استمر الاستيقاظ ليلًا، فقد يكون سببه التسنين إلى جانب «قلق الانفصال». ففي عمر ٨-٩ أشهر، تبدأ القواطع العلوية عادةً بالظهور. وقد تكون اللثة متورمة وحساسة. دلّكي لثته برفق بإصبعكِ النظيف قبل النوم لمساعدته على الشعور بالراحة. تحلّي بالصبر، فهذا الانزعاج مؤقت، أما دعمكِ له فدائم.') WHERE id = 'a7e2adf7-fa7d-49f9-b9df-6cb36632b7da';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تهانينا، لقد أتممنا 230 يومًا! أصبح طفلكِ الآن بارعًا جدًا في فهم مشاعركِ. فعندما تبتسمين يفرح هو أيضًا، وعندما تتحدثين بنبرة جادة يتوقف وينظر إليكِ. استلقي معه اليوم على الأرض والعبا معًا لعبة الدغدغة فحسب. ستبدّد ضحكاته كل تعبكِ. لقد بنيتِ رابطًا رائعًا بينكما يا أمي!') WHERE id = 'd3c12132-2a39-444c-81a2-79aa27f8b6cc';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'يمكنكِ الآن إدخال حبوب متنوعة، مثل الشوفان والشعير، إلى نظامه الغذائي. إذا لم تكن هناك حساسية من الغلوتين في العائلة، فعصيدة الشوفان (oat) وجبة فطور مشبعة وغنية بالألياف لطفلكِ. تساعد الأطعمة الغنية بالألياف على تنظيم حركة أمعاء طفلكِ والتخفيف من مشكلة الإمساك. ويمكنكِ جعل مذاق العصيدة ألذ بإضافة القليل من الموز المهروس أو هريس التفاح إليها.') WHERE id = 'f8aaab74-ed0b-4ea9-b26f-011f00ca98cb';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل بدأ طفلكِ يحاول وضع الأشياء بعضها داخل بعض أو تكديسها فوق بعضها؟ هذا دليل على تطور «الإدراك المكاني» لديه. أعطيه أكوابًا بلاستيكية بأحجام مختلفة أو أوعية يمكن إدخال بعضها في بعض. عندما يكتشف أن الوعاء الصغير يتسع داخل الوعاء الكبير، تتكون روابط عصبية جديدة في دماغه. قد يكون بناء برج صعبًا عليه في الوقت الحالي، لكن هدم البرج الذي تبنينه سيصبح نشاطه المفضل!') WHERE id = '51ca7794-c77c-4014-b77a-c79e37d35c43';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التعرّف إلى جسمه: قد يتمكن طفلكِ الآن من الإشارة إلى «أنفه» أو «عينه» أو «فمه» عندما تذكرينها، أو قد يستجيب بابتسامة عندما تشيرين إليها. وهذا جزء مهم من تطور وعيه بذاته. أثناء تحميمه أو إلباسه، سمّي أعضاء جسمه بقولكِ: «الآن نُلبس يدك اليمنى» أو «الآن نغسل قدمك اليسرى». فهذا يساعد على تطور لغته وتكوين تصوره عن جسمه.') WHERE id = '7184c458-15f9-4675-8f4b-a012153962e8';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'إتقان تناول «الأطعمة بالأصابع» (finger foods): أصبح طفلكِ الآن أكثر مهارة في التقاط قطع الطعام الصغيرة بأصابعه، مثل شريحة جزر مطهوة أو حبة بازلاء، ووضعها مباشرةً في فمه. تساعد هذه المهارة على تنمية قدرته على الأكل باستقلالية وإدراك شعوره بالشبع. ضعي أمامه أطعمة آمنة وطرية، وأتيحي له فرصة تناول الطعام بنفسه. من الطبيعي أن تتسخ المنطقة المحيطة به؛ فالأهم أن يكتسب هذه المهارة. ابقي دائمًا إلى جانبه وراقبيه.') WHERE id = 'b13c96d3-3ebb-4786-a1ba-dda465e426a2';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل بدأ طفلكِ يقلّدكِ، فيتظاهر بالتحدث عبر الهاتف أو يحاول تمشيط شعره؟ هذه هي مرحلة "اللعب الوظيفي"، إذ يبدأ بفهم الغرض من استخدام الأشياء. ادعمي مهارة التقليد لديه بإعطائه أدوات منزلية آمنة، مثل مشط بلاستيكي أو هاتف لعبة أو ملعقة خشبية. فالتقليد من أقوى الوسائل التي تدعم نمو طفلكِ الاجتماعي والفكري.') WHERE id = '186aab21-e01b-4cb3-9b1b-f1b7cf5f3b0c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الانتقال إلى قوام جديد في التغذية: إذا كنتِ لا تزالين تقدمين الطعام مهروسًا تمامًا، فابدئي من اليوم بزيادة القطع الصغيرة فيه. لا تهرسي الطعام كليًا، بل اتركي فيه قطعًا صغيرة وطرية. يساعد ذلك طفلكِ على تطوير مهارة المضغ وتقوية لثته. إذا كان طفلكِ يلفظ القطع، فلا تجبريه، لكن واصلي المحاولة بتقديم بضع قطع في كل وجبة. تحلّي بالصبر، وسرعان ما سيتمكن من تناول طعام مائدة الأسرة.') WHERE id = '0b1ada17-b48a-4258-81e3-556f2db2a842';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التفاعل الاجتماعي: هل تعلّم طفلكِ التلويح بيده مودّعًا أو التصفيق عندما تقولين له "أحسنت"؟ هذه الإيماءات هي من أشكال التواصل التي تسبق الكلام. إذا كان يقلّدكِ عندما تلوّحين بيدكِ، فهذا يدل على تعلقه بكِ وانتباهه إليكِ. اجعلي هذه الحركات أكثر متعة من خلال دمجها مع الأغاني. واستجيبي لكل إيماءة منه بفرح، ليزداد حماسه للتواصل.') WHERE id = '88a30222-647e-4598-aa2c-f27d2f68a4e6';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحلة جديدة من السلامة: أصبح طفلكِ الآن يرغب في تسلّق كل شيء. فالطاولات المنخفضة وحواف الأرائك تمثّل له "قممًا" يسعى إلى بلوغها. تحققي من ثبات جميع الأغراض الثقيلة وقطع الأثاث في المنزل. وأخفي الأسلاك الكهربائية خصوصًا، لأن شدّها قد يكون من أكثر الأمور إثارة لفضوله. ستمنحكِ سلامة المنزل راحة البال، وتوفر له مساحة واسعة للاستكشاف.') WHERE id = '42e1e998-0acc-4253-963b-1927f727ffd8';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'النوم ليلًا و"قلق الانفصال": قد يبكي طفلكِ بصوت عالٍ إذا استيقظ ليلًا ولم يجدكِ أمامه. ومن المهم في هذه المرحلة أن تمنحيه الشعور بالأمان. عندما تذهبين إليه، ربّتي عليه برفق من دون تشغيل الضوء، وقولي له بصوت هادئ: "ماما هنا، نم". لا تتعجلي في حمله ومغادرة الغرفة به فورًا. فمجرد وجودكِ إلى جانبه وسماع صوتكِ قد يمنحانه ما يكفي من الأمان ليعود إلى النوم.') WHERE id = 'cab92102-e3a5-49d4-bbd8-bdc2525ea7fb';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تهانينا، لقد أتممنا 8 أشهر كاملة! أصبح وزن طفلكِ الآن نحو ثلاثة أضعاف وزنه عند الولادة (وهذا رقم تقريبي). وهو نشيط جدًا، ويميز الأصوات، ويتعرف إلى أفراد الأسرة. العبي معه اليوم على الأرض بالكرة؛ دحرجيها نحوه ودعيه يحاول الإمساك بها. تساعد هذه اللعبة على تطوير التناسق البصري لديه، وكذلك مهارة تبادل الأدوار، وهي إحدى القواعد الاجتماعية. لقد قطعتِ شوطًا رائعًا يا ماما!') WHERE id = 'eeeb250d-7860-4dbd-adfd-8f04383dcc0f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحبًا بكِ في الشهر التاسع! هذا الشهر هو مرحلة «التواصل الواعي» لدى طفلكِ. فعندما يقول الآن «ما-ما» أو «با-با»، لا يكون مجرد تدرّب على إصدار الأصوات، بل يناديكِ أنتِ أو والده مباشرةً. عندما ينظر إليكِ وينطق بهذه الكلمات، أظهري فرحتكِ واحتضنيه. إن رد فعلكِ الإيجابي يعلّمه قوة الكلمات ومعناها. وهو يدرك الآن أنه يستطيع التعبير عن رغباته وحبه من خلال اللغة.') WHERE id = 'c35ed773-5541-46b9-a100-13e031ebc738';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الانتقال الكامل من الزحف على البطن إلى الحبو على اليدين والركبتين! أصبح طفلكِ الآن يرفع بطنه عن الأرض ويتحرك بسرعة على أطرافه الأربعة. تساعد هذه الحركة على تحسين التناسق المتقاطع بين نصفي دماغه. كما يشكّل الحبو أساسًا للتناسق البصري اللازم لمهارات القراءة والكتابة مستقبلًا. دعيه يستكشف جميع أرجاء المنزل، وتأكدي فقط من أن مساراته آمنة.') WHERE id = 'eef05a4c-d9ba-43c9-8340-a35c1089e87f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'زيادة تنوع الغذاء: يمكنكِ الآن إضافة البقوليات، مثل العدس الأخضر وهريس الفاصولياء، ومختلف الفواكه الموسمية الممزوجة بالجبن القريش إلى نظام طفلكِ الغذائي بثقة أكبر. وللحفاظ على مخزون الحديد لديه خلال هذه المرحلة، حاولي تقديم اللحوم الحمراء أو صفار البيض مع الخضراوات الخضراء. يساعد فيتامين C، مثل بضع قطرات من الليمون المعصور فوق الخضراوات، على تحسين امتصاص الحديد.') WHERE id = 'c2e87fad-ec56-47c4-9f57-fc56aefe9e8a';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبحت «قبضة الكماشة» (pincer grasp) لديه أشبه بمهارة فنية. يستطيع طفلكِ التقاط حتى أصغر فتات يراه على الأرض بإصبعين. ولتنمية هذه المهارة، قدّمي له حبات البازلاء المطهوة حتى تصبح طرية أو قطعًا صغيرة من الجبن القريش. يمنحه تناول الطعام بنفسه ثقة كبيرة بالنفس. لكن كوني حذرة: فهذه المهارة تعني أيضًا أنه يستطيع بسهولة وضع أشياء صغيرة وخطيرة في فمه، مثل الأزرار والخرز.') WHERE id = 'afe941be-e174-4b07-9f32-16d62d4cfe8e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ يفهم تمامًا معنى كلمة «لا». عندما يفعل شيئًا خطيرًا وتقولين له «لا»، قد يتوقف وينظر إليكِ، بل وقد يبكي اعتراضًا. هذه بداية تعلّمه للحدود. لكن حاولي ألا يمتلئ المنزل بكلمة «لا». أبعدي الأشياء الخطرة كي يتمكن من ممارسة ألعاب يمكنكِ أن تقولي لها «نعم» بحرية. ضعي الحدود فقط في المواقف المهمة حقًا.') WHERE id = 'a85e4f35-e664-455a-b825-3e51d17e5f0d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لعبة «بقاء الأشياء»: يعرف طفلكِ الآن أن اللعبة لا تختفي حتى لو أخفيتِها تحت البطانية. أخفي جزءًا من اللعبة ودعيه يعثر عليها. تعزز هذه اللعبة ذاكرته وتفكيره المنطقي. كما تساعد لعبة «الغميضة» على تخفيف خوفه من الانفصال؛ إذ يدرك أنكِ حتى لو غبتِ عن نظره، فستعودين إليه حتمًا.') WHERE id = '0a1f58ae-f05c-4b6b-aa75-6ff0b27beddc';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'إتقان الوقوف بالاستناد: أصبح طفلكِ الآن يقف مستندًا إلى كل ما حوله، كحافة الأريكة أو ساق الكرسي، بل وحتى ممسكًا بركبتيكِ. لكنه قد لا يعرف بعد كيف ينزل، فيظل واقفًا ويبكي طالبًا المساعدة. أريه كيف يجلس؛ اثني ركبتيه وضعيه على الأرض ببطء. سيساعده ذلك على تطوير التحكم في جسمه والشعور بالتوازن.') WHERE id = 'd5785d23-fd09-4663-8877-2740ab81ecbc';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '«الاستيقاظ الحركي» أثناء النوم ليلًا: قد يبدأ طفلكِ فجأة بالحبو أثناء نومه ليلًا، أو قد يحاول الوقوف وهو نصف نائم. فدماغه يكرر ليلًا الحركات التي تعلمها نهارًا. إذا لم يكن يبكي، فلا تلمسيه ودعيه يجد وضعيته بنفسه ويعود إلى النوم. وإذا بكى، فاقتربي منه بهدوء، وأعيديه إلى وضعية الاستلقاء من دون تشغيل الضوء، وقولي له كلمات مطمئنة. هذه المرحلة مؤقتة.') WHERE id = '3ee50fc0-987b-4449-9a9a-aeac43eacebb';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التسنين والتغذية: في الشهر 9 غالبًا ما تبدأ القواطع الجانبية العلوية أو السفلية بالظهور. وخلال هذه الفترة، قد يرفض طفلكِ الأطعمة الصلبة بسبب ألم لثته. لا تجبريه، وقدّمي له لبضعة أيام أطعمة أكثر ليونة وبرودة، مثل هريس الفاكهة البارد أو الزبادي. ستعود شهيته بمجرد انتهاء مرحلة التسنين. صبركِ وحنانكِ هما أفضل دواء له.') WHERE id = '5c734779-7b9a-4eb8-a3df-dadd22df3bb2';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تهانينا، لقد قطعنا معًا رحلة طويلة امتدت 250 يومًا! أصبح طفلكِ الآن قادرًا على قراءة تعابير وجهكِ بدقة كبيرة. فعندما تفرحين يضحك هو أيضًا، وعندما تتحدثين بنبرة جادة يتوقف ويراقب. خصصي اليوم وقتًا للجلوس معه على الأرض وتصفح الكتب. أشيري إلى الحيوانات في كتاب ذي صور كبيرة وقلّدي أصواتها. سيحاول تقليدكِ. أنتِ دليله الأكثر أمانًا في رحلة اكتشاف العالم، يا أمي!') WHERE id = '4168c3b6-34fd-49a6-b076-88e5415caa27';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لقد وصلتما الآن إلى منتصف الشهر 9 تمامًا! أصبح طفلكِ ماهرًا في الوقوف مستندًا إلى الأشياء. لكن المهارة الأهم لا تزال أمامه: الجلوس على الأرض بأمان من وضعية الوقوف. أريه كيف يثني ركبتيه ويجلس ببطء. وإذا سقط على ظهره، فلا تصرخي فتخيفيه؛ بل اقتربي منه وأعيدي توضيح الطريقة الصحيحة للحركة. فهذا يقوّي التناسق الحركي لجسمه.') WHERE id = '8802254f-c7f7-4ff6-9b20-d9c01f14b494';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبحت إيماءات طفلكِ وسيلة تواصل ذات معنى. فقد يشير بإصبعه إلى اللعبة التي يريدها (الإشارة بالإصبع). وهذه قفزة كبيرة في تطوره المعرفي! إنه يريد مشاركة اهتمامه معكِ. عندما يشير إلى شيء، اذكري اسمه فورًا: "نعم، هذه كرة! هل تريد الكرة؟". سيساعده ذلك على ترسيخ الصلة بين الكلمات والأشياء في دماغه.') WHERE id = '425f3229-dceb-43c5-a7c7-021a098be008';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التنوع في التغذية والقوام الجديد: يمكنكِ الآن الاستغناء تمامًا عن الطعام المهروس. قدّمي الطعام لطفلكِ بعد هرسه بالشوكة فحسب. فلثته قوية بما يكفي لسحق قطع اللحم الطرية المطهية جيدًا أو الخضراوات. وحركة المضغ ضرورية ليس للهضم فقط، بل أيضًا لنمو العضلات المسؤولة عن النطق. إذا بصق بعض القطع، فلا تقلقي؛ فهو يعتاد الأحاسيس الجديدة.') WHERE id = '04975f3b-94a9-41da-8a0a-2994a09d6287';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'عزّزي عادة شرب الماء من الكوب. قد يحاول طفلكِ الآن إمساك الكوب بكلتا يديه. قدّمي له الماء في كوب صغير من البلاستيك أو السيليكون. في البداية، سيسكب نصف الماء على نفسه، وهذا طبيعي جدًا. الشرب من كوب مفتوح أنفع لنمو اللسان والفك نموًا سليمًا من الشرب بالزجاجة ذات الحلمة. وهذه خطوة أخرى نحو استقلاليته.') WHERE id = '2fd76c93-94cc-41aa-af0c-928b17fbd06d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الألعاب الاجتماعية: أصبحت لعبة "أعطني وخذ" من أنشطته المفضلة. عندما تطلبين منه اللعبة، قد يمدّها إليكِ (حتى لو سحبها أحيانًا!). تشكّل هذه اللعبة أساس فهمه لتبادل الأدوار والمشاركة. لا تنسي أن تقولي له "شكرًا جزيلًا". فعندما يرى رد فعلكِ الإيجابي، سيتشجع على تكرار مثل هذه السلوكيات الاجتماعية بوتيرة أكبر.') WHERE id = '7c3fd582-3962-47a8-9de8-b81ab68183e7';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبحت "قبضة الملقط" (pincer grasp) لديه أكثر إتقانًا الآن. يستطيع طفلكِ التقاط حتى أصغر ذرة غبار من الأرض. ولتنمية هذه المهارة، يمكنكِ أن تقدّمي له بقوليات مطهية جيدًا (مثل الحمص أو العدس). ويساعده ذلك أيضًا على التركيز. لكن تذكّري أنه سيضع في فمه كل شيء صغير يعثر عليه، لذا احرصي دائمًا على خلو الأرض من الأغراض الصغيرة الخطرة.') WHERE id = 'fda4720c-d3a0-4bf6-82ad-06eddb719108';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبحت ذاكرة طفلكِ قوية بما يكفي لتحتفظ بأحداث وقعت قبل عدة أيام. وقد يتذكر المكان الذي أُخفيت فيه لعبته المفضلة. العبي معه ألعاب اختباء أكثر تعقيدًا. على سبيل المثال، أخفي اللعبة تحت غطاء وراقبيه وهو يعثر عليها. فهذا ينمّي تفكيره المنطقي وفهمه أن الأشياء لا تختفي، بل تكون مخفية فحسب (ديمومة الأشياء).') WHERE id = '2c349583-ad28-47b1-aaec-34168c563082';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تزداد سرعة المشي مع الاستناد (cruising). قد يتحرك طفلكِ بسرعة بمحاذاة الأريكة من أحد طرفيها إلى الآخر. لا تُلبسيه حذاءً في هذه المرحلة. فالحركة حافي القدمين أو مرتديًا جوارب مانعة للانزلاق مثالية لتشكّل باطن القدم وأصابعها بصورة سليمة. وكلما شعر بملمس الأرض، تمكن من الحفاظ على توازنه بصورة أفضل.') WHERE id = 'e21e8596-3f21-4200-9b5c-b7f1ca90251a';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'قد تؤثر حكة اللثة وألمها أثناء التسنين في نوم رضيعكِ ليلًا. إذا كان رضيعكِ مضطربًا أثناء نومه، فدلّكي لثته برفق بقطعة قماش نظيفة ورطبة وباردة. ومن الطبيعي أيضًا أن تقل شهيته خلال فترة التسنين؛ فلا تجبريه على الأكل، وقدّمي له المزيد من السوائل وحليب الأم/الحليب الصناعي. حنانكِ هو أقوى مسكّن لآلامه.') WHERE id = 'c0bb1b1a-709a-4043-a236-fe5cfd9ea7eb';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تهانينا، لقد أكمل طفلكِ 260 يومًا! أصبح الآن يتعرّف دائمًا إلى اسمه ويلتفت نحوكِ فور مناداته. كما بات يميّز أفراد الأسرة بوضوح عن الآخرين، ويُظهر ارتباطًا مميزًا بكِ. خصّصي اليوم وقتًا «لقراءة كتاب» معه على الأرض؛ دعيه يشير إلى الصور، وأخبريه بأسمائها. أنتِ معلّمته وبطلته الأكثر ثقة، يا أمي!') WHERE id = '122b28c9-a9e8-422e-9381-d9406e97f79b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'ندخل الآن الأيام العشرة الأخيرة من الشهر التاسع. أصبح طفلكِ قادرًا، أثناء الوقوف، على رفع إحدى يديه عن الأريكة ومدّ الأخرى نحو لعبة. وهذا يوضح مدى تطور إحساسه بالتوازن. خلال هذه الفترة، تأكدي من وجود قطع أثاث ثابتة حوله يمكنه التمسك بها. فهو يختبر قوته الآن، وسيجمع قريبًا شجاعته ليخطو أولى خطواته مستقلًا.') WHERE id = '4ac0d7bc-e3ee-464a-a0d8-d71c88bce550';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'إنجاز جديد في «المهارات الحركية الدقيقة» لدى طفلكِ: أصبح الآن يستمتع كثيرًا بإصدار الأصوات عبر ضرب غرضين معًا في الوقت نفسه. ويتطلب ذلك عمل كلتا يديه بتناسق. أعطيه مكعبين خشبيين أو وعاءين بلاستيكيين، وراقبي كيف يقرعهما معًا. تعزز هذه الحركة البسيطة حاسة السمع لديه وقدرته على التخطيط للحركة (التخطيط الحركي). ويمكنكِ جعل هذه اللعبة أكثر متعة باستخدام الإيقاعات الموسيقية.') WHERE id = 'fddb995c-a311-44d6-a424-3f063a465828';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التنويع في التغذية: إذا لم تكوني قد جرّبتِ ذلك بعد، فهذا هو الوقت المناسب لإضافة قطع صغيرة وطرية من الفاكهة إلى نظامه الغذائي مع الجبن القريش أو الزبادي. أصبحت حركات المضغ لدى طفلكِ الآن أكثر انتظامًا. إن تقديم الطعام له في صورة قطع صغيرة بدلًا من هرسه تمامًا يساعد على تقوية لثته واستعداده مستقبلًا لتناول طعام الأسرة. أتيحي له فرصة تناول الطعام بنفسه، فهذا يعزز ثقته بنفسه.') WHERE id = 'b230cf28-523f-407d-9888-06b6c53bb3a6';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحلة «التقليد» في التواصل الاجتماعي: أصبح طفلكِ قادرًا على تقليد تعابير وجهكِ والأصوات التي تصدرينها، بل وحتى عطستكِ. إنه يراقبكِ بعناية ويتعلم منكِ. قومي بحركات مختلفة أمامه (مثل إخراج لسانكِ أو الرمش بعينيكِ)، ولنرَ هل سيقلّدكِ! تُعد مهارة التقليد هذه إحدى أقوى وسائل تكيفه الاجتماعي وقدرته على التعلم.') WHERE id = '671adb79-58b3-4617-94e4-bb4071a9a5ba';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح مفهوم "بقاء الأشياء" مكتملًا الآن. يعرف طفلكِ أن اللعبة لم تختفِ إذا أخفيتِها في جيبكِ، بل إنها ما زالت موجودة فيه. سيبحث عنكِ ويشدّ جيبكِ. يدرّب ذلك ذاكرته وينمّي تفكيره المنطقي. العبي معه لعبة "الغميضة" بطرق أكثر تعقيدًا؛ فهذا يساعد أيضًا على تخفيف قلق الانفصال لديه.') WHERE id = '6997dc99-18bc-4bdc-bae3-c34fc9c367dc';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'عزّزي عادة شرب الماء من الكوب. يتعلم طفلكِ الآن التحكم في كمية الماء أثناء محاولته إمساك الكوب وتقريبه من فمه. قد ينسكب نصف الماء على ملابسه في البداية، فلا تقلقي. الشرب من كوب مفتوح مهم جدًا للنمو السليم لعضلات اللسان والشفتين. وتمهّد هذه المهارة لزيادة وضوح نطقه مستقبلًا. تحلّي بالصبر، فهذه عملية تعلّم.') WHERE id = '85d33873-230f-4ec2-aeb2-c03aab1bc8c9';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ أسرع بكثير في المشي مستندًا إلى الأثاث (cruising). فهو يتحرك بمحاذاة الأريكة كما لو كان يركض. راجعي مجددًا تدابير السلامة في المنزل خلال هذه المرحلة. فقد أصبحت زوايا الأثاث الحادة ومفارش الطاولات المتدلية والأسلاك الكهربائية الممتدة على الأرض تشكّل خطرًا أكبر. يرغب طفلكِ في شدّ كل شيء وجذبه نحوه. وستتيح له البيئة الآمنة التطور من دون كبح شغفه بالاستكشاف.') WHERE id = '6cb85c30-34e6-4f9c-a6d7-47b0e62b9c27';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحلة "الرطانة" في تطور اللغة: أصبح طفلكِ الآن يروي "قصصًا" طويلة بلغته الخاصة. ورغم أنكِ لا تفهمين كلماته، فإنه يقلّد نبرة حديث البالغين بإتقان. أنصتي إليه باهتمام، واطرحي عليه أسئلة، وأجيبيه قائلةً: "حقًا؟ وماذا حدث بعد ذلك؟" يعزّز هذا "الحوار" رغبته في التعبير عن نفسه ويثري حصيلته اللغوية في الدماغ.') WHERE id = '56798677-523b-4029-94dd-1e80eef243c7';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'قد تؤثر حكة اللثة وألمها أثناء التسنين في نوم طفلكِ ليلًا. إذا كان طفلكِ مضطربًا أثناء نومه، فدلّكي لثته برفق بقطعة قماش نظيفة ورطبة وباردة. ومن الطبيعي أيضًا أن تقل شهيته خلال فترة التسنين؛ فلا تجبريه على الأكل، وقدّمي له مزيدًا من السوائل وحليب الأم أو الحليب الصناعي. حنانكِ هو أقوى مسكّن لألمه.') WHERE id = '953f792e-f8bd-44cc-a2d0-c3b8471c1a51';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تهانينا، لقد أتممنا 9 أشهر! أصبح طفلكِ الآن يتعرّف دائمًا إلى اسمه، ويلتفت نحوكِ فور مناداته. كما أصبح يميّز أفراد أسرته بوضوح عن الآخرين، ويُظهر تعلّقًا خاصًا بكِ. خصّصي اليوم وقتًا "لقراءة كتاب" معه على الأرض؛ دعيه يشير إلى الصور، واذكري له أسماءها. أنتِ معلمته وبطلته الأكثر ثقة، يا أمي!') WHERE id = 'b5fee624-3a8a-4073-bf22-e9bf23545a25';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحبًا بكِ في الشهر العاشر! يمكن اعتبار هذا الشهر شهر "إعلان استقلال" طفلكِ. فقد أصبح يقف بثقة أكبر مستندًا إلى الأثاث، بل ويحاول البقاء من دون دعم لبضع ثوانٍ. لحظات التوازن القصيرة هذه تبشّر بخطواته الأولى. وفّري له مساحة واسعة وآمنة. وتذكّري أن كل سقطة تعلّمه قوة الجاذبية وكيفية التحكم في جسمه. فقط ابقي بجانبه وشجّعيه.') WHERE id = '162ad9af-c711-43da-b203-5c312cf418b0';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبحت كلمات مثل "ماما" و"بابا" و"باي باي" في كلام طفلكِ تحمل معنى واضحًا. فإذا نظر إليكِ أو إلى والده عند نطقها، فهذا يعني أنه أصبح يربط الكلمة بالشخص أو الشيء المقصود. وعندما تجيبينه، استخدمي جملًا بسيطة وواضحة. فعلى سبيل المثال، عندما يقول "كرة"، قولي له: "نعم، هذه كرة حمراء" لإثراء مفرداته. فكل إجابة منكِ تنشئ روابط لغوية جديدة في دماغه.') WHERE id = 'be8f3e1a-5335-4ace-960c-562783ff9dcb';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحلة جديدة في التغذية: تطورت "قبضة الملقط" (pincer grasp) لدى طفلكِ إلى حدٍّ يمكّنه من التقاط حبة بازلاء صغيرة أو شريحة جزر مطهية جيدًا ووضعها في فمه بمفرده. امنحيه مزيدًا من الفرص ليأكل بنفسه. فهذا يعزّز مهاراته الحركية وقدرته على تنظيم شعوره بالشبع بنفسه. لا تخشي اتساخ المكان من حوله؛ فهذه "الفوضى الإبداعية" مهمة لنموه.') WHERE id = '58ffad0f-55f8-47af-b047-3975e8528016';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ بارعًا في تقليدكِ. فعندما تتحدثين عبر الهاتف، يمسك هو أيضًا شيئًا ويضعه على أذنه، وعندما تمشّطين شعركِ، يقوم بحركة مشابهة. هذه مرحلة "التقليد الوظيفي". ادعمي هذه المهارة بتقديم أدوات منزلية آمنة له، مثل مشط بلاستيكي أو هاتف لعبة أو ملعقة خشبية. إنه يتعلّم عن العالم من خلال مراقبتكِ، لذا حاولي أن تكون تصرفاتكِ قدوة حسنة له.') WHERE id = 'a6c8ab18-10f6-4956-855e-8fca749308ef';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لعبة "دوام وجود الأشياء": أصبح طفلكِ يعرف الآن أن اللعبة لا تختفي إذا وضعتِها داخل وعاء وغطّيتِها. العبي معه ألعاب اختباء أكثر تعقيدًا. على سبيل المثال، أخفي اللعبة تحت واحد من غطاءين مختلفين وراقبيه وهو يعثر عليها. فهذا يقوّي ذاكرته وقدرته على تركيز انتباهه. وعندما ينجح في حل المسألة، امدحيه بحماس.') WHERE id = '535f32b7-37dd-475b-9f52-55c5a1160920';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح المشي بالاستناد إلى الأثاث (cruising) تلقائيًا تمامًا. وقد يتحرك طفلكِ بسرعة من أحد طرفي الغرفة إلى الآخر ممسكًا بالأريكة. في هذه المرحلة، أعيدي التحقق من سلامة المنزل: فأغطية الطاولات المتدلية، والأسلاك الكهربائية على الأرض، والزوايا الحادة أصبحت تشكّل خطرًا أكبر. فهو يرغب في شدّ كل شيء نحوه والتسلّق. وتمنحه البيئة الآمنة فرصة للاستكشاف بحرية.') WHERE id = 'd10583a3-e400-4339-b85b-3d395175b72a';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'إيماءات جديدة في التواصل الاجتماعي: أصبح طفلكِ الآن يشير بإصبعه إلى الشيء الذي يريده. وهذه قفزة كبيرة في تطوره الإدراكي، فهو يريد مشاركة انتباهه معكِ. عندما يشير إلى شيء ما، اذكري اسمه فورًا: "نعم، هذا طائر! انظري، الطائر يطير". يساعد ذلك على إثراء حصيلته اللغوية وتقوية الرابط العاطفي بينكما. من المهم جدًا أن تتفاعلي مع اهتمامه ولا تتجاهليه.') WHERE id = '1c394285-7074-4a0d-ac82-eab79473970a';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'طوّري مهارة طفلكِ في شرب الماء من الكوب. لقد أصبح الآن أقرب إلى إمساك الكوب بكلتا يديه والحفاظ على توازنه. قدّمي له كمية قليلة من الماء في كوب صغير مصنوع من البلاستيك أو السيليكون. انسكاب الماء جزء من عملية التعلم. الشرب من كوب مفتوح أنفع من زجاجة الرضاعة ذات الحلمة لنمو عضلات اللسان والشفتين نموًا سليمًا، كما يساعد على أن يصبح نطقه أوضح مستقبلًا.') WHERE id = '863feabb-ad16-4aad-8a94-087f99977902';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'إذا استمرت مرحلة التسنين، فقد يضطرب نوم طفلكِ وشهيته مجددًا. في الشهر العاشر، تظهر عادةً القواطع الجانبية العلوية أو السفلية. إذا كانت لثته تزعجه كثيرًا، فأعطيه عضّاضات مبردة، ولكن غير مجمدة، أو شرائح خضراوات باردة تحت إشرافكِ. قدّمي له مزيدًا من السوائل وحليب الأم خلال هذه الفترة، فهذا يحافظ على ترطيب جسمه ويساعد على تهدئته. حنانكِ هو أفضل مسكّن للألم.') WHERE id = '22dd56cb-e699-4f81-b502-66f9d54e2b23';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تهانينا، لقد أكملنا 280 يومًا! أصبح طفلكِ الآن يعرف اسمه ويستجيب بوضوح كلما ناديتِه. كما بات قادرًا على اختيار لعبته أو شخصه المفضل، وبدأ يُظهر "شخصيته" الخاصة. استلقي معه اليوم على الأرض والعبا ببساطة لعبة "التقليد"؛ دعيه يُصدر صوتًا وكرريه أنتِ، ثم صفّقي بيديكِ ودعيه يقلدكِ. أنتِ المرفأ الأكثر أمانًا له وهو يكتشف العالم، يا أمي!') WHERE id = '71654afe-3791-4e59-a41c-7da09d0ef29c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'لقد وصلتما الآن إلى منتصف الشهر العاشر تمامًا! أصبح طفلكِ ماهرًا في الوقوف مستندًا إلى الأشياء، بل ويحاول ترك يديه والوقوف مستقلًا لبضع ثوانٍ. وهذا يدل على مدى تطور قدرته على التوازن وقوة عضلات ساقيه. لا تضغطي عليه ليقف بمفرده، بل دعيه يخطو هذه الخطوة عندما يشعر بأنه مستعد. أنشئي له "ساحة" آمنة محاطة بوسائد ناعمة كي لا يخاف من السقوط.') WHERE id = '03d76f01-bcab-4644-9f10-2526c187201c';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحلة جديدة في تطور كلام طفلكِ: المناغاة الشبيهة بالكلام! إنه يصدر مقاطع طويلة ذات نبرات مختلفة ومفعمة بالمشاعر، كما لو كان يشرح لكِ شيئًا. ورغم أنكِ لا تفهمين أي كلمة بعد، فإن ذلك يشكّل أساس كلامه في المستقبل. أنصتي إليه باهتمام وأجيبي: "حقًا؟ هذا ممتع جدًا، وماذا حدث بعد ذلك؟". تعزز هذه الحوارات رغبته في التعبير عن نفسه، وتُثري حصيلته اللغوية في الدماغ بسرعة.') WHERE id = 'e6d2e0ec-fef4-4fdf-bd36-60be17d3ab5e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أكملي الانتقال إلى قوامات مختلفة في التغذية. ينبغي الآن أن تكون مرحلة الطعام المهروس قد انتهت تمامًا. قدّمي الطعام بعد هرسه بالشوكة فقط، أو على شكل قطع صغيرة وطرية يمكن تناولها باليد (finger foods). أصبحت لثتا طفلكِ الآن قويتين بما يكفي لهرس اللحم أو الخضراوات المطهوة جيدًا والطرية. يساعد ذلك على تعزيز مهارة المضغ والوقاية من مشكلات "انتقائية الطعام" مستقبلًا. تحلّي بالصبر، فكل قوام جديد هو تجربة تعلّم.') WHERE id = '25d3da74-5500-488e-93bc-4e022b9fdf57';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مهارة "تبادل الأدوار" في الألعاب الاجتماعية: أصبح طفلكِ يفهم الآن لعبة "أعطني" و"سأعطيك" بصورة أفضل. ناوليه لعبة، ثم اطلبيها منه قائلة: "الآن أعطني الكرة". وإذا أعطاكِ إياها، فامتدحيه بحماس. تشكّل هذه اللعبة أساس فهمه للمشاركة وقواعد التواصل المتبادل. كما تساعده على إتقان التناسق بين اليد والعين ومهارة إفلات الأشياء (release).') WHERE id = '639df12e-60c1-4322-9712-2375f1060042';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"الفئات" في التطور المعرفي: بدأ طفلكِ الآن يميّز بين الأشياء المتشابهة. فمثلًا، بات قريبًا من فهم أن الكرات ذات الأشكال المختلفة كلها تُسمّى "كرة". أريه كرات أو مكعبات بألوان وأحجام مختلفة. تمثّل هذه الخطوة بداية التفكير المجرّد لديه. وأثناء اللعب معه، اذكري لون الأشياء وشكلها بصوت واضح: "هذه سيارة كبيرة، وهذه سيارة صغيرة".') WHERE id = '4207275f-8c9b-455a-be42-c07fcdc66c91';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح طفلكِ الآن يتقن تمامًا "قبضة الكماشة" (pincer grasp). فهو يلتقط حتى أصغر فتات يراه على الأرض مستخدمًا الإبهام والسبابة. ولتطوير هذه المهارة أكثر، قدّمي له حبات عدس مطهوة جيدًا أو قطعًا صغيرة وطرية من الجبن القريش. انتبهي: تعني هذه المهارة أيضًا أنه يستطيع أن يضع في فمه بالبراعة نفسها أي جسم صغير وخطِر يجده، مثل الأزرار أو الخرز. الحفاظ على نظافة المنزل وخلوّه من الأجسام الصغيرة أهم الآن من أي وقت مضى.') WHERE id = 'd9053aab-2643-4a33-bd40-377294e7163f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'أصبح تنقّل طفلكِ مستندًا إلى الأثاث (cruising) سريعًا لدرجة أنه يكاد يركض بمحاذاة الأريكة. في هذه المرحلة، تحقّقي مجددًا من ثبات أثاث المنزل. فهو يرغب في التسلق على كل شيء عبر الإمساك به وشدّ نفسه إلى أعلى. أزيلي أغطية الطاولات المتدلية، لأنه إذا حاول الإمساك بها للنهوض، فقد يُسقط كل ما عليها فوقه. تعزّز البيئة الآمنة ثقته بنفسه وتتيح له الاستكشاف دون خوف.') WHERE id = '22ae7b1e-0f5e-4f2c-a0b9-f363eec03221';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الوعي بالذات: بدأ طفلكِ الآن يدرك أن الانعكاس في المرآة هو صورته. فإذا وضعتِ علامة صغيرة ملوّنة على أنفه وجعلتِه ينظر في المرآة، فسيحاول مسحها عن وجهه (وهذا ما يُسمّى "اختبار أحمر الشفاه"). يدل ذلك على تطور وعيه بذاته (self-awareness). قفي معه أمام المرآة وأشيري إلى الاختلافات قائلة: "هذا أنفك، وهذا أنف أمك". كما يُعدّ هذا تمرينًا ممتازًا لتكوين وعيه بصورة جسده.') WHERE id = 'aee72c71-4ab2-40ae-a72a-f441c99bcf9d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'قد يظهر «قلق الانفصال» مجددًا أثناء النوم ليلًا. وقد يبكي رضيعكِ فورًا إذا استيقظ ولم يجدكِ. ولطمأنته، اذهبي إليه وربّتي عليه بهدوء من دون إضاءة الغرفة، واهمسي له: «ماما هنا، نم». لا تتعجلي في حمله وإخراجه من الغرفة فورًا؛ دعيه يشعر بوجودكِ ويحاول العودة إلى النوم بنفسه. سيساعدكِ صبركِ على اجتياز هذه المرحلة بسهولة أكبر.') WHERE id = '807f6974-949a-4673-9e12-ca050a097e4d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تهانينا، لقد أكملنا ٢٩٠ يومًا! بدأ طفلكِ يُظهر شخصيته وطباعه بوضوح: ما يحبه، وما يخاف منه، والطعام الذي يفضله... استلقي اليوم معه على الأرض والعبا معًا لعبة يقودها هو. دعيه «يوجّهكِ»، فيعطيكِ اللعبة أو يقلّدكِ. كل دقيقة تقضينها معه هي حجر أساس لسعادته في المستقبل. لقد قطعتِ شوطًا رائعًا يا أمي!') WHERE id = '2489cf6a-6c9a-4826-ac80-afae063dcb86';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحبًا بكِ في الأيام العشرة الأخيرة من الشهر العاشر! هل يمشي طفلكِ بثقة عندما تمسكين بإحدى يديه، أم أنه لا يزال لا يجرؤ على الوقوف من دون دعم؟ كلتا الحالتين طبيعيتان. يبدأ بعض الأطفال المشي في الشهر العاشر، بينما ينتظر آخرون حتى عمر ١٥-١٦ شهرًا. دعيه يقضي وقتًا أطول على الأرض لتقوية عضلات ساقيه. وما إن يثق بقدراته، حتى يفاجئكِ بخطوته المستقلة الأولى!') WHERE id = '96dedeae-65fd-4082-8b02-077d47cad21d';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تطور مفهوم «بقاء الأشياء» لدى طفلكِ إلى درجة أنه لا يملّ من وضع غرض داخل صندوق ثم إخراجه منه. تعزز لعبة «الإدخال والإخراج» هذه إدراكه المكاني ومهاراته الحركية الدقيقة معًا. قدّمي له أوعية بأحجام مختلفة وأغراضًا آمنة يمكنه وضعها داخلها. هذا التمرين البسيط هو أساس قدرته مستقبلًا على حل المهام المعقدة.') WHERE id = 'a8043f3c-dcb0-41ac-858a-58401aab3cc0';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'قفزة جديدة في تطور الكلام: أصبح طفلكِ يربط بعض الكلمات أو الأصوات بأحداث محددة. فمثلًا، قد يقول «بابا» عندما يرن جرس الباب، أو يصدر صوتًا معينًا عندما يشعر بالجوع. هذه بداية الكلام الواعي. استجيبي باهتمام لكل محاولة صوتية منه: «نعم، رن جرس الباب، بابا قادم!». تساعد «ترجماتكِ» هذه على ترسيخ معاني الكلمات تمامًا في دماغه.') WHERE id = '7f7f52b6-f75a-4125-9bb5-a72c5365ce29';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'التنويع في الغذاء: يمكنكِ الآن إضافة كميات صغيرة جدًا من الحبوب الكاملة المطهية جيدًا، أو المعكرونة الطرية، أو لبّ الخبز إلى نظام طفلكِ الغذائي. يساعده ذلك على استكشاف قوامات مختلفة وتحسين مهارة المضغ لديه. تذكّري أننا ما زلنا لا نضيف الملح أو السكر إلى طعامه. فالنكهات الطبيعية هي الأفضل لنمو براعم التذوق لديه على نحو سليم.') WHERE id = 'b9f43156-8bbe-4d46-a470-47337a11cf3a';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تبدأ مرحلة "أنا بنفسي!". أثناء تناول الطعام، يزداد إصرار طفلكِ على أخذ الملعقة من يدكِ أو تناول الطعام بيديه مباشرةً. لا تكبتي رغبته في الاستقلال. دعي يديه تتسخان ووجهه يتلطخ بالهريس. فهذه العملية تعزز ثقته بنفسه وتساعده على بناء علاقة إيجابية مع الطعام. صبركِ اليوم يمهد لأن يصبح مستقبلًا طفلًا مستقلًا يتمتع بشهية جيدة.') WHERE id = 'b31abab7-200d-4d55-b197-62b606e68100';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'المهارات الاجتماعية: أصبح طفلكِ قادرًا على تقليد إيماءات مثل "مع السلامة" (التلويح باليد) أو "إرسال قبلة" (قبلة في الهواء). هذه الإيماءات هي من أشكال التواصل التي تسبق الكلام. فإذا لوّحتِ بيدكِ وقلّدكِ، فهذا يدل على تعلقه بكِ وانتباهه إليكِ. اجعلي هذه الحركات أكثر متعة بدمجها مع الأغاني. وتفاعلي بفرح مع كل إيماءة يقوم بها، حتى يزداد حماسه للتواصل.') WHERE id = 'db90e8f1-9d73-4d53-8169-2122571f4a13';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحلة جديدة من الأمان: أصبح طفلكِ يميل الآن إلى التسلق إلى الأماكن المرتفعة. فالطاولات المنخفضة وحواف الأرائك تبدو له مثل "القمم". تحققي من ثبات جميع الأغراض الثقيلة وقطع الأثاث في المنزل. وأخفي الأسلاك الكهربائية خصوصًا، لأن شدها قد يكون من أكثر الأشياء إثارة لفضوله. تأمين المنزل يمنحكِ راحة البال، ويمنحه مساحة واسعة وآمنة للاستكشاف.') WHERE id = 'cd4b7de4-c97d-44b4-ae4b-d87984914859';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'النوم ليلًا والتطور المعرفي: قد يبكي طفلكِ بشدة إذا استيقظ ليلًا ولم يجدكِ أمامه. من المهم أن تمنحيه شعورًا بالأمان خلال هذه المرحلة. عندما تذهبين إليه، ربّتي عليه برفق وقولي بصوت هادئ ومن دون تشغيل الضوء: "ماما هنا، نم". لا تتعجلي في حمله ومغادرة الغرفة به فورًا. فمجرد وجودكِ وصوتكِ يمنحانه ما يكفي من الأمان ليعود إلى النوم. إنها مرحلة عابرة من "قلق الانفصال".') WHERE id = 'd5f8c50f-64e6-4aba-ad9f-5604b24fb65b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'غدًا يكمل طفلكِ 300 يوم بالتمام! خلال هذه الأشهر الـ10، قطع رحلة مذهلة؛ فتحوّل من رضيع عاجز يحتاج إلى المساعدة إلى إنسان صغير له شخصيته ورغباته ومهاراته. وأنتِ أيضًا اكتسبتِ خبرة كبيرة خلال هذه الفترة. استلقي اليوم إلى جانبه على الأرض، واكتفي بمشاهدة ضحكته. حبكِ هو أكبر قوة دافعة لنموه وتطوره.') WHERE id = '2638511c-740a-477b-ab58-1fbe5fd5c94a';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'تهانينا! أكمل طفلكِ 300 يوم! إنها آخر محطة مهمة قبل إتمام عامه الأول. أصبح طفلكِ الآن يتعرف إلى اسمه كلما ناديته، ويعبّر عن مشاعره بوضوح، وربما يستعد لاتخاذ خطواته الأولى. احتفلي بهذا اليوم معه بلعبة مميزة أو بتقديم فاكهته المفضلة. لقد أنجزتِ عملًا رائعًا يا أمي! إن ثمرة جهودكِ طوال 300 يوم تتجلى في تلك العينين السعيدتين اللتين تنظران إليكِ كل يوم.') WHERE id = '4dbc6d6a-ae47-4867-ba96-b66058f91a2f';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'مرحبًا بالشهر الحادي عشر! لم يتبقَّ سوى شهرين على عيد ميلاد طفلكِ الأول. في هذه المرحلة، أصبح طفلكِ يفهم الفرق بين "أنا" و"أنتِ" بصورة أفضل. وهو يطوّر ذكاءه العاطفي من خلال تقليد تعابير وجهكِ؛ فعندما تكونين حزينة قد تبدو ملامحه جادة أيضًا، وعندما تضحكين يضحك بصوت عالٍ. تحدّثي معه عن مشاعركِ، فهذا يضع أساسًا متينًا يساعده مستقبلًا على إدارة مشاعره.') WHERE id = '9a834d06-30b3-4c6c-92b2-859a3c7000f4';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'هل يمشي طفلكِ بثقة كبيرة عندما تمسكين بإحدى يديه، أم لا يزال يتنقّل مستندًا إلى حافة الأريكة فقط؟ في هذه الأيام، قد يخطو خطوة أو خطوتين بمفرده وهو يمد ذراعيه إلى الجانبين للحفاظ على توازنه. تساعد حركات "التوازن" هذه على تدريب جهاز التوازن في دماغه (الجهاز الدهليزي). لا تستعجليه، ودعيه يكتسب ثقته بنفسه تمامًا.') WHERE id = 'a31576c9-38ba-4027-9aca-cbc63e6f334a';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, '"التعبير عن الرغبات" في التطور المعرفي: أصبح طفلكِ قادرًا على إفهامكِ ما يريده، ليس بالبكاء فقط، بل أيضًا بالإشارة بإصبعه وإصدار أصوات مميزة. عندما يشير إلى لعبته، أكّدي رغبته بالكلمات قائلة: "نعم، هل تريد هذا الدب؟". يمنحه ذلك شعورًا بأن الآخرين يفهمونه، ويساعد مستقبلًا على الحد من السلوكيات العدوانية، مثل نوبات البكاء الناتجة عن عدم فهمه.') WHERE id = 'aa86788c-ff14-4450-8f10-2208ffcc316b';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'الاستقلالية في تناول الطعام: أصبح طفلكِ يرغب في إمساك الملعقة بنفسه تمامًا وإيصالها إلى فمه. نعم، سينتهي معظم الطعام على الأرض وعلى المريلة، لكن هذا من أهم التدريبات للمهارات الحركية الدقيقة والتنسيق بين اليد والعين. أعطيه ملعقة مريحة له، مصنوعة من السيليكون أو ذات مقبض سميك. ويمكنكِ مساعدته في الوقت نفسه بملعقة أخرى. إنه أشبه بـ"العمل الجماعي"!') WHERE id = '3159f58c-c8a2-418a-a8bd-3b961ca0266e';
UPDATE public.mommy_daily_messages SET message_ar = COALESCE(message_ar, 'حان وقت "أصوات الحيوانات" في تطور الكلام! قد يبدأ طفلكِ الآن بالإجابة بطريقته الخاصة عن أسئلة مثل: "كيف ينبح الكلب؟" و"ما الصوت الذي تصدره القطة؟". تمثل هذه المرحلة ذروة قدرته على تقليد الأصوات. واصلي هذه الألعاب أثناء تصفح الكتب التي تحتوي على صور الحيوانات. يساعد تقليد الأصوات على تهيئة أعضاء النطق، مثل اللسان وعضلات الشفتين، لنطق كلمات أكثر تعقيدًا مستقبلًا.') WHERE id = '43246706-501b-4546-a51a-8e59351b53c5';